describe('auth routes fallback hardening', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    cookieStore.get.mockReturnValue({ value: 'csrf-token' });
    mockGetSessionFromCookie.mockResolvedValue(null);
  });

  it('returns wrapped fallback for unhandled sign-in failures', async () => {
