import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import crypto from 'crypto';
import { createSessionToken, hashPassword, SESSION_COOKIE } from '@/lib/server/auth';
import { checkRateLimit, getRateLimitHeaders, hasValidCsrf, isSameOrigin, CSRF_COOKIE } from '@/lib/server/security';
import { createUser, findUserByEmail } from '@/lib/server/data-layer';
import type { UserRecord } from '@/lib/server/models';
import { withApiRoute } from '@/lib/server/api-route';

export async function POST(req: NextRequest) {
  return withApiRoute(
    {
      method: 'POST',
      path: '/api/auth/signup',
      fallbackMessage: 'Sign-up is temporarily unavailable. Please try again.',
    },
    async () => {
      if (!isSameOrigin(req)) {
        return NextResponse.json({ error: 'Invalid request origin.' }, { status: 403 });
      }

      const rateLimit = checkRateLimit(req, { scope: 'auth-signup', limit: 10, windowMs: 60_000 });
      if (rateLimit.limited) {
        return NextResponse.json(
          { error: 'Too many requests. Try again shortly.' },
          { status: 429, headers: getRateLimitHeaders(rateLimit) }
        );
      }

      const cookieStore = await cookies();
      const csrfCookie = cookieStore.get(CSRF_COOKIE)?.value;
      if (!hasValidCsrf(req, csrfCookie)) {
        return NextResponse.json({ error: 'CSRF validation failed.' }, { status: 403 });
      }

      const body = await req.json().catch(() => ({}));
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
      const password = typeof body.password === 'string' ? body.password : '';

      if (name.length < 2) {
        return NextResponse.json({ error: 'Name must be at least 2 characters.' }, { status: 400 });
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return NextResponse.json({ error: 'Enter a valid email.' }, { status: 400 });
      }
      if (password.length < 8) {
        return NextResponse.json({ error: 'Password must be at least 8 characters.' }, { status: 400 });
      }

      const existing = await findUserByEmail(email);
      if (existing) {
        return NextResponse.json({ error: 'Account already exists for this email.' }, { status: 409 });
      }

      const creds = await hashPassword(password);
      const user: UserRecord = {
        id: crypto.randomUUID(),
        name,
        email,
        passwordHash: creds.hash,
        passwordSalt: creds.salt,
        createdAt: new Date().toISOString(),
      };

      await createUser(user);

      const token = createSessionToken(user.id, user.email, user.name);
      cookieStore.set(SESSION_COOKIE, token, {
        httpOnly: true,
        sameSite: 'lax',
        secure: process.env.NODE_ENV === 'production',
        maxAge: 60 * 60 * 24 * 7,
        path: '/',
      });

      return NextResponse.json({ user: { id: user.id, name: user.name, email: user.email } });
    }
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import crypto from 'crypto';
import { getSessionFromCookie } from '@/lib/server/auth';
import { validateBody, validateTitle } from '@/lib/server/community';
import { hasValidCsrf, isRateLimited, isSameOrigin, CSRF_COOKIE } from '@/lib/server/security';
import { getAllPosts, createPost } from '@/lib/server/data-layer';
import { sanitizeTitle, sanitizeBody } from '@/lib/sanitizer';
import { logger } from '@/lib/logger';
import type { DiscussionPost } from '@/lib/server/models';

export async function GET() {
  const requestId = crypto.randomUUID();
  logger.logRequest('GET', '/api/community', requestId);

  try {
    const posts = await getAllPosts();
    const sorted = [...posts].sort(
      (a, b) => +new Date(b.createdAt) - +new Date(a.createdAt)
    );

    logger.logResponse('GET', '/api/community', 200, 0, requestId);
    return NextResponse.json({ posts: sorted });
  } catch (error) {
    logger.error('Failed to fetch community posts', error as Error, {}, requestId);
    return NextResponse.json(
      { error: 'Failed to load community posts' },
      { status: 500 }
    );
  }
}

export async function POST(req: NextRequest) {
  const requestId = crypto.randomUUID();
  logger.logRequest('POST', '/api/community', requestId);

  if (!isSameOrigin(req)) {
    logger.logSecurity('csrf-fail', { requestId, reason: 'invalid-origin' });
    return NextResponse.json({ error: 'Invalid request origin.' }, { status: 403 });
  }

  if (isRateLimited(req, { scope: 'community-post', limit: 20, windowMs: 60_000 })) {
    logger.logSecurity('rate-limit', { requestId, endpoint: '/api/community' });
    return NextResponse.json({ error: 'Too many requests. Try again shortly.' }, { status: 429 });
  }

  const cookieStore = await cookies();
  const csrfCookie = cookieStore.get(CSRF_COOKIE)?.value;
  if (!hasValidCsrf(req, csrfCookie)) {
    logger.logSecurity('csrf-fail', { requestId });
    return NextResponse.json({ error: 'CSRF validation failed.' }, { status: 403 });
  }

  const session = await getSessionFromCookie();
  if (!session) {
    logger.logAuth('signin', undefined, false, 'not-authenticated');
    return NextResponse.json({ error: 'Sign in required to post.' }, { status: 401 });
  }

  const body = await req.json().catch(() => ({}));
  const rawTitle = typeof body.title === 'string' ? body.title.trim() : '';
  const rawText = typeof body.text === 'string' ? body.text.trim() : '';

  // Sanitize inputs to prevent XSS
  const title = sanitizeTitle(rawTitle);
  if (!title) {
    logger.warn('Invalid post title', { requestId, userId: session.uid });
    return NextResponse.json(
      { error: 'Title must be between 3 and 200 characters' },
      { status: 400 }
    );
  }

  const text = sanitizeBody(rawText);
  if (!text) {
    logger.warn('Invalid post body', { requestId, userId: session.uid });
    return NextResponse.json(
      { error: 'Description must be between 10 and 5000 characters' },
      { status: 400 }
    );
  }

  // Additional validation
  const titleError = validateTitle(title);
  if (titleError) {
    return NextResponse.json({ error: titleError }, { status: 400 });
  }

  const bodyError = validateBody(text);
  if (bodyError) {
    return NextResponse.json({ error: bodyError }, { status: 400 });
  }

  const next: DiscussionPost = {
    id: `p-${crypto.randomUUID()}`,
    author: session.name,
    title,
    text,
    likes: 0,
    createdAt: new Date().toISOString(),
    replies: [],
  };

  try {
    await createPost(next);
    logger.logResponse('POST', '/api/community', 201, 0, requestId);
    return NextResponse.json({ post: next });
  } catch (error) {
    logger.error('Failed to create community post', error as Error, { userId: session.uid }, requestId);
    return NextResponse.json(
      { error: 'Failed to create post. Please try again.' },
      { status: 500 }
    );
  }
}

import crypto from 'crypto';
import { NextRequest } from 'next/server';
import { logger } from '@/lib/logger';
import { CONTACT_ROUTE, CONTACT_RATE_LIMIT, type ContactPayload } from '@/lib/server/contact/config';
import { createContactResponse } from '@/lib/server/contact/response';
import { ContactDeliveryError, deliverContactSubmission } from '@/lib/server/contact/service';
import { validateContactPayload } from '@/lib/server/contact/validation';
import { checkRateLimit, getClientIp, isSameOrigin } from '@/lib/server/security';

export async function POST(req: NextRequest) {
  const requestId = crypto.randomUUID();
  logger.logRequest('POST', CONTACT_ROUTE, requestId);

  const rateLimit = checkRateLimit(req, CONTACT_RATE_LIMIT);
  const clientIp = getClientIp(req);

  if (!isSameOrigin(req)) {
    logger.logSecurity('csrf-fail', { requestId, endpoint: CONTACT_ROUTE, reason: 'invalid-origin', clientIp });
    return createContactResponse(
      { error: 'Invalid request origin.' },
      requestId,
      rateLimit,
      { status: 403 }
    );
  }

  if (rateLimit.limited) {
    logger.logSecurity('rate-limit', { requestId, endpoint: CONTACT_ROUTE, clientIp });
    return createContactResponse(
      { error: 'Too many requests. Please wait a minute before trying again.' },
      requestId,
      rateLimit,
      { status: 429 }
    );
  }

  let body: ContactPayload;
  try {
    body = await req.json();
  } catch {
    logger.warn('Invalid contact request body', { requestId, endpoint: CONTACT_ROUTE, clientIp });
    return createContactResponse({ error: 'Invalid request.' }, requestId, rateLimit, { status: 400 });
  }

  const validation = validateContactPayload(body);

  if (validation.kind === 'spam') {
    logger.logSecurity('xss-attempt', {
      requestId,
      endpoint: CONTACT_ROUTE,
      clientIp,
      reason: 'honeypot-filled',
    });
    return createContactResponse({ success: true }, requestId, rateLimit);
  }

  if (validation.kind === 'invalid') {
    logger.warn('Invalid contact submission', {
      requestId,
      endpoint: CONTACT_ROUTE,
      clientIp,
      reason: validation.error,
    });
    return createContactResponse(
      { error: validation.error },
      requestId,
      rateLimit,
      { status: 400 }
    );
  }

  try {
    const delivery = await deliverContactSubmission(validation.submission);

    if (delivery.kind === 'logged') {
      logger.info(
        'Contact form submitted without RESEND_API_KEY; logging only',
        {
          to: delivery.recipient,
          from: delivery.submission.email,
          name: delivery.submission.name,
          persona: delivery.submission.persona,
          message: delivery.submission.message,
        },
        requestId
      );
    }

    logger.logResponse('POST', CONTACT_ROUTE, 200, 0, requestId);
    return createContactResponse({ success: true }, requestId, rateLimit);
  } catch (error) {
    if (error instanceof ContactDeliveryError) {
      logger.error(
        'Resend API rejected contact submission',
        error,
        { endpoint: CONTACT_ROUTE, responseBody: error.responseBody, statusCode: error.statusCode },
        requestId
      );
      return createContactResponse(
        { error: 'Could not send message right now. Please try again shortly.' },
        requestId,
        rateLimit,
        { status: 502 }
      );
    }

    const normalizedError = error instanceof Error ? error : new Error('Unknown contact delivery failure');

    logger.error('Contact route fetch error', normalizedError, { endpoint: CONTACT_ROUTE }, requestId);
    return createContactResponse(
      { error: 'Network error. Please try again.' },
      requestId,
      rateLimit,
      { status: 500 }
    );
  }
}

import { revalidatePath } from 'next/cache';
import { NextRequest, NextResponse } from 'next/server';
import { runKwinSeoAgencyJob } from '@/lib/seo-agency/job';
import { getSeoAgencyPersistenceDiagnostics } from '@/lib/seo-agency/store';
import { getLatestSeoAgencyRun } from '@/lib/seo-agency/store';
import { beginSchedulerHeartbeat, completeSchedulerHeartbeat, recordVerification } from '@/lib/operations/verification-repository';
import { VERIFICATION_POLICIES } from '@/lib/operations/verification-policy';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300;

function isAuthorized(request: NextRequest): boolean {
  const secret = process.env.CRON_SECRET;
  if (secret) {
    return request.headers.get('authorization') === `Bearer ${secret}`;
  }

  if (process.env.NODE_ENV !== 'production') {
    return true;
  }

  return request.headers.get('user-agent') === 'vercel-cron/1.0';
}

export async function GET(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ success: false, error: 'Unauthorized cron request.' }, { status: 401 });
  }

  const startedAt = Date.now();
  const startedAtIso = new Date(startedAt).toISOString();
  const provider = request.headers.get('x-kwin-trigger-provider') === 'github_actions'
    ? 'github_actions' as const
    : request.headers.get('user-agent') === 'vercel-cron/1.0'
      ? 'vercel_cron' as const
      : 'manual' as const;
  const requestedInvocationId = request.headers.get('x-github-run-id');
  const invocationId = requestedInvocationId && /^[a-zA-Z0-9._:-]{1,120}$/.test(requestedInvocationId)
    ? requestedInvocationId
    : crypto.randomUUID();
  const heartbeatKey = `seo-refresh:${provider}:${invocationId}`;
  await beginSchedulerHeartbeat({ idempotencyKey: heartbeatKey, provider, scheduleId: 'kwin-seo-agency-daily', invocationId });
  const result = await runKwinSeoAgencyJob();

  revalidatePath('/seo-agency');
  revalidatePath(`/seo-agency/articles/${result.run.dailyArticle.slug}`);
  revalidatePath(`/seo-agency/articles/${result.run.dailyArticle.slug}/instagram-image`);
  revalidatePath('/sitemap.xml');
  revalidatePath('/feed.xml');

  const persistedRun = result.storageBackend === 'supabase' ? await getLatestSeoAgencyRun() : null;
  const postWriteVerified = persistedRun?.id === result.run.id;
  const contentOutcome = result.liveInputStatus === 'live' && result.storageBackend === 'supabase' && postWriteVerified
    ? 'passed' as const
    : 'partial' as const;
  let evidenceAttemptId: string | null = null;
  let evidenceQualified = false;
  let evidenceWarning: string | undefined;
  try {
    const evidence = await recordVerification({
      // A daily run ID is intentionally stable, but each scheduler invocation
      // is a separate evidence attempt. The invocation ID remains stable for
      // GitHub job retries, preserving safe idempotency without cross-run collisions.
      idempotencyKey: `content:${provider}:${invocationId}`,
      suite: 'content_refresh', outcome: contentOutcome,
      policyVersion: VERIFICATION_POLICIES.content_refresh.version,
      startedAt: startedAtIso, completedAt: new Date().toISOString(),
      commitSha: process.env.VERCEL_GIT_COMMIT_SHA?.toLowerCase(),
      environment: process.env.VERCEL_ENV === 'production' ? 'production' : process.env.NODE_ENV === 'production' ? 'preview' : 'development',
      provider, providerRunId: result.run.id, trigger: provider === 'vercel_cron' ? 'schedule' : 'request',
      controls: [
        { id: 'authorization', required: true, outcome: 'passed' },
        { id: 'source-health', required: true, outcome: result.liveInputStatus === 'live' ? 'passed' : 'failed', summary: result.warning },
        { id: 'live-inputs', required: true, outcome: result.liveInputStatus === 'live' ? 'passed' : 'failed', metrics: { signalCount: result.run.newsSignals.length } },
        { id: 'content-validation', required: true, outcome: 'passed' },
        { id: 'supabase-persistence', required: true, outcome: result.storageBackend === 'supabase' ? 'passed' : 'failed' },
        { id: 'post-write-read', required: true, outcome: postWriteVerified ? 'passed' : 'failed' },
      ],
      manifest: { runId: result.run.id, runDate: result.run.runDate, storageBackend: result.storageBackend, liveInputStatus: result.liveInputStatus },
      failureCode: contentOutcome === 'partial' ? 'content-refresh-not-qualified' : undefined,
      failureSummary: contentOutcome === 'partial' ? (result.warning ?? 'Live input or durable persistence qualification failed.') : undefined,
    });
    evidenceAttemptId = evidence.attempt.id;
    evidenceQualified = evidence.attempt.qualified;
  } catch (error) {
    evidenceWarning = error instanceof Error ? error.message : 'Evidence recording failed.';
  }
  await completeSchedulerHeartbeat(heartbeatKey, {
    outcome: contentOutcome, durationMs: Date.now() - startedAt,
    failureCode: contentOutcome === 'partial' ? 'content-refresh-not-qualified' : evidenceWarning ? 'evidence-recording-failed' : undefined,
  });

  return NextResponse.json({
    success: true,
    runDate: result.run.runDate,
    generatedAt: result.run.generatedAt,
    storageBackend: result.storageBackend,
    liveInputStatus: result.liveInputStatus,
    warning: result.warning,
    persistence: getSeoAgencyPersistenceDiagnostics(),
    durationMs: Date.now() - startedAt,
    evidence: { attemptId: evidenceAttemptId, qualified: evidenceQualified, warning: evidenceWarning },
    topSignal: result.run.newsSignals[0]
      ? {
          title: result.run.newsSignals[0].title,
          source: result.run.newsSignals[0].source,
          relevanceScore: result.run.newsSignals[0].relevanceScore,
        }
      : null,
    publishingReadiness: result.run.publishingReadiness,
    publishAttempts: result.run.publishAttempts,
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { getSupabaseAdmin } from '@/lib/server/supabase-client';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

function isAuthorized(request: NextRequest): boolean {
  const secret = process.env.CRON_SECRET;
  if (secret) {
    return request.headers.get('authorization') === `Bearer ${secret}`;
  }

  if (process.env.NODE_ENV !== 'production') {
    return true;
  }

  return request.headers.get('user-agent') === 'vercel-cron/1.0';
}

/**
 * A low-cost, read-only query that gives a Free-tier Supabase project regular
 * database activity and makes configuration failures visible in Vercel logs.
 */
export async function GET(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ ok: false, error: 'Unauthorized cron request.' }, { status: 401 });
  }

  const supabase = getSupabaseAdmin();
  if (!supabase) {
    return NextResponse.json({
      ok: false,
      error: 'Supabase service-role client is not configured.',
    }, { status: 503 });
  }

  const { error } = await supabase
    .from('seo_agency_runs')
    .select('id', { head: true })
    .limit(1);

  if (error) {
    return NextResponse.json({
      ok: false,
      error: 'Supabase heartbeat query failed.',
    }, { status: 503 });
  }

  return NextResponse.json({
    ok: true,
    service: 'supabase',
    mode: 'read-only',
    checkedAt: new Date().toISOString(),
  });
}

import { NextRequest, NextResponse } from 'next/server';
import {
  classifyReaderSourceTier,
  getReaderProvenance,
  parseReaderFeedsFromOpml,
  type ReaderSourceFeed,
} from '@/components/news-reader/source-registry';
import { scoreKwinRelevance } from '@/components/news-reader/kwin-relevance';

type FeedItem = {
  title: string;
  link: string;
  summary: string;
  summarySource: 'publisher-feed' | 'discovery-snippet' | 'unavailable';
  fullContent: string;
  source: string;
  sourceFeedUrl: string;
  sourceTier: 'primary' | 'official' | 'contextual';
  provenance: 'direct-institutional' | 'direct-publisher' | 'source-filtered-discovery' | 'contextual-monitoring';
  authenticity: 'verified-feed' | 'discovery-feed' | 'unverified';
  isKwinRelated: boolean;
  kwinRelevanceScore: number;
  kwinRelevanceReasons: string[];
  publishedAt: string | null;
};

type FeedEntry = ReaderSourceFeed;

type TierBuckets = Record<FeedItem['sourceTier'], FeedItem[]>;

const TIER_ORDER: FeedItem['sourceTier'][] = ['official', 'primary', 'contextual'];
const TIER_TARGET_SHARES: Record<FeedItem['sourceTier'], number> = {
  contextual: 0.2,
  official: 0.5,
  primary: 0.3,
};

const DEFAULT_LIMIT = 36;
const MAX_LIMIT = 100;
const MAX_FEEDS = 32;
const REQUEST_TIMEOUT_MS = 9000;
const CACHE_TTL_MS = 3 * 60 * 1000;
const KWIN_RESERVED_SHARE = 0.4;
const KWIN_FEED_HINTS = /\bkwin(?:\s+city)?\b|knowledge\s*,?\s*well(?:being|ness)\s*(?:and|&)\s*innovation|khir\s+city|ಕ್ವಿನ್\s*ಸಿಟಿ/i;

type ReaderPayload = {
  opmlUrl: string;
  feedCount: number;
  itemCount: number;
  generatedAt: string;
  items: FeedItem[];
  cache: {
    hit: boolean;
    ttlMs: number;
  };
};

type CacheEntry = {
  expiresAt: number;
  payload: ReaderPayload;
};

const SUMMARY_QUALITY: Record<FeedItem['summarySource'], number> = {
  unavailable: 0,
  'discovery-snippet': 1,
  'publisher-feed': 2,
};

const routeCache: Map<string, CacheEntry> = new Map();

function decodeEntities(input: string): string {
  return input
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .trim();
}

function stripHtml(input: string): string {
  return decodeEntities(input)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function summarize(input: string, maxLen = 320): string {
  const clean = stripHtml(input);
  if (!clean) {
    return 'Summary unavailable. Open the original source to read the full article.';
  }
  if (clean.length <= maxLen) {
    return clean;
  }
  return `${clean.slice(0, maxLen).trimEnd()}...`;
}

function buildSummary(title: string, input: string, feedUrl: string): Pick<FeedItem, 'summary' | 'summarySource'> {
  const clean = stripHtml(input);
  const hostname = new URL(feedUrl).hostname.toLowerCase();
  const normalizedTitle = title.replace(/\s+-\s+[^-]+$/, '').toLowerCase().replace(/\W+/g, ' ').trim();
  const normalizedContent = clean.toLowerCase().replace(/\W+/g, ' ').trim();
  const isHeadlineEcho = !clean
    || normalizedContent === normalizedTitle
    || normalizedContent.startsWith(`${normalizedTitle} `)
    || /^https?:\/\//i.test(clean);

  if (hostname === 'news.google.com' && isHeadlineEcho) {
    return {
      summary: 'Content summary is not supplied by this discovery feed. Open the original publisher report for full context.',
      summarySource: 'unavailable',
    };
  }

  return {
    summary: summarize(input),
    summarySource: hostname.endsWith('bing.com') ? 'discovery-snippet' : 'publisher-feed',
  };
}

function unwrapDiscoveryLink(link: string): string {
  try {
    const url = new URL(link);
    if (url.hostname.endsWith('bing.com') && url.pathname.includes('/news/apiclick')) {
      const publisherUrl = url.searchParams.get('url');
      if (publisherUrl && /^https?:\/\//i.test(publisherUrl)) return publisherUrl;
    }
  } catch {
    // Keep the feed link when a provider changes its URL shape.
  }
  return link;
}

function getTagValue(block: string, tags: string[]): string {
  for (const tag of tags) {
    const match = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
    if (match && match[1]) {
      return decodeEntities(match[1]);
    }
  }
  return '';
}

function getAtomLink(block: string): string {
  const alternate = block.match(/<link\b[^>]*rel=["']alternate["'][^>]*href=["']([^"']+)["'][^>]*>/i);
  if (alternate && alternate[1]) {
    return decodeEntities(alternate[1]);
  }
  const generic = block.match(/<link\b[^>]*href=["']([^"']+)["'][^>]*>/i);
  return generic?.[1] ? decodeEntities(generic[1]) : '';
}

function parseDateMaybe(input: string): string | null {
  if (!input) {
    return null;
  }
  const d = new Date(input);
  if (Number.isNaN(d.getTime())) {
    return null;
  }
  return d.toISOString();
}

function compareByPublishedAtDesc(a: FeedItem, b: FeedItem): number {
  const aTime = a.publishedAt ? new Date(a.publishedAt).getTime() : 0;
  const bTime = b.publishedAt ? new Date(b.publishedAt).getTime() : 0;
  return bTime - aTime;
}

function buildTierTargets(limit: number): Record<FeedItem['sourceTier'], number> {
  const rawTargets = TIER_ORDER.map((tier) => {
    const exact = limit * TIER_TARGET_SHARES[tier];
    return {
      tier,
      floor: Math.floor(exact),
      remainder: exact - Math.floor(exact),
    };
  });

  const targets: Record<FeedItem['sourceTier'], number> = {
    contextual: rawTargets.find((entry) => entry.tier === 'contextual')?.floor ?? 0,
    official: rawTargets.find((entry) => entry.tier === 'official')?.floor ?? 0,
    primary: rawTargets.find((entry) => entry.tier === 'primary')?.floor ?? 0,
  };

  let assigned = targets.contextual + targets.official + targets.primary;
  const orderedRemainders = [...rawTargets].sort((a, b) => b.remainder - a.remainder || TIER_ORDER.indexOf(a.tier) - TIER_ORDER.indexOf(b.tier));

  for (const entry of orderedRemainders) {
    if (assigned >= limit) {
      break;
    }
    targets[entry.tier] += 1;
    assigned += 1;
  }

  if (limit > 0 && targets.contextual === 0) {
    targets.contextual = 1;
    if (targets.primary > 0) {
      targets.primary -= 1;
    } else if (targets.official > 0) {
      targets.official -= 1;
    }
  }

  const total = targets.contextual + targets.official + targets.primary;
  if (total > limit) {
    let overflow = total - limit;
    for (const tier of ['primary', 'official', 'contextual'] as const) {
      while (overflow > 0 && targets[tier] > 0) {
        targets[tier] -= 1;
        overflow -= 1;
      }
    }
  }

  return targets;
}

function selectBalancedStories(items: FeedItem[], limit: number): FeedItem[] {
  const buckets: TierBuckets = {
    primary: [],
    official: [],
    contextual: [],
  };

  for (const item of items) {
    buckets[item.sourceTier].push(item);
  }

  for (const tier of TIER_ORDER) {
    buckets[tier].sort(compareByPublishedAtDesc);
  }

  const selected: FeedItem[] = [];
  const targets = buildTierTargets(limit);

  for (const tier of TIER_ORDER) {
    const take = Math.min(targets[tier], buckets[tier].length);
    selected.push(...buckets[tier].splice(0, take));
  }

  while (selected.length < limit) {
    let added = false;
    for (const tier of TIER_ORDER) {
      const item = buckets[tier].shift();
      if (item) {
        selected.push(item);
        added = true;
        if (selected.length >= limit) {
          break;
        }
      }
    }

    if (!added) {
      break;
    }
  }

  return selected.sort(compareByPublishedAtDesc);
}

function selectReaderStories(items: FeedItem[], limit: number): FeedItem[] {
  const kwinLimit = Math.max(1, Math.ceil(limit * KWIN_RESERVED_SHARE));
  const rankedKwinItems = items
    .filter((item) => item.isKwinRelated)
    .sort((a, b) => b.kwinRelevanceScore - a.kwinRelevanceScore || compareByPublishedAtDesc(a, b));
  const kwinItems = rankedKwinItems.slice(0, kwinLimit);
  const selectedLinks = new Set(kwinItems.map((item) => item.link));
  const regionalItems = selectBalancedStories(
    items.filter((item) => !selectedLinks.has(item.link) && !item.isKwinRelated),
    Math.max(0, limit - kwinItems.length),
  );
  const remainingCapacity = limit - kwinItems.length - regionalItems.length;
  const additionalKwinItems = remainingCapacity > 0
    ? rankedKwinItems.slice(kwinItems.length, kwinItems.length + remainingCapacity)
    : [];

  return [...kwinItems, ...additionalKwinItems, ...regionalItems];
}

function isKwinSourceFeed(feedEntry: FeedEntry): boolean {
  const descriptor = decodeEntities([
    feedEntry.title,
    ...feedEntry.groupPath,
    decodeURIComponent(feedEntry.xmlUrl),
  ].join(' '));
  return KWIN_FEED_HINTS.test(descriptor);
}

function parseFeedItems(feedXml: string, feedEntry: FeedEntry, perFeedLimit: number): FeedItem[] {
  const source =
    stripHtml(getTagValue(feedXml, ['channel>title', 'title'])) ||
    new URL(feedEntry.xmlUrl).hostname.replace(/^www\./, '');

  const sourceTier = classifyReaderSourceTier(feedEntry);
  const provenance = getReaderProvenance(feedEntry);
  const authenticity = provenance === 'direct-institutional' || provenance === 'direct-publisher'
    ? 'verified-feed' as const
    : 'discovery-feed' as const;

  const rssItems = feedXml.match(/<item\b[\s\S]*?<\/item>/gi) ?? [];
  const atomEntries = feedXml.match(/<entry\b[\s\S]*?<\/entry>/gi) ?? [];

  const parsed: FeedItem[] = [];
  for (const item of rssItems.slice(0, perFeedLimit)) {
    const title = stripHtml(getTagValue(item, ['title'])) || 'Untitled article';
    const link = unwrapDiscoveryLink(decodeEntities(getTagValue(item, ['link'])));
    const summaryText = getTagValue(item, ['description', 'content:encoded', 'content']);
    const published = parseDateMaybe(getTagValue(item, ['pubDate', 'dc:date', 'published', 'updated']));
    if (!link) {
      continue;
    }
    const fullText = stripHtml(summaryText);
    const summary = buildSummary(title, summaryText, feedEntry.xmlUrl);
    const relevance = scoreKwinRelevance(title, fullText);
    const itemSource = stripHtml(getTagValue(item, ['source', 'News:Source'])) || source;
    parsed.push({
      title,
      link,
      ...summary,
      fullContent: fullText.length > 5000 ? `${fullText.slice(0, 5000)}…` : fullText,
      source: itemSource,
      sourceFeedUrl: feedEntry.xmlUrl,
      sourceTier,
      provenance,
      authenticity,
      isKwinRelated: relevance.isRelevant,
      kwinRelevanceScore: relevance.score,
      kwinRelevanceReasons: relevance.reasons,
      publishedAt: published,
    });
  }

  for (const entry of atomEntries.slice(0, perFeedLimit)) {
    const title = stripHtml(getTagValue(entry, ['title'])) || 'Untitled article';
    const link = unwrapDiscoveryLink(getAtomLink(entry));
    const summaryText = getTagValue(entry, ['summary', 'content']);
    const published = parseDateMaybe(getTagValue(entry, ['published', 'updated']));
    if (!link) {
      continue;
    }
    const fullText = stripHtml(summaryText);
    const summary = buildSummary(title, summaryText, feedEntry.xmlUrl);
    const relevance = scoreKwinRelevance(title, fullText);
    const itemSource = stripHtml(getTagValue(entry, ['source>title'])) || source;
    parsed.push({
      title,
      link,
      ...summary,
      fullContent: fullText.length > 5000 ? `${fullText.slice(0, 5000)}…` : fullText,
      source: itemSource,
      sourceFeedUrl: feedEntry.xmlUrl,
      sourceTier,
      provenance,
      authenticity,
      isKwinRelated: relevance.isRelevant,
      kwinRelevanceScore: relevance.score,
      kwinRelevanceReasons: relevance.reasons,
      publishedAt: published,
    });
  }

  return parsed;
}

async function fetchTextWithTimeout(url: string): Promise<string> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(url, {
      method: 'GET',
      signal: controller.signal,
      headers: {
        'User-Agent': 'KWINNewsReader/1.0 (+https://kwin-city.com)',
        Accept: 'application/rss+xml, application/atom+xml, text/xml, application/xml, text/plain;q=0.8, */*;q=0.5',
      },
      cache: 'no-store',
    });
    if (!response.ok) {
      throw new Error(`Fetch failed for ${url}: ${response.status}`);
    }
    return await response.text();
  } finally {
    clearTimeout(timeout);
  }
}

function resolveOpmlUrl(rawOpmlUrl: string, requestUrl: string): string {
  const requestOrigin = new URL(requestUrl);
  const resolved = new URL(rawOpmlUrl, `${requestOrigin.protocol}//${requestOrigin.host}`);
  if (!['http:', 'https:'].includes(resolved.protocol)) {
    throw new Error('Only HTTP(S) OPML URLs are allowed.');
  }

  // The server intentionally fetches only the reviewed, same-origin registry.
  // Accepting arbitrary remote OPML files turns a reader endpoint into an SSRF proxy.
  const isSameOriginHost = resolved.hostname.toLowerCase() === requestOrigin.hostname.toLowerCase();
  if (!isSameOriginHost || resolved.pathname !== '/feeds/kwin-city-news-feeds.opml') {
    throw new Error('Only the reviewed KWIN source registry is available in the public reader.');
  }
  return resolved.toString();
}

export async function GET(request: NextRequest) {
  try {
    const opmlUrlRaw = request.nextUrl.searchParams.get('opmlUrl') ?? '/feeds/kwin-city-news-feeds.opml';
    const limitRaw = request.nextUrl.searchParams.get('limit') ?? `${DEFAULT_LIMIT}`;
    const limit = Math.min(Math.max(Number(limitRaw) || DEFAULT_LIMIT, 1), MAX_LIMIT);

    const opmlUrl = resolveOpmlUrl(opmlUrlRaw, request.url);
    const cacheKey = `${opmlUrl}::${limit}`;
    const now = Date.now();
    const cached = routeCache.get(cacheKey);
    if (cached && cached.expiresAt > now) {
      return NextResponse.json({
        ...cached.payload,
        cache: {
          hit: true,
          ttlMs: Math.max(0, cached.expiresAt - now),
        },
      });
    }

    const opmlXml = await fetchTextWithTimeout(opmlUrl);
    const feedEntries = parseReaderFeedsFromOpml(opmlXml)
      .sort((a, b) => Number(isKwinSourceFeed(b)) - Number(isKwinSourceFeed(a)))
      .slice(0, MAX_FEEDS);
    const feedUrls = feedEntries.map((entry) => entry.xmlUrl);

    if (feedUrls.length === 0) {
      return NextResponse.json(
        { error: 'No feed URLs found in the provided OPML file.' },
        { status: 400 }
      );
    }

    const perFeedLimit = Math.max(4, Math.ceil(limit / Math.min(feedUrls.length, 8)));
    const settled = await Promise.allSettled(
      feedEntries.map(async (feedEntry) => {
        const feedXml = await fetchTextWithTimeout(feedEntry.xmlUrl);
        return parseFeedItems(feedXml, feedEntry, perFeedLimit);
      })
    );

    const combined: FeedItem[] = [];
    for (const result of settled) {
      if (result.status === 'fulfilled') {
        combined.push(...result.value);
      }
    }

    const dedupedMap = new Map<string, FeedItem>();
    for (const item of combined) {
      const key = item.title
        .replace(/\s+-\s+[^-]+$/, '')
        .toLowerCase()
        .replace(/[^\p{L}\p{N}]+/gu, ' ')
        .trim();
      const existing = dedupedMap.get(key);
      if (!existing
        || SUMMARY_QUALITY[item.summarySource] > SUMMARY_QUALITY[existing.summarySource]
        || (SUMMARY_QUALITY[item.summarySource] === SUMMARY_QUALITY[existing.summarySource]
          && item.kwinRelevanceScore > existing.kwinRelevanceScore)) {
        dedupedMap.set(key, item);
      }
    }

    const sorted = selectReaderStories([...dedupedMap.values()], limit);

    const payload: ReaderPayload = {
      opmlUrl,
      feedCount: feedUrls.length,
      itemCount: sorted.length,
      generatedAt: new Date().toISOString(),
      items: sorted,
      cache: {
        hit: false,
        ttlMs: CACHE_TTL_MS,
      },
    };

    routeCache.set(cacheKey, {
      expiresAt: now + CACHE_TTL_MS,
      payload,
    });

    return NextResponse.json(payload);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to load reader data.';
    return NextResponse.json({ error: message }, { status: 400 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabase, getSupabaseAdmin } from "@/lib/server/supabase-client";

// Simple rate limiter: max 3 signups per IP per minute
const rateMap = new Map<string, { count: number; resetAt: number }>();
function checkRateLimit(ip: string): boolean {
  const now = Date.now();
  const entry = rateMap.get(ip);
  if (!entry || now > entry.resetAt) {
    rateMap.set(ip, { count: 1, resetAt: now + 60_000 });
    return false;
  }
  if (entry.count >= 3) return true;
  entry.count++;
  return false;
}

function sanitise(value: unknown, maxLen = 200): string {
  if (typeof value !== "string") return "";
  return value
    .replace(/[<>"'`]/g, "")
    .trim()
    .slice(0, maxLen);
}

export async function POST(req: NextRequest) {
  const ip = req.headers.get("x-forwarded-for")?.split(",")[0] ?? "unknown";
  if (checkRateLimit(ip)) {
    return NextResponse.json({ error: "Too many requests" }, { status: 429 });
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { error: "Invalid request body" },
      { status: 400 },
    );
  }

  if (typeof body !== "object" || body === null) {
    return NextResponse.json(
      { error: "Invalid request body" },
      { status: 400 },
    );
  }

  const { name, email, interests } = body as Record<string, unknown>;
  const cleanEmail = sanitise(email);
  const cleanName = sanitise(name);
  const cleanInterests = Array.isArray(interests)
    ? interests.map((i) => sanitise(i)).join(", ")
    : "";

  if (!cleanEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail)) {
    return NextResponse.json(
      { error: "Invalid email address" },
      { status: 400 },
    );
  }

  // ── Try to store in Supabase if configured ──────────────────────────────────
  const supabase = getSupabaseAdmin() ?? getSupabase();
  if (supabase) {
    try {
      await supabase.from("newsletter_signups").insert({
        email: cleanEmail,
        name: cleanName || null,
        interests: cleanInterests || null,
        created_at: new Date().toISOString(),
      });
    } catch {
      // Non-fatal — fall through
    }
  }

  // ── Optional: forward via Resend ────────────────────────────────────────────
  const resendKey = process.env.RESEND_API_KEY;
  const notifyEmail = process.env.CONTACT_EMAIL ?? "hello@kwin-city.com";
  if (resendKey) {
    try {
      await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${resendKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          from: "KWIN City <onboarding@resend.dev>",
          to: [notifyEmail],
          subject: `New newsletter signup: ${cleanEmail}`,
          html: `<p><strong>Email:</strong> ${cleanEmail}</p><p><strong>Name:</strong> ${cleanName || "—"}</p><p><strong>Interests:</strong> ${cleanInterests || "—"}</p>`,
        }),
      });
    } catch {
      // Non-fatal
    }
  }

  return NextResponse.json({ ok: true }, { status: 200 });
}

import { NextRequest, NextResponse } from 'next/server';

const CKAN_BASE = 'https://data.opencity.in/api/3/action';

export async function GET(req: NextRequest) {
  const { searchParams } = req.nextUrl;
  const dataset = searchParams.get('dataset');
  const resourceId = searchParams.get('resource_id');
  const limit = Math.min(parseInt(searchParams.get('limit') ?? '500', 10), 1000);

  if (!dataset && !resourceId) {
    return NextResponse.json({ error: 'dataset or resource_id param required' }, { status: 400 });
  }

  try {
    let targetResourceId = resourceId;

    if (!targetResourceId) {
      // Step 1: discover the datastore-active resource from the dataset slug
      const pkgRes = await fetch(
        `${CKAN_BASE}/package_show?id=${encodeURIComponent(dataset!)}`,
        { next: { revalidate: 3600 } }
      );
      if (!pkgRes.ok) throw new Error(`package_show HTTP ${pkgRes.status}`);

      const pkg = await pkgRes.json();
      if (!pkg.success) {
        return NextResponse.json(
          { error: pkg.error?.message ?? 'CKAN returned error', ckan_error: pkg.error },
          { status: 422 }
        );
      }

      const resources: { id: string; datastore_active: boolean; format: string; name: string }[] =
        pkg.result?.resources ?? [];

      // Prefer datastore-active resource; fall back to CSV
      const active =
        resources.find((r) => r.datastore_active) ??
        resources.find((r) => r.format?.toUpperCase() === 'CSV');

      if (!active) {
        return NextResponse.json(
          {
            error: 'No queryable datastore resource found on this dataset.',
            hint: 'The dataset may only contain PDFs or documents.',
            resources: resources.map((r) => ({ id: r.id, name: r.name, format: r.format })),
          },
          { status: 422 }
        );
      }

      targetResourceId = active.id;
    }

    // Step 2: fetch actual tabular data
    const dataRes = await fetch(
      `${CKAN_BASE}/datastore_search?resource_id=${encodeURIComponent(targetResourceId)}&limit=${limit}`,
      { next: { revalidate: 3600 } }
    );
    if (!dataRes.ok) throw new Error(`datastore_search HTTP ${dataRes.status}`);

    const data = await dataRes.json();
    return NextResponse.json(data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error fetching from OpenCity';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

