import { NextRequest, NextResponse } from 'next/server';
import { checkRateLimit, getRateLimitHeaders } from '@/lib/server/security';
import { parseVerificationSubmission } from '@/lib/operations/verification-schema';
import { recordVerification } from '@/lib/operations/verification-repository';
import { evaluateVerification } from '@/lib/operations/verification-policy';
import { EVIDENCE_NONCE_HEADER, EVIDENCE_SIGNATURE_HEADER, EVIDENCE_TIMESTAMP_HEADER, verifyEvidenceSignature } from '@/lib/operations/verification-signature';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 30;
const MAX_BODY_BYTES = 96 * 1024;

export async function POST(request: NextRequest) {
  const rateLimit = checkRateLimit(request, { scope: 'operations-evidence', limit: 30, windowMs: 60_000 });
  const headers = getRateLimitHeaders(rateLimit);
  if (rateLimit.limited) return NextResponse.json({ success: false, error: 'Rate limit exceeded.' }, { status: 429, headers });
  const length = Number(request.headers.get('content-length') ?? '0');
  if (length > MAX_BODY_BYTES) return NextResponse.json({ success: false, error: 'Payload too large.' }, { status: 413, headers });
  const body = await request.text();
  if (Buffer.byteLength(body) > MAX_BODY_BYTES) return NextResponse.json({ success: false, error: 'Payload too large.' }, { status: 413, headers });
  const secret = process.env.OPERATIONS_EVIDENCE_SECRET;
  if (!secret || Buffer.byteLength(secret) < 32) return NextResponse.json({ success: false, error: 'Evidence recording is not configured.' }, { status: 503, headers });
  const authorized = verifyEvidenceSignature({
    secret, timestamp: request.headers.get(EVIDENCE_TIMESTAMP_HEADER), nonce: request.headers.get(EVIDENCE_NONCE_HEADER),
    signature: request.headers.get(EVIDENCE_SIGNATURE_HEADER), body,
  });
  if (!authorized) return NextResponse.json({ success: false, error: 'Unauthorized evidence request.' }, { status: 401, headers });
  try {
    const submission = parseVerificationSubmission(JSON.parse(body));
    const evaluation = evaluateVerification(submission);
    const result = await recordVerification(submission);
    return NextResponse.json({
      success: true, attemptId: result.attempt.id, outcome: result.attempt.outcome,
      qualified: result.attempt.qualified, rail: evaluation.rail, idempotent: result.idempotent,
    }, { headers: { ...headers, 'Cache-Control': 'no-store' } });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'invalid-evidence';
    const conflict = message === 'idempotency-key-payload-conflict';
    const storageFailure = message.startsWith('operational-') && !conflict;
    return NextResponse.json(
      { success: false, error: conflict ? 'Idempotency key conflicts with an existing payload.' : storageFailure ? 'Evidence persistence failed.' : 'Invalid evidence payload.' },
      { status: conflict ? 409 : storageFailure ? 503 : 400, headers },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { getSessionFromCookie } from '@/lib/server/auth';
import { hasValidCsrf, isRateLimited, isSameOrigin, CSRF_COOKIE } from '@/lib/server/security';
import { getPreferences, setPreferences } from '@/lib/server/data-layer';
import type { UserPreference } from '@/lib/server/models';

function isValidPreference(input: unknown): input is UserPreference {
  if (!input || typeof input !== 'object') return false;
  const value = input as UserPreference;
  const personaOk = ['investor', 'resident', 'researcher', 'journalist', 'citizen'].includes(value.persona);
  const digestOk = ['daily', 'weekly', 'monthly'].includes(value.digestFrequency);
  const topicsOk = Array.isArray(value.favoriteTopics) && value.favoriteTopics.every((t) => typeof t === 'string');
  return personaOk && digestOk && topicsOk && typeof value.emailUpdates === 'boolean';
}

export async function GET() {
  const session = await getSessionFromCookie();
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const prefs = await getPreferences(session.email);
  const defaultPreference: UserPreference = {
    persona: 'resident',
    favoriteTopics: ['timeline'],
    digestFrequency: 'weekly',
    emailUpdates: true,
  };
  return NextResponse.json({ preferences: prefs || defaultPreference });
}

export async function PUT(req: NextRequest) {
  if (!isSameOrigin(req)) {
    return NextResponse.json({ error: 'Invalid request origin.' }, { status: 403 });
  }

  if (isRateLimited(req, { scope: 'preferences-write', limit: 30, windowMs: 60_000 })) {
    return NextResponse.json({ error: 'Too many requests. Try again shortly.' }, { status: 429 });
  }

  const cookieStore = await cookies();
  const csrfCookie = cookieStore.get(CSRF_COOKIE)?.value;
  if (!hasValidCsrf(req, csrfCookie)) {
    return NextResponse.json({ error: 'CSRF validation failed.' }, { status: 403 });
  }

  const session = await getSessionFromCookie();
  if (!session) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const body = await req.json().catch(() => null);
  if (!isValidPreference(body)) {
    return NextResponse.json({ error: 'Invalid preference payload.' }, { status: 400 });
  }

  await setPreferences(session.email, body);
  const prefs = await getPreferences(session.email);

  return NextResponse.json({ preferences: prefs });
}

