      const limit = normalizeLeadLimit(req.nextUrl.searchParams.get('limit'));
      const data = await listOpportunityLeads(limit);

      return NextResponse.json(
        createEnvelope({
          requestId,
          status: 'success',
          data,
          sourceIds: ['brief'],
        })
      );
    }
  );
