'use client';

import { useEffect } from 'react';

declare global {
  interface Window {
    __kwinClarityInitialized?: boolean;
  }
}

const CLARITY_PROJECT_ID = 'w90fdbtt4x';
const clarityProjectId = process.env.NEXT_PUBLIC_CLARITY_PROJECT_ID?.trim() || CLARITY_PROJECT_ID;

export default function ClarityInit() {
  useEffect(() => {
    let cancelled = false;

    async function initClarity() {
      if (window.__kwinClarityInitialized) {
        return;
      }

      const { default: Clarity } = await import('@microsoft/clarity');
      if (cancelled || window.__kwinClarityInitialized) {
        return;
      }

      Clarity.init(clarityProjectId);
      window.__kwinClarityInitialized = true;
    }

    void initClarity();

    return () => {
      cancelled = true;
    };
  }, []);

  return null;
}

'use client';

import { useEffect, useState } from 'react';
import dynamic from 'next/dynamic';

const PwaRegistration = dynamic(() => import('@/components/PwaRegistration'), { ssr: false });
const PwaInstallPrompt = dynamic(() => import('@/components/PwaInstallPrompt'), { ssr: false });
const PageAnalytics = dynamic(() => import('@/components/PageAnalytics'), { ssr: false });
const ClarityInit = dynamic(() => import('@/components/ClarityInit'), { ssr: false });
const PostHogInit = dynamic(() => import('@/components/PostHogInit'), { ssr: false });

export default function ClientEnhancements() {
  const [shouldEnhance, setShouldEnhance] = useState(false);
  const [shouldLoadAnalytics, setShouldLoadAnalytics] = useState(false);

  useEffect(() => {
    const browser = globalThis as typeof globalThis & {
      requestIdleCallback?: (callback: IdleRequestCallback, options?: IdleRequestOptions) => number;
      cancelIdleCallback?: (handle: number) => void;
    };
    const activate = () => setShouldEnhance(true);

    if (typeof browser.requestIdleCallback === 'function') {
      const idleId = browser.requestIdleCallback(activate, { timeout: 1500 });
      return () => browser.cancelIdleCallback?.(idleId);
    }

    const timeoutId = browser.setTimeout(activate, 800);
    return () => browser.clearTimeout(timeoutId);
  }, []);

  useEffect(() => {
    const browser = globalThis as typeof globalThis & {
      requestIdleCallback?: (callback: IdleRequestCallback, options?: IdleRequestOptions) => number;
      cancelIdleCallback?: (handle: number) => void;
      navigator: Navigator & {
        connection?: { effectiveType?: string; saveData?: boolean };
      };
    };
    const connection = browser.navigator.connection;

    // Analytics must never compete with the first render, and should respect
    // explicit data-saving or very slow connection preferences.
    if (connection?.saveData || connection?.effectiveType === 'slow-2g' || connection?.effectiveType === '2g') {
      return;
    }

    let idleId: number | undefined;
    let timeoutId: ReturnType<typeof setTimeout> | undefined;
    let cancelled = false;

    const activate = () => {
      if (cancelled) return;
      if (typeof browser.requestIdleCallback === 'function') {
        idleId = browser.requestIdleCallback(() => setShouldLoadAnalytics(true), { timeout: 5000 });
      } else {
        timeoutId = browser.setTimeout(() => setShouldLoadAnalytics(true), 3500);
      }
    };

    if (document.readyState === 'complete') {
      activate();
    } else {
      window.addEventListener('load', activate, { once: true });
    }

    return () => {
      cancelled = true;
      window.removeEventListener('load', activate);
      if (idleId !== undefined) browser.cancelIdleCallback?.(idleId);
      if (timeoutId !== undefined) browser.clearTimeout(timeoutId);
    };
  }, []);

  if (!shouldEnhance) {
    return null;
  }

  return (
    <>
      <PwaRegistration />
      <PwaInstallPrompt />
      {shouldLoadAnalytics ? (
        <>
          <PageAnalytics />
          <ClarityInit />
          <PostHogInit />
        </>
      ) : null}
    </>
  );
}

'use client';

import { FormEvent, useEffect, useMemo, useState } from 'react';
import { useI18n } from '@/lib/i18n/I18nProvider';
import { pickLocalizedValue } from '@/lib/i18n/messages';

type SessionUser = {
  id: string;
  name: string;
  email: string;
};

type Reply = {
  id: string;
  author: string;
  text: string;
  createdAt: string;
};

type DiscussionPost = {
  id: string;
  author: string;
  title: string;
  text: string;
  likes: number;
  createdAt: string;
  replies: Reply[];
};

export default function CommunityDiscussion() {
  const { locale } = useI18n();
  const l = (values: Parameters<typeof pickLocalizedValue<string>>[1]) => pickLocalizedValue(locale, values);
  const [posts, setPosts] = useState<DiscussionPost[]>([]);
  const [session, setSession] = useState<SessionUser | null>(null);
  const [title, setTitle] = useState('');
  const [text, setText] = useState('');
  const [replyDrafts, setReplyDrafts] = useState<Record<string, string>>({});
  const [status, setStatus] = useState('');
  const [busy, setBusy] = useState(false);
  const [csrf, setCsrf] = useState('');

  const t = {
    couldNotCreatePost: l({ en: 'Could not create post.', kn: 'ಪೋಸ್ಟ್ ರಚಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.', hi: 'पोस्ट नहीं बन सकी।', ta: 'பதிவை உருவாக்க முடியவில்லை.' }),
    discussionPosted: l({ en: 'Discussion posted.', kn: 'ಚರ್ಚೆ ಪ್ರಕಟಿಸಲಾಗಿದೆ.', hi: 'चर्चा पोस्ट हो गई।', ta: 'விவாதம் வெளியிடப்பட்டது.' }),
    requestFailed: l({ en: 'Request failed. Please try again.', kn: 'ವಿನಂತಿ ವಿಫಲವಾಗಿದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.', hi: 'अनुरोध विफल हुआ। कृपया फिर प्रयास करें।', ta: 'கோரிக்கை தோல்வியடைந்தது. மீண்டும் முயற்சிக்கவும்.' }),
    couldNotAddReply: l({ en: 'Could not add reply.', kn: 'ಪ್ರತ್ಯುತ್ತರ ಸೇರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.', hi: 'उत्तर जोड़ना संभव नहीं हुआ।', ta: 'பதில் சேர்க்க முடியவில்லை.' }),
  };

  const loadSession = async () => {
    const res = await fetch('/api/auth/me', { cache: 'no-store' });
    if (!res.ok) {
      setSession(null);
      return;
    }
    const data = (await res.json()) as { user: SessionUser | null; csrf?: string };
    setSession(data.user);
    if (data.csrf) setCsrf(data.csrf);
  };

  const loadPosts = async () => {
    const res = await fetch('/api/community', { cache: 'no-store' });
    if (!res.ok) return;
    const data = (await res.json()) as { posts: DiscussionPost[] };
    setPosts(data.posts);
  };

  useEffect(() => {
    loadSession().catch(() => setSession(null));
    loadPosts().catch(() => setPosts([]));
  }, []);

  const createPost = async (e: FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setStatus('');

    try {
      const res = await fetch('/api/community', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrf,
        },
        body: JSON.stringify({ title, text }),
      });
      const data = (await res.json()) as { error?: string; post?: DiscussionPost };
      if (!res.ok) {
        setStatus(data.error || t.couldNotCreatePost);
        return;
      }

      if (data.post) {
        setPosts((prev) => [data.post as DiscussionPost, ...prev]);
      }
      setTitle('');
      setText('');
      setStatus(t.discussionPosted);
    } catch {
      setStatus(t.requestFailed);
    } finally {
      setBusy(false);
    }
  };

  const likePost = async (postId: string) => {
    const res = await fetch(`/api/community/${postId}/like`, {
      method: 'POST',
      headers: { 'x-csrf-token': csrf },
    });
    const data = (await res.json()) as { likes?: number };
    if (!res.ok || typeof data.likes !== 'number') return;

    setPosts((prev) => prev.map((p) => (p.id === postId ? { ...p, likes: data.likes as number } : p)));
  };

  const addReply = async (postId: string) => {
    const draft = (replyDrafts[postId] || '').trim();
    if (!draft) return;

    const res = await fetch(`/api/community/${postId}/reply`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-csrf-token': csrf,
      },
      body: JSON.stringify({ text: draft }),
    });
    const data = (await res.json()) as { error?: string; reply?: Reply };
    if (!res.ok || !data.reply) {
      setStatus(data.error || t.couldNotAddReply);
      return;
    }

    setPosts((prev) =>
      prev.map((p) => (p.id === postId ? { ...p, replies: [...p.replies, data.reply as Reply] } : p))
    );
    setReplyDrafts((prev) => ({ ...prev, [postId]: '' }));
  };

  const stats = useMemo(() => {
    const totalReplies = posts.reduce((sum, p) => sum + p.replies.length, 0);
    const totalLikes = posts.reduce((sum, p) => sum + p.likes, 0);
    return { totalReplies, totalLikes };
  }, [posts]);

  return (
    <main className="min-h-screen bg-gradient-to-b from-white to-[#F7FAFC]">
      <section className="bg-gradient-to-r from-[#0F172A] to-[#1E3A8A] text-white py-14">
        <div className="container">
          <h1 className="text-4xl md:text-5xl font-extrabold mb-3">{l({ en: 'Community Discussion', kn: 'ಸಮುದಾಯ ಚರ್ಚೆ', hi: 'समुदाय चर्चा', ta: 'சமூக விவாதம்' })}</h1>
          <p className="text-blue-100 max-w-2xl">
            {l({ en: 'Open conversation board for stakeholders to discuss evidence, planning signals, and next research asks.', kn: 'ಸಾಕ್ಷ್ಯ, ಯೋಜನಾ ಸೂಚನೆಗಳು ಮತ್ತು ಮುಂದಿನ ಸಂಶೋಧನಾ ಪ್ರಶ್ನೆಗಳ ಬಗ್ಗೆ ಚರ್ಚಿಸಲು ತೆರೆಯಾದ ವೇದಿಕೆ.', hi: 'प्रमाण, योजना संकेत और आगे के शोध प्रश्नों पर चर्चा के लिए खुला मंच।', ta: 'ஆதாரங்கள், திட்டச் சுட்டுக்கள் மற்றும் அடுத்த ஆய்வு கேள்விகள் குறித்து விவாதிக்க திறந்த கலந்துரையாடல் தளம்.' })}
          </p>
        </div>
      </section>

      <section className="container py-10 grid grid-cols-1 xl:grid-cols-3 gap-6">
        <div className="xl:col-span-1 space-y-4">
          <div className="rounded-2xl border border-slate-200 bg-white p-5">
            <p className="text-xs font-bold tracking-widest uppercase text-slate-500 mb-2">{l({ en: 'Thread Stats', kn: 'ಥ್ರೆಡ್ ಅಂಕಿಅಂಶಗಳು', hi: 'थ्रेड आँकड़े', ta: 'திரை விவாத புள்ளிவிவரங்கள்' })}</p>
            <p className="text-sm text-slate-700">{l({ en: 'Posts', kn: 'ಪೋಸ್ಟ್‌ಗಳು', hi: 'पोस्ट्स', ta: 'பதிவுகள்' })}: {posts.length}</p>
            <p className="text-sm text-slate-700">{l({ en: 'Replies', kn: 'ಪ್ರತ್ಯುತ್ತರಗಳು', hi: 'उत्तर', ta: 'பதில்கள்' })}: {stats.totalReplies}</p>
            <p className="text-sm text-slate-700">{l({ en: 'Likes', kn: 'ಇಷ್ಟಗಳು', hi: 'पसंद', ta: 'விருப்பங்கள்' })}: {stats.totalLikes}</p>
          </div>

          <form onSubmit={createPost} className="rounded-2xl border border-slate-200 bg-white p-5 space-y-3">
            <h2 className="text-lg font-extrabold text-slate-900">{l({ en: 'Start a Discussion', kn: 'ಚರ್ಚೆಯನ್ನು ಆರಂಭಿಸಿ', hi: 'चर्चा शुरू करें', ta: 'ஒரு விவாதத்தை தொடங்கவும்' })}</h2>
            {session ? (
              <p className="text-sm text-slate-600">{l({ en: 'Posting as', kn: 'ಈ ಹೆಸರಿನಲ್ಲಿ ಪೋಸ್ಟ್ ಮಾಡಲಾಗುತ್ತಿದೆ', hi: 'इस नाम से पोस्ट किया जा रहा है', ta: 'இந்த பெயரில் பதிவிடப்படுகிறது' })} {session.name}</p>
            ) : (
              <p className="text-sm text-amber-700">{l({ en: 'Sign in at /account to post or reply.', kn: 'ಪೋಸ್ಟ್ ಅಥವಾ ಪ್ರತಿಕ್ರಿಯೆಗಾಗಿ /account ನಲ್ಲಿ ಸೈನ್ ಇನ್ ಮಾಡಿ.', hi: 'पोस्ट या उत्तर देने के लिए /account पर साइन इन करें।', ta: 'பதிவு செய்ய அல்லது பதிலளிக்க /account இல் உள்நுழைக.' })}</p>
            )}
            <div>
              <label className="block text-xs font-bold tracking-widest uppercase text-slate-500 mb-1">{l({ en: 'Title', kn: 'ಶೀರ್ಷಿಕೆ', hi: 'शीर्षक', ta: 'தலைப்பு' })}</label>
              <input
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="w-full rounded-lg border border-slate-300 px-3 py-2"
                placeholder={l({ en: 'What should we discuss?', kn: 'ನಾವು ಯಾವ ವಿಷಯ ಚರ್ಚಿಸಬೇಕು?', hi: 'हमें किस विषय पर चर्चा करनी चाहिए?', ta: 'நாம் எந்த விஷயத்தை விவாதிப்பது?' })}
                disabled={!session || busy}
              />
            </div>
            <div>
              <label className="block text-xs font-bold tracking-widest uppercase text-slate-500 mb-1">{l({ en: 'Message', kn: 'ಸಂದೇಶ', hi: 'संदेश', ta: 'செய்தி' })}</label>
              <textarea
                value={text}
                onChange={(e) => setText(e.target.value)}
                rows={4}
                className="w-full rounded-lg border border-slate-300 px-3 py-2"
                placeholder={l({ en: 'Share context, evidence, and your question...', kn: 'ಪರಿಸ್ಥಿತಿ, ಸಾಕ್ಷ್ಯ ಮತ್ತು ನಿಮ್ಮ ಪ್ರಶ್ನೆಯನ್ನು ಹಂಚಿಕೊಳ್ಳಿ...', hi: 'संदर्भ, प्रमाण और अपना प्रश्न साझा करें...', ta: 'சூழல், ஆதாரம் மற்றும் உங்கள் கேள்வியை பகிரவும்...' })}
                disabled={!session || busy}
              />
            </div>
            <button
              type="submit"
              disabled={!session || busy}
              className="w-full rounded-lg bg-blue-600 text-white font-semibold px-4 py-2 hover:bg-blue-700 transition-colors disabled:opacity-60"
            >
              {l({ en: 'Post', kn: 'ಪೋಸ್ಟ್ ಮಾಡಿ', hi: 'पोस्ट करें', ta: 'பதிவிடு' })}
            </button>
          </form>
        </div>

        <div className="xl:col-span-2 space-y-4">
          {posts.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-6 text-slate-600">
              {l({ en: 'No discussions yet. Be the first to post.', kn: 'ಇನ್ನೂ ಚರ್ಚೆಗಳು ಇಲ್ಲ. ಮೊದಲ ಪೋಸ್ಟ್ ಮಾಡಿ.', hi: 'अभी कोई चर्चा नहीं है। पहली पोस्ट करें।', ta: 'இன்னும் விவாதங்கள் இல்லை. முதலில் நீங்கள் பதிவிடுங்கள்.' })}
            </div>
          ) : (
            posts.map((post) => (
              <article key={post.id} className="rounded-2xl border border-slate-200 bg-white p-5">
                <div className="flex items-start justify-between gap-4 mb-3">
                  <div>
                    <h3 className="text-xl font-extrabold text-slate-900">{post.title}</h3>
                    <p className="text-sm text-slate-600">
                      {l({ en: 'By', kn: 'ಬರೆದವರು', hi: 'द्वारा', ta: 'எழுதியவர்' })} {post.author} {l({ en: 'on', kn: 'ರಂದು', hi: 'को', ta: 'தேதி' })} {new Date(post.createdAt).toLocaleString()}
                    </p>
                  </div>
                  <button
                    onClick={() => likePost(post.id)}
                    className="px-3 py-1.5 rounded-lg border border-slate-300 text-sm font-semibold text-slate-700 hover:bg-slate-50"
                  >
                    {l({ en: 'Like', kn: 'ಇಷ್ಟ', hi: 'पसंद', ta: 'விருப்பு' })} ({post.likes})
                  </button>
                </div>
                <p className="text-slate-800 mb-4">{post.text}</p>

                <div className="space-y-2 mb-3">
                  {post.replies.map((reply) => (
                    <div key={reply.id} className="rounded-lg bg-slate-50 border border-slate-200 px-3 py-2">
                      <p className="text-sm text-slate-900">{reply.text}</p>
                      <p className="text-xs text-slate-500 mt-1">
                        {reply.author} · {new Date(reply.createdAt).toLocaleString()}
                      </p>
                    </div>
                  ))}
                </div>

                <div className="flex gap-2">
                  <input
                    value={replyDrafts[post.id] || ''}
                    onChange={(e) => setReplyDrafts((prev) => ({ ...prev, [post.id]: e.target.value }))}
                    className="flex-1 rounded-lg border border-slate-300 px-3 py-2"
                    placeholder={l({ en: 'Write a reply...', kn: 'ಪ್ರತ್ಯುತ್ತರ ಬರೆಯಿರಿ...', hi: 'उत्तर लिखें...', ta: 'ஒரு பதிலை எழுதுங்கள்...' })}
                    disabled={!session}
                  />
                  <button
                    onClick={() => addReply(post.id)}
                    disabled={!session}
                    className="px-3 py-2 rounded-lg bg-slate-900 text-white font-semibold hover:bg-slate-800 disabled:opacity-60"
                  >
                    {l({ en: 'Reply', kn: 'ಪ್ರತ್ಯುತ್ತರ', hi: 'उत्तर', ta: 'பதில்' })}
                  </button>
                </div>
              </article>
            ))
          )}
        </div>
      </section>

      {status ? (
        <div className="container pb-10">
          <p className="rounded-lg border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-800">{status}</p>
        </div>
      ) : null}
    </main>
  );
}

'use client';

import Link from 'next/link';
import { useId, useRef, useState } from 'react';
import { useI18n } from '@/lib/i18n/I18nProvider';
import { pickLocalizedValue } from '@/lib/i18n/messages';
import { ContactFields } from '@/components/contact/ContactFields';
import { ContactSuccessState } from '@/components/contact/ContactSuccessState';
import { getMessagePlaceholder, getSelectedPersona, type FormState, type PersonaId } from '@/components/contact/config';
import { PersonaSelector } from '@/components/contact/PersonaSelector';

type FieldName = 'name' | 'email' | 'message';
type FieldErrors = Partial<Record<FieldName, string>>;

const CONTACT_EMAIL = 'hello@kwin-city.com';

export default function ContactForm() {
  const { locale } = useI18n();
  const l = (values: Parameters<typeof pickLocalizedValue<string>>[1]) => pickLocalizedValue(locale, values);
  const uid = useId();
  const nameRef = useRef<HTMLInputElement>(null);
  const errorSummaryRef = useRef<HTMLDivElement>(null);

  const [persona, setPersona] = useState<PersonaId | null>(null);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [honeypot, setHoneypot] = useState('');
  const [formState, setFormState] = useState<FormState>('idle');
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [errorMsg, setErrorMsg] = useState('');
  const [errorRequestId, setErrorRequestId] = useState('');

  const selectedPersona = getSelectedPersona(persona);
  const messagePlaceholder = getMessagePlaceholder(selectedPersona);
  const charCount = message.length;

  const validate = (): FieldErrors => {
    const errors: FieldErrors = {};
    if (!name.trim()) errors.name = 'Enter your name so we know how to address you.';
    if (!email.trim()) errors.email = 'Enter an email address so we can reply.';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) errors.email = 'Enter a valid email address, such as name@example.com.';
    if (!message.trim()) errors.message = 'Tell us a little about what you need.';
    else if (message.trim().length < 20) errors.message = 'Please add a little more detail (at least 20 characters) so we can respond usefully.';
    return errors;
  };

  const clearFieldError = (field: FieldName) => {
    setFieldErrors((current) => {
      if (!current[field]) return current;
      const next = { ...current };
      delete next[field];
      return next;
    });
    if (formState === 'error') setFormState('idle');
  };

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (formState === 'submitting') return;

    const errors = validate();
    if (Object.keys(errors).length) {
      setFieldErrors(errors);
      setErrorMsg('Please correct the highlighted fields and try again.');
      setErrorRequestId('');
      setFormState('error');
      window.requestAnimationFrame(() => errorSummaryRef.current?.focus());
      return;
    }

    setFormState('submitting');
    setFieldErrors({});
    setErrorMsg('');
    setErrorRequestId('');

    try {
      const response = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: name.trim(),
          email: email.trim(),
          message: message.trim(),
          persona: selectedPersona?.label ?? 'Visitor',
          website: honeypot,
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.success) {
        setErrorMsg(data.error ?? 'Something went wrong. Please try again.');
        setErrorRequestId(typeof data.requestId === 'string' ? data.requestId : '');
        setFormState('error');
        window.requestAnimationFrame(() => errorSummaryRef.current?.focus());
        return;
      }
      setFormState('success');
    } catch {
      setErrorMsg('We could not connect right now. Check your connection and try again, or email us directly.');
      setFormState('error');
      window.requestAnimationFrame(() => errorSummaryRef.current?.focus());
    }
  };

  return (
    <main id="main-content" className="kwin-page-top overflow-hidden bg-[#f7f8fc] pb-16">
      <section className="relative isolate overflow-hidden bg-[#07112d] px-4 pb-16 pt-12 text-white sm:px-6 lg:px-8">
        <div aria-hidden="true" className="absolute inset-0 -z-10 bg-[radial-gradient(circle_at_12%_12%,rgba(245,166,35,0.22),transparent_28%),radial-gradient(circle_at_88%_18%,rgba(6,182,212,0.18),transparent_30%)]" />
        <div className="mx-auto max-w-6xl">
          <p className="inline-flex rounded-full border border-amber-300/30 bg-amber-300/10 px-3 py-1 text-xs font-bold uppercase tracking-[0.18em] text-amber-200">Contact KWIN City</p>
          <div className="mt-6 grid gap-8 lg:grid-cols-[minmax(0,1.35fr)_minmax(18rem,.65fr)] lg:items-end">
            <div>
              <h1 className="max-w-3xl text-4xl font-black tracking-tight sm:text-5xl">A clear route to the right conversation.</h1>
              <p className="mt-5 max-w-2xl text-base leading-7 text-slate-200 sm:text-lg">Ask a project question, request evidence, share a correction, or begin a media, research, or partnership conversation. Choose the context that best fits, then write in your own words.</p>
            </div>
            <div className="rounded-2xl border border-white/10 bg-white/[0.06] p-5 backdrop-blur-sm">
              <p className="text-sm font-bold text-white">Prefer email?</p>
              <a href={`mailto:${CONTACT_EMAIL}`} className="mt-2 inline-flex break-all text-base font-semibold text-amber-200 underline decoration-amber-200/40 underline-offset-4 hover:text-white">{CONTACT_EMAIL}</a>
              <p className="mt-3 text-sm leading-6 text-slate-300">Use the form when context helps us route your message. Do not send passwords, financial details, or sensitive documents.</p>
            </div>
          </div>
        </div>
      </section>

      <section className="mx-auto grid max-w-6xl gap-8 px-4 py-10 sm:px-6 lg:grid-cols-[minmax(0,1.25fr)_minmax(17rem,.75fr)] lg:px-8">
        <div className="rounded-[28px] border border-slate-200 bg-white p-5 shadow-[0_24px_60px_rgba(15,23,42,0.08)] sm:p-8">
          {formState === 'success' ? <ContactSuccessState name={name} /> : (
            <form noValidate onSubmit={handleSubmit} className="space-y-7" aria-describedby={`${uid}-form-note`}>
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.16em] text-amber-700">Start here</p>
