'use client';

import { useCallback, useEffect, useRef } from 'react';
import { usePathname, useSearchParams } from 'next/navigation';
import { capturePostHogEvent, initPostHog } from '@/lib/analytics/posthog';

export default function PostHogInit() {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const lastTrackedUrlRef = useRef<string>('');

  const trackCurrentPageview = useCallback((currentUrl: string) => {
    lastTrackedUrlRef.current = currentUrl;
    capturePostHogEvent('$pageview', {
      $current_url: window.location.href,
      pathname,
      query: searchParams?.toString() || null,
    });
  }, [pathname, searchParams]);

  useEffect(() => {
    let cancelled = false;

    const browser = window as typeof window & {
      requestIdleCallback?: (callback: IdleRequestCallback, options?: IdleRequestOptions) => number;
      cancelIdleCallback?: (handle: number) => void;
    };

    const initialize = () => {
      if (!cancelled) {
        if (initPostHog()) {
          const query = searchParams?.toString();
          const currentUrl = query ? `${pathname}?${query}` : pathname;
          if (currentUrl && lastTrackedUrlRef.current !== currentUrl) {
            trackCurrentPageview(currentUrl);
          }
        }
      }
    };

    if (typeof browser.requestIdleCallback === 'function') {
      const idleId = browser.requestIdleCallback(initialize, { timeout: 2000 });
      return () => {
        cancelled = true;
        browser.cancelIdleCallback?.(idleId);
      };
    }

    const timeoutId = browser.setTimeout(initialize, 1000);
    return () => {
      cancelled = true;
      browser.clearTimeout(timeoutId);
    };
  }, [pathname, searchParams, trackCurrentPageview]);

  useEffect(() => {
    const query = searchParams?.toString();
    const currentUrl = query ? `${pathname}?${query}` : pathname;

    if (!currentUrl || lastTrackedUrlRef.current === currentUrl || !window.__kwinPosthogInitialized) {
      return;
    }

    trackCurrentPageview(currentUrl);
  }, [pathname, searchParams, trackCurrentPageview]);

  return null;
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { AnimatePresence, motion } from "framer-motion";
import { PWA_CONFIG } from "@/lib/pwa/config";
import {
  PWA_INSTALL_STORAGE_KEYS,
  readInstallPromptState,
  recordVisit,
  shouldOfferInstall,
} from "@/lib/pwa/install-policy";

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed"; platform: string }>;
}

function isStandalone() {
  const navigatorWithStandalone = navigator as Navigator & {
    standalone?: boolean;
  };
  return (
    window.matchMedia("(display-mode: standalone)").matches ||
    navigatorWithStandalone.standalone === true
  );
}

export default function PwaInstallPrompt() {
  const [prompt, setPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [visible, setVisible] = useState(false);
  const [installed, setInstalled] = useState(false);
  const [showIosHelp, setShowIosHelp] = useState(false);
  const isIos = useMemo(
    () =>
      typeof navigator !== "undefined" &&
      /iphone|ipad|ipod/i.test(navigator.userAgent),
    [],
  );

  useEffect(() => {
    const standalone = isStandalone();
    if (standalone) {
      setInstalled(true);
      try { localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.installedAt, String(Date.now())); } catch { /* optional persistence */ }
      return;
    }
    let revealTimer: ReturnType<typeof setTimeout> | undefined;
    let visits = 0;
    try { visits = recordVisit(localStorage, sessionStorage); } catch { /* Storage is optional. */ }

    const reveal = (nativePrompt: boolean) => {
      let eligible = nativePrompt;
      try {
        eligible = shouldOfferInstall({
          state: { ...readInstallPromptState(localStorage, PWA_CONFIG.installDismissalDays), visitCount: visits },
          now: Date.now(), isStandalone: false, isIos, hasNativePrompt: nativePrompt,
          minimumIosVisits: PWA_CONFIG.installMinimumIosVisits,
          repeatOfferDays: PWA_CONFIG.installRepeatOfferDays,
        });
      } catch { /* Native browser eligibility remains the fallback. */ }
      if (!eligible) return;
      if (revealTimer) clearTimeout(revealTimer);
      revealTimer = setTimeout(() => {
        setVisible(true);
        try { localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.lastShownAt, String(Date.now())); } catch { /* optional */ }
      }, PWA_CONFIG.installRevealDelayMs);
    };
    const onPrompt = (event: Event) => {
      event.preventDefault();
      setPrompt(event as BeforeInstallPromptEvent);
      reveal(true);
    };
    const onInstalled = () => {
      setInstalled(true);
      setVisible(false);
      setPrompt(null);
      try { localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.installedAt, String(Date.now())); } catch { /* optional */ }
    };

    window.addEventListener("beforeinstallprompt", onPrompt);
    window.addEventListener("appinstalled", onInstalled);
    if (isIos) reveal(false);

    return () => {
      if (revealTimer) clearTimeout(revealTimer);
      window.removeEventListener("beforeinstallprompt", onPrompt);
      window.removeEventListener("appinstalled", onInstalled);
    };
  }, [isIos]);

  const install = async () => {
    if (!prompt) {
      setShowIosHelp(true);
      return;
    }
    try {
      await prompt.prompt();
      const choice = await prompt.userChoice;
      if (choice.outcome === "accepted") {
        setInstalled(true);
        try { localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.installedAt, String(Date.now())); } catch { /* optional */ }
      } else {
        try {
          const until = Date.now() + PWA_CONFIG.installDismissalDays * 86_400_000;
          localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.dismissedUntil, String(until));
        } catch { /* optional */ }
      }
    } finally {
      setPrompt(null);
      setVisible(false);
    }
  };

  const dismiss = () => {
    setVisible(false);
    try {
      const until = Date.now() + PWA_CONFIG.installDismissalDays * 86_400_000;
      localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.dismissedUntil, String(until));
    } catch {
      // Storage can be unavailable in private browsing; dismissal still works now.
    }
  };

  const optOut = () => {
    setVisible(false);
    try { localStorage.setItem(PWA_INSTALL_STORAGE_KEYS.optedOut, 'true'); } catch { /* optional */ }
  };

  return (
    <AnimatePresence>
      {visible && !installed ? (
        <motion.aside
          key="pwa-install"
          initial={{ y: 100, opacity: 0, scale: 0.96 }}
          animate={{ y: 0, opacity: 1, scale: 1 }}
          exit={{ y: 80, opacity: 0, scale: 0.98 }}
          transition={{ type: "spring", stiffness: 260, damping: 26 }}
          className="fixed inset-x-3 bottom-[max(1rem,env(safe-area-inset-bottom))] z-[240] mx-auto max-w-md overflow-hidden rounded-3xl border border-white/10 bg-[linear-gradient(150deg,rgba(13,22,64,.98),rgba(4,7,20,.98))] text-white shadow-[0_30px_90px_rgba(0,0,0,.55)] backdrop-blur-2xl"
          aria-labelledby="pwa-install-title"
        >
          <div className="h-1 bg-gradient-to-r from-amber-400 via-cyan-300 to-indigo-400" />
          <div className="p-5">
            <div className="flex items-start gap-4">
              <div className="grid h-14 w-14 shrink-0 place-items-center rounded-2xl bg-gradient-to-br from-amber-300 to-orange-400 text-2xl font-black text-[#040714] shadow-lg shadow-amber-500/20">
                K
              </div>
              <div className="min-w-0 flex-1">
                <p className="mb-1 text-[10px] font-extrabold uppercase tracking-[.22em] text-cyan-300">
                  Your city intelligence, elevated
                </p>
                <h2
                  id="pwa-install-title"
                  className="text-lg font-black leading-tight"
                >
                  Install KWIN City
                </h2>
                <p className="mt-1 text-sm leading-5 text-slate-300">
                  Faster launches, an offline safety net, and no app store
                  required.
                </p>
              </div>
              <button
                type="button"
                onClick={dismiss}
                aria-label="Dismiss install suggestion for 30 days"
                className="rounded-lg p-1.5 text-slate-400 transition hover:bg-white/10 hover:text-white"
              >
                ×
              </button>
            </div>

            {showIosHelp ? (
              <div className="mt-4 rounded-2xl border border-cyan-300/15 bg-cyan-300/[.06] p-3 text-sm leading-6 text-slate-200">
                In Safari, tap <strong>Share</strong>, then choose{" "}
                <strong>Add to Home Screen</strong> and confirm{" "}
                <strong>Add</strong>.
              </div>
            ) : null}

            <div className="mt-4 grid grid-cols-2 gap-2.5">
              <button
                type="button"
                onClick={install}
                className="rounded-xl bg-gradient-to-r from-amber-300 to-orange-400 px-4 py-3 text-sm font-black text-[#040714] transition hover:brightness-105"
              >
                {isIos && !prompt ? "How to install" : "Install free"}
              </button>
              <Link
                href="/download"
                onClick={dismiss}
                className="rounded-xl border border-white/15 px-4 py-3 text-center text-sm font-bold text-slate-200 transition hover:border-white/30 hover:bg-white/[.06]"
              >
                Explore the app
              </Link>
            </div>
            <div className="mt-3 flex items-center justify-center gap-4 text-xs text-slate-400">
              <button type="button" onClick={dismiss} className="hover:text-white hover:underline">Not now</button>
              <button type="button" onClick={optOut} className="hover:text-white hover:underline">Don’t ask again</button>
            </div>
          </div>
        </motion.aside>
      ) : null}
    </AnimatePresence>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { PWA_CONFIG } from "@/lib/pwa/config";

export default function PwaRegistration() {
  const [waitingWorker, setWaitingWorker] = useState<ServiceWorker | null>(
    null,
  );
  const [isOnline, setIsOnline] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const reloadOnControllerChange = useRef(false);

  const applyUpdate = useCallback(() => {
    if (!waitingWorker) return;
    reloadOnControllerChange.current = true;
    setIsUpdating(true);
    waitingWorker.postMessage({ type: "SKIP_WAITING" });
  }, [waitingWorker]);

  useEffect(() => {
    if (!("serviceWorker" in navigator)) return;

    if (process.env.NODE_ENV !== "production") {
      navigator.serviceWorker
        .getRegistrations()
        .then((registrations) =>
          Promise.all(
            registrations.map((registration) => registration.unregister()),
          ),
        )
        .catch(() => undefined);
      return;
    }

    let intervalId: ReturnType<typeof setInterval> | undefined;
    let disposed = false;

    const observeRegistration = (registration: ServiceWorkerRegistration) => {
      if (registration.waiting && navigator.serviceWorker.controller) {
        setWaitingWorker(registration.waiting);
      }
      registration.addEventListener("updatefound", () => {
        const worker = registration.installing;
        if (!worker) return;
        worker.addEventListener("statechange", () => {
          if (
            worker.state === "installed" &&
            navigator.serviceWorker.controller
          ) {
            setWaitingWorker(worker);
          }
        });
      });
      intervalId = setInterval(
        () => registration.update().catch(() => undefined),
        PWA_CONFIG.updateCheckIntervalMs,
      );
    };

    navigator.serviceWorker
      .register(PWA_CONFIG.serviceWorkerUrl, {
        scope: PWA_CONFIG.serviceWorkerScope,
        updateViaCache: "none",
      })
      .then((registration) => {
        if (!disposed) observeRegistration(registration);
      })
      .catch((error) => {
        if (process.env.NODE_ENV !== "production") {
          console.warn("[PWA] Service worker registration failed.", error);
        }
      });

    const onControllerChange = () => {
      if (reloadOnControllerChange.current) window.location.reload();
    };
    navigator.serviceWorker.addEventListener(
      "controllerchange",
      onControllerChange,
    );

    return () => {
      disposed = true;
      if (intervalId) clearInterval(intervalId);
      navigator.serviceWorker.removeEventListener(
        "controllerchange",
        onControllerChange,
      );
    };
  }, []);

  useEffect(() => {
    const sync = () => setIsOnline(navigator.onLine);
    sync();
    window.addEventListener("online", sync);
    window.addEventListener("offline", sync);
    return () => {
      window.removeEventListener("online", sync);
      window.removeEventListener("offline", sync);
    };
  }, []);

  return (
    <div
      className="pointer-events-none fixed inset-x-0 top-0 z-[250] flex flex-col items-center gap-2 p-3"
      aria-live="polite"
      aria-atomic="true"
    >
      {!isOnline ? (
        <div className="pointer-events-auto flex max-w-lg items-center gap-3 rounded-full border border-amber-300/30 bg-[#07101f]/95 px-4 py-2 text-sm font-semibold text-white shadow-2xl backdrop-blur-xl">
          <span className="h-2.5 w-2.5 animate-pulse rounded-full bg-amber-400" />
          Offline mode · showing saved content where available
        </div>
      ) : null}

      {waitingWorker ? (
        <div className="pointer-events-auto flex w-full max-w-lg items-center gap-3 rounded-2xl border border-cyan-300/20 bg-[#07101f]/95 p-3 text-white shadow-2xl backdrop-blur-xl">
          <div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-gradient-to-br from-cyan-300 to-amber-300 font-black text-[#040714]">
            K
          </div>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-extrabold">
              A fresher KWIN City is ready
            </p>
            <p className="text-xs text-slate-300">
              Update safely without losing your place.
            </p>
          </div>
          <button
            type="button"
            onClick={applyUpdate}
            disabled={isUpdating}
            className="rounded-xl bg-amber-300 px-4 py-2 text-xs font-extrabold text-[#040714] transition hover:bg-amber-200 disabled:opacity-60"
          >
            {isUpdating ? "Updating…" : "Update"}
          </button>
          <button
            type="button"
            onClick={() => setWaitingWorker(null)}
            className="rounded-lg p-2 text-slate-300 transition hover:bg-white/10 hover:text-white"
            aria-label="Dismiss update notification"
          >
            ×
          </button>
        </div>
      ) : null}
    </div>
  );
}

