                <span
                  className={`rounded-full border px-2 py-0.5 text-[11px] font-semibold ${statusStyles[source.status]}`}
                >
                  {source.status === "pending-verification"
                    ? "Pending primary verification"
                    : source.status === "verified"
                      ? "Primary source"
                      : "Contextual source"}
