import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import type { DatasetConfig } from '@/lib/data-insights-datasets';
import { CHART_COLORS } from './constants';

type ChartRendererProps = {
  data: Record<string, string | number>[];
  cfg: DatasetConfig;
};

export function ChartRenderer({ data, cfg }: ChartRendererProps) {
  const formatValue = (value: number) =>
    value >= 1_000_000
      ? `${(value / 1_000_000).toFixed(1)}M`
      : value >= 1_000
      ? `${(value / 1_000).toFixed(1)}K`
      : String(Math.round(value));

  const tickStyle = { fill: '#94A3B8', fontSize: 11 };
  const common = { data, margin: { top: 8, right: 16, left: 0, bottom: 60 } };

  if (cfg.chartType === 'pie') {
    const chartDescription = `Pie chart: ${cfg.description}. Categories shown: ${data.map((item) => `${item[cfg.xField]}: ${formatValue(Number(item[cfg.yField] ?? 0))}`).join(', ')}`;
    return (
      <figure role="img" aria-label={cfg.label} aria-describedby={`chart-desc-${cfg.id}`}>
        <ResponsiveContainer width="100%" height={340}>
          <PieChart>
            <Pie
              data={data}
              dataKey={cfg.yField}
              nameKey={cfg.xField}
              cx="50%"
              cy="45%"
              outerRadius={110}
              label={({ name, percent }) => `${String(name).slice(0, 18)} (${((percent ?? 0) * 100).toFixed(0)}%)`}
              labelLine={false}
            >
              {data.map((_, index) => (
                <Cell key={index} fill={CHART_COLORS[index % CHART_COLORS.length]} />
              ))}
            </Pie>
            <Tooltip formatter={(value) => [formatValue(Number(value ?? 0)), cfg.yField]} />
          </PieChart>
        </ResponsiveContainer>
        <figcaption id={`chart-desc-${cfg.id}`} className="sr-only">{chartDescription}</figcaption>
      </figure>
    );
  }

  if (cfg.chartType === 'area') {
    const chartDescription = `Area chart: ${cfg.description}. ${cfg.note ? `Note: ${cfg.note}` : ''}`;
    return (
      <figure role="img" aria-label={cfg.label} aria-describedby={`chart-desc-${cfg.id}`}>
        <ResponsiveContainer width="100%" height={340}>
          <AreaChart {...common}>
            <defs>
              <linearGradient id={`area-gradient-${cfg.id}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#F5A623" stopOpacity={0.25} />
                <stop offset="95%" stopColor="#F5A623" stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#1E293B" />
            <XAxis dataKey={cfg.xField} tick={tickStyle} angle={-40} textAnchor="end" interval="preserveStartEnd" />
            <YAxis tick={tickStyle} tickFormatter={formatValue} />
            <Tooltip formatter={(value) => [formatValue(Number(value ?? 0)), cfg.unit ?? cfg.yField]} />
            <Area type="monotone" dataKey={cfg.yField} stroke="#F5A623" fill={`url(#area-gradient-${cfg.id})`} strokeWidth={2} />
          </AreaChart>
        </ResponsiveContainer>
        <figcaption id={`chart-desc-${cfg.id}`} className="sr-only">{chartDescription}</figcaption>
      </figure>
    );
  }

  if (cfg.chartType === 'line') {
    const chartDescription = `Line chart: ${cfg.description}. ${cfg.note ? `Note: ${cfg.note}` : ''}`;
    return (
      <figure role="img" aria-label={cfg.label} aria-describedby={`chart-desc-${cfg.id}`}>
        <ResponsiveContainer width="100%" height={340}>
          <LineChart {...common}>
            <CartesianGrid strokeDasharray="3 3" stroke="#1E293B" />
            <XAxis dataKey={cfg.xField} tick={tickStyle} angle={-40} textAnchor="end" />
            <YAxis tick={tickStyle} tickFormatter={formatValue} />
            <Tooltip formatter={(value) => [formatValue(Number(value ?? 0)), cfg.unit ?? cfg.yField]} />
            <Line type="monotone" dataKey={cfg.yField} stroke="#3B82F6" strokeWidth={2} dot={false} />
          </LineChart>
        </ResponsiveContainer>
        <figcaption id={`chart-desc-${cfg.id}`} className="sr-only">{chartDescription}</figcaption>
      </figure>
    );
  }

  return (
    <ResponsiveContainer width="100%" height={340}>
      <BarChart {...common}>
        <CartesianGrid strokeDasharray="3 3" stroke="#1E293B" />
        <XAxis dataKey={cfg.xField} tick={tickStyle} angle={-40} textAnchor="end" interval="preserveStartEnd" />
        <YAxis tick={tickStyle} tickFormatter={formatValue} />
        <Tooltip formatter={(value) => [formatValue(Number(value ?? 0)), cfg.unit ?? cfg.yField]} />
        <Bar dataKey={cfg.yField} radius={[4, 4, 0, 0]}>
          {data.map((_, index) => (
            <Cell key={index} fill={CHART_COLORS[index % CHART_COLORS.length]} />
          ))}
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  );
}

'use client';

import { useCallback, useState } from 'react';
import type { ChartType, DatasetConfig } from '@/lib/data-insights-datasets';
import { ChartRenderer } from './ChartRenderer';
import { LOCAL_DATA } from './constants';
import { normaliseRows } from './normaliseRows';

type FetchState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'error'; message: string; hint?: string }
  | { status: 'ok'; data: Record<string, string | number>[] };

const CHART_TYPES: ChartType[] = ['bar', 'line', 'area', 'pie'];

type DatasetCardProps = {
  cfg: DatasetConfig;
};

export function DatasetCard({ cfg }: DatasetCardProps) {
  const [state, setState] = useState<FetchState>({ status: 'idle' });
  const [chartType, setChartType] = useState<ChartType>(cfg.chartType);
  const [limit, setLimit] = useState(30);

  const load = useCallback(async () => {
    if (cfg.dataset === '__local__') {
      setState({ status: 'ok', data: LOCAL_DATA[cfg.id] ?? [] });
      return;
    }

    setState({ status: 'loading' });

    try {
      const response = await fetch(`/api/opencity?dataset=${encodeURIComponent(cfg.dataset)}&limit=${limit}`);
      const json = await response.json();

      if (!response.ok || json.error) {
        setState({
          status: 'error',
          message: json.error ?? 'Failed to fetch data',
          hint: json.hint,
        });
        return;
      }

      const records: Record<string, unknown>[] = json.result?.records ?? [];
      if (!records.length) {
        setState({ status: 'error', message: 'Dataset returned no table records.', hint: json.hint });
        return;
      }

      setState({ status: 'ok', data: normaliseRows(records, cfg, limit) });
    } catch (error) {
      setState({
        status: 'error',
        message: error instanceof Error ? error.message : 'Network error',
      });
    }
  }, [cfg, limit]);

  return (
    <div className="rounded-2xl border border-white/8 bg-[rgba(255,255,255,0.03)] overflow-hidden flex flex-col">
      <div className="px-6 pt-6 pb-4 border-b border-white/8">
        <div className="flex items-start justify-between gap-3 mb-2">
          <span
            className="text-[10px] font-bold tracking-widest uppercase px-2.5 py-1 rounded-full"
            style={{ backgroundColor: `${cfg.tagColor}18`, color: cfg.tagColor }}
          >
            {cfg.tag}
          </span>
          {cfg.dataset !== '__local__' ? (
            <a
              href={`https://data.opencity.in/dataset/${cfg.dataset}`}
              target="_blank"
              rel="noopener noreferrer"
              className="kwin-text-on-dark-muted text-[10px] transition-colors hover:text-white"
            >
              ↗ OpenCity
            </a>
          ) : null}
        </div>
        <h3 className="text-lg font-bold text-white mb-1">{cfg.label}</h3>
        <p className="text-sm text-[#94A3B8] leading-relaxed">{cfg.description}</p>
      </div>

      <div className="flex-1 px-4 py-5 min-h-[380px] flex flex-col">
        {state.status === 'idle' ? (
          <div className="flex-1 flex flex-col items-center justify-center gap-4">
            {cfg.dataset !== '__local__' ? (
              <label className="kwin-text-on-dark-muted flex items-center gap-2 text-xs">
                Show top
                <select
                  className="bg-[#0D1333] border border-white/10 rounded-lg px-2 py-1 text-white text-xs"
                  value={limit}
                  onChange={(event) => setLimit(parseInt(event.target.value, 10))}
                >
                  {[15, 30, 50, 100].map((count) => (
                    <option key={count} value={count}>{count}</option>
                  ))}
                </select>
                records
              </label>
            ) : null}

            <button
              onClick={load}
              className="inline-flex items-center gap-2 px-6 py-3 rounded-xl font-bold text-sm text-[#040714] bg-[linear-gradient(135deg,#F5A623,#E8A020)] hover:brightness-110 transition-all"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
              </svg>
              Generate Chart
            </button>
          </div>
        ) : null}

        {state.status === 'loading' ? (
          <div className="flex-1 flex items-center justify-center gap-3 text-[#94A3B8]">
            <div className="w-5 h-5 rounded-full border-2 border-[#F5A623] border-t-transparent animate-spin" />
            Fetching from data.opencity.in…
          </div>
        ) : null}

        {state.status === 'error' ? (
          <div className="flex-1 flex flex-col items-center justify-center gap-3 text-center px-4">
            <div className="w-10 h-10 rounded-full bg-red-500/10 flex items-center justify-center text-red-400 text-xl">!</div>
            <p className="text-red-400 text-sm font-semibold">{state.message}</p>
            {state.hint ? <p className="kwin-text-on-dark-muted text-xs">{state.hint}</p> : null}
            <button onClick={load} className="btn btn-outline-light text-xs px-4 py-2">Retry</button>
          </div>
        ) : null}

        {state.status === 'ok' ? (
          <>
            <div className="flex justify-end gap-1 mb-3">
              {CHART_TYPES.map((type) => (
                <button
                  key={type}
                  onClick={() => setChartType(type)}
                  className={`text-[10px] font-bold uppercase tracking-wide px-2.5 py-1 rounded-lg transition-colors ${
                    chartType === type
                      ? 'bg-[#F5A623] text-[#040714]'
                      : 'kwin-text-on-dark-muted hover:text-white hover:bg-white/5'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>

            <ChartRenderer data={state.data} cfg={{ ...cfg, chartType }} />

            {cfg.note ? (
              <p className="kwin-text-on-dark-muted mt-3 text-center text-[10px]">{cfg.note}</p>
            ) : null}

            <button
              onClick={() => setState({ status: 'idle' })}
              className="kwin-text-on-dark-muted mt-3 self-center text-xs transition-colors hover:text-white"
            >
              ← Reset
            </button>
          </>
        ) : null}
      </div>
    </div>
  );
}

