import Link from 'next/link';
import LanguageSwitcher from '@/components/LanguageSwitcher';
import ToolFinder from '@/components/header/ToolFinder';
import { GROUP_STORIES, type HeaderLabels } from '@/components/header/config';
import type { AuthUser, NavGroup } from '@/components/header/types';
import type { Locale } from '@/lib/i18n/locales';

type MobileMenuSheetProps = {
  menuGroups: NavGroup[];
  labels: HeaderLabels;
  locale: Locale;
  setLocale: (nextLocale: Locale) => void;
  currentUser: AuthUser | null;
  mobileOpenGroup: string | null;
  isActive: (href: string) => boolean;
  isGroupActive: (group: NavGroup) => boolean;
  onToggleGroup: (key: string) => void;
  onCloseMenu: () => void;
  onOpenSearch: () => void;
};

export default function MobileMenuSheet({
  menuGroups,
  labels,
  locale,
  setLocale,
  currentUser,
  mobileOpenGroup,
  isActive,
  isGroupActive,
  onToggleGroup,
  onCloseMenu,
  onOpenSearch,
