            <option value="primary">{l({ en: 'Original sources only', kn: 'ಮೂಲ ಮೂಲಗಳು ಮಾತ್ರ', hi: 'केवल मूल स्रोत', ta: 'மூல மூலங்கள் மட்டும்' })}</option>
          </select>
