import { formatDate } from './utils';
import type { ReaderCluster, ReaderItem, ReaderLocale, ReaderText } from './types';

function getSourceTierCopy(
  l: ReaderText,
  tier: ReaderItem['sourceTier'],
): { label: string; className: string } {
  if (tier === 'primary') {
    return {
      label: l({ en: 'Primary', kn: 'ಪ್ರಾಥಮಿಕ', hi: 'प्राथमिक', ta: 'முதன்மை' }),
      className: 'border-emerald-200 bg-emerald-50 text-emerald-800',
    };
  }

  if (tier === 'official') {
    return {
      label: l({ en: 'Official', kn: 'ಅಧಿಕೃತ', hi: 'आधिकारिक', ta: 'அதிகாரப்பூர்வ' }),
      className: 'border-sky-200 bg-sky-50 text-sky-800',
    };
  }

  return {
    label: l({ en: 'Discovery', kn: 'ಅನ್ವೇಷಣೆ', hi: 'खोज', ta: 'கண்டுபிடிப்பு' }),
    className: 'border-slate-200 bg-slate-100 text-slate-700',
  };
}

type ReaderResultsProps = {
  l: ReaderText;
  locale: ReaderLocale;
  isLoading: boolean;
  error: string | null;
  hasLoadedData: boolean;
  items: ReaderItem[];
  onSelectItem: (item: ReaderItem) => void;
  savedIds?: string[];
  readIds?: string[];
  onToggleSaved?: (id: string, item?: ReaderItem) => void;
  onToggleMutedDomain?: (domain: string) => void;
};

export function ReaderResults({
  l,
  locale,
  isLoading,
  error,
  hasLoadedData,
  items,
  onSelectItem,
  savedIds = [],
  readIds = [],
  onToggleSaved,
  onToggleMutedDomain,
}: ReaderResultsProps) {
  if (error) {
    return (
      <div className="rounded-2xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800">
        {error}
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 md:gap-5">
        {Array.from({ length: 9 }).map((_, index) => (
          <div key={index} className="rounded-2xl border border-slate-200 bg-white p-5 animate-pulse">
            <div className="h-3 w-24 rounded bg-slate-200" />
            <div className="mt-3 h-5 w-11/12 rounded bg-slate-200" />
            <div className="mt-2 h-5 w-4/5 rounded bg-slate-200" />
            <div className="mt-4 h-3 w-full rounded bg-slate-200" />
            <div className="mt-2 h-3 w-full rounded bg-slate-200" />
            <div className="mt-2 h-3 w-5/6 rounded bg-slate-200" />
          </div>
        ))}
      </div>
    );
  }

  if (items.length) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 md:gap-5">
        {items.map((item) => (
          <article
            key={`${item.link}-${item.title}`}
            className="group rounded-2xl border border-slate-200 bg-white p-5 shadow-[0_10px_28px_rgba(15,23,42,0.06)] transition-all hover:-translate-y-0.5 hover:shadow-[0_14px_30px_rgba(15,23,42,0.10)]"
          >
            <div className="flex items-center justify-between gap-3 mb-3">
              <div className="flex flex-wrap items-center gap-2">
                <span
                  className={`rounded-full border px-2.5 py-1 text-[11px] font-bold tracking-[0.08em] uppercase ${getSourceTierCopy(l, item.sourceTier).className}`}
                >
                  {getSourceTierCopy(l, item.sourceTier).label}
                </span>
                <span className="rounded-full border border-slate-200 bg-slate-50 px-2.5 py-1 text-[11px] font-semibold tracking-[0.06em] uppercase text-slate-600">
                  {item.source}
                </span>
              </div>
              <span className="text-[11px] text-slate-500">{formatDate(item.publishedAt, locale)}</span>
            </div>

            <h2 className="text-lg font-extrabold leading-6 text-slate-900 mb-3 line-clamp-3">{item.title}</h2>
            {(item as ReaderItem & { cluster?: ReaderCluster }).cluster ? (
              <div className="mb-3 rounded-lg bg-cyan-50 px-3 py-2 text-xs text-cyan-900">
                <strong>{(item as ReaderItem & { cluster: ReaderCluster }).cluster.sourceCount} source{(item as ReaderItem & { cluster: ReaderCluster }).cluster.sourceCount === 1 ? '' : 's'}</strong>
                {' · '}{(item as ReaderItem & { cluster: ReaderCluster }).cluster.whyThisMatters.join(' · ')}
              </div>
            ) : null}
            <p className="text-sm text-slate-700 leading-7 min-h-[126px]">{item.summary}</p>

            <div className="mt-4 flex items-center justify-between gap-3">
              <button
                onClick={() => onSelectItem(item)}
                className="inline-flex items-center gap-1.5 rounded-lg bg-slate-900 px-3 py-2 text-xs font-semibold text-white hover:bg-slate-800"
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5">
                  <path d="M10.75 4.75a.75.75 0 0 0-1.5 0v4.5h-4.5a.75.75 0 0 0 0 1.5h4.5v4.5a.75.75 0 0 0 1.5 0v-4.5h4.5a.75.75 0 0 0 0-1.5h-4.5v-4.5Z" />
                </svg>
                {l({ en: 'Read in Reader', kn: 'ರೀಡರ್‌ನಲ್ಲಿ ಓದಿ', hi: 'रीडर में पढ़ें', ta: 'ரீடரில் படிக்க' })}
              </button>
              <div className="flex items-center gap-2">
                <button onClick={() => onToggleSaved?.(item.link, item)} className="text-xs font-semibold text-slate-600 hover:text-slate-950">
                  {savedIds.includes(item.link) ? 'Saved' : 'Save'}
                </button>
                <button onClick={() => onToggleMutedDomain?.(new URL(item.originalLink || item.link).hostname.replace(/^www\./, ''))} className="text-xs font-semibold text-slate-500 hover:text-slate-950">
                  Mute source
                </button>
              </div>
              <a
                href={item.link}
                target="_blank"
                rel="noreferrer"
                className="text-xs font-semibold text-slate-500 hover:text-slate-800"
              >
                {l({ en: 'Original', kn: 'ಮೂಲ', hi: 'मूल', ta: 'மூலம்' })} ↗
              </a>
            </div>
            {readIds.includes(item.link) ? <span className="mt-3 block text-[11px] font-semibold uppercase tracking-wide text-slate-400">Read</span> : <span className="mt-3 block text-[11px] font-semibold uppercase tracking-wide text-cyan-700">Unread</span>}
          </article>
        ))}
      </div>
    );
  }

  if (hasLoadedData) {
    return (
      <div className="rounded-2xl border border-slate-200 bg-white p-6 text-sm text-slate-700">
        {l({
          en: 'No stories match the current filters. Try changing the topic keyword or widening source/domain/time filters.',
          kn: 'ಪ್ರಸ್ತುತ ಫಿಲ್ಟರ್‌ಗಳಿಗೆ ಹೊಂದುವ ಕಥೆಗಳಿಲ್ಲ. ವಿಷಯ ಕೀವರ್ಡ್ ಬದಲಿಸಿ ಅಥವಾ ಮೂಲ/ಡೊಮೇನ್/ಸಮಯ ಫಿಲ್ಟರ್ ವಿಸ್ತರಿಸಿ.',
          hi: 'वर्तमान फ़िल्टर से कोई कहानी मेल नहीं खाती। विषय कीवर्ड बदलें या स्रोत/डोमेन/समय फ़िल्टर व्यापक करें।',
          ta: 'தற்போதைய வடிகட்டிகளுக்கு பொருந்தும் செய்திகள் இல்லை. தலைப்பு முக்கியச்சொல்லை மாற்றவும் அல்லது மூலம்/டொமைன்/நேர வடிகட்டிகளை விரிவுபடுத்தவும்.',
        })}
      </div>
    );
  }

  return (
