export const PRESET_STORAGE_KEY = 'kwin-news-reader-presets-v1';
export const LAST_READER_STATE_STORAGE_KEY = 'kwin-news-reader-last-state-v1';

export const DEFAULT_OPML_URL = '/feeds/kwin-city-news-feeds.opml';
export const DEFAULT_STORY_LIMIT = 36;

import type {
  EvidenceStatus,
  IntelligenceBrief,
  IntelligenceLens,
  ReaderCluster,
  ReaderItem,
} from './types';
import { getDomain } from './utils';

const UNAVAILABLE_SUMMARIES = new Set(['', 'Summary unavailable from this feed.']);

function unique(values: string[]) {
  return [...new Set(values.filter(Boolean))];
}

function distinctPublisherCount(items: ReaderItem[]) {
  return new Set(items.map((item) => getDomain(item.originalLink || item.link)).filter(Boolean)).size;
}

function statusFor(items: ReaderItem[]): EvidenceStatus {
  if (items.some((item) => item.provenance === 'direct-institutional')) return 'confirmed-primary';
  if (distinctPublisherCount(items) > 1 && items.some((item) => item.provenance === 'direct-publisher')) return 'corroborated';
  if (items.some((item) => item.provenance === 'direct-publisher')) return 'publisher-reported';
  return 'discovery-only';
}

const STATUS_LABELS: Record<EvidenceStatus, string> = {
  'confirmed-primary': 'Primary evidence available',
  corroborated: 'Covered by multiple distinct publishers',
  'publisher-reported': 'Publisher-reported signal',
  'discovery-only': 'Discovery signal only',
};

function usableSummary(item: ReaderItem) {
  const summary = item.summary.trim();
  return !UNAVAILABLE_SUMMARIES.has(summary) && summary.toLowerCase() !== item.title.trim().toLowerCase()
    ? summary
    : '';
}

function buildUnknowns(item: ReaderItem, status: EvidenceStatus) {
  const unknowns: string[] = [];
  if (!usableSummary(item)) unknowns.push('The feed does not provide enough detail to verify the article beyond its headline.');
  if (!item.publishedAt) unknowns.push('The publisher did not provide a reliable publication timestamp.');
  if (status === 'discovery-only') unknowns.push('KWIN has not received this report through a direct publisher or institutional feed.');
  if (status !== 'confirmed-primary') unknowns.push('No primary document in this story cluster independently confirms the reported claim.');
  return unknowns;
}

function lensCopy(item: ReaderItem, status: EvidenceStatus): Record<IntelligenceLens, string> {
  const caution = status === 'confirmed-primary'
    ? 'A primary-source signal is present, but scope and implementation should still be checked.'
    : 'Treat this as a monitoring signal until primary evidence confirms scope and implementation.';
  const relevance = item.kwinRelevanceReasons?.[0] ?? 'This item matched KWIN’s monitored regional themes.';
  return {
    resident: `${relevance} ${caution}`,
    investor: `Use this as an early signal, not an investment conclusion. ${caution}`,
    government: `Review the named authority, policy instrument, funding and execution milestone before acting. ${caution}`,
    researcher: `The cluster preserves publisher, timestamp and provenance metadata for follow-up. ${caution}`,
  };
}

export function buildIntelligenceBrief(item: ReaderItem, cluster?: ReaderCluster, now = new Date()): IntelligenceBrief {
  const items = cluster?.items?.length ? cluster.items : [item];
  const publisherCount = distinctPublisherCount(items);
  const primaryCount = items.filter((entry) => entry.provenance === 'direct-institutional').length;
  const directPublisherCount = items.filter((entry) => entry.provenance === 'direct-publisher').length;
  const status = statusFor(items);
  const summary = usableSummary(item);
  const why = unique(item.kwinRelevanceReasons?.length ? item.kwinRelevanceReasons : cluster?.whyThisMatters ?? []);
  const known = [
    `KWIN observed ${items.length} report${items.length === 1 ? '' : 's'} from ${publisherCount} distinct publisher domain${publisherCount === 1 ? '' : 's'}.`,
    primaryCount ? `${primaryCount} report${primaryCount === 1 ? '' : 's'} came from a direct institutional feed.` : '',
    directPublisherCount ? `${directPublisherCount} report${directPublisherCount === 1 ? '' : 's'} came from a direct publisher feed.` : '',
    item.publishedAt ? `The selected report is dated ${new Date(item.publishedAt).toISOString()}.` : '',
  ];

  const timeline = [...items]
    .sort((a, b) => (new Date(a.publishedAt ?? 0).getTime() - new Date(b.publishedAt ?? 0).getTime()))
    .map((entry) => ({
      at: entry.publishedAt,
      label: entry.title,
      source: entry.source,
      provenance: entry.provenance,
    }));

  return {
    whatHappened: summary || `A monitored source published “${item.title}”. The feed supplied no independently usable article summary.`,
    whyItMatters: why.length ? why : ['This report appears in KWIN’s monitored intelligence feed.'],
    evidenceStatus: status,
    evidenceLabel: STATUS_LABELS[status],
    known: unique(known),
    unknown: buildUnknowns(item, status),
    timeline,
    lensCopy: lensCopy(item, status),
    questions: [
      {
        id: 'confirmed',
        question: 'Is this independently confirmed?',
        answer: status === 'confirmed-primary'
          ? 'A direct institutional source is present in this cluster. That confirms the source signal, but not every interpretation of it.'
          : `Not by primary evidence in this cluster. KWIN currently sees ${publisherCount} distinct publisher domain${publisherCount === 1 ? '' : 's'}.`,
      },
      {
        id: 'kwin',
        question: 'Why is this relevant to KWIN?',
        answer: why.length ? why.join(' ') : 'It matched the configured KWIN monitoring criteria; no stronger relevance explanation is available.',
      },
      {
        id: 'next',
        question: 'What should be verified next?',
        answer: status === 'confirmed-primary'
          ? 'Check the operative document, scope, funding, effective date and latest execution milestone.'
          : 'Look for an official order, agency publication, filing, tender, budget record or project-status update.',
      },
    ],
    generatedAt: now.toISOString(),
  };
}

import type { ReaderCluster, ReaderItem, ReaderSortMode } from './types';
import { getDomain } from './utils';
import { scoreRegionalPriority } from './regional-relevance';

const STOP_WORDS = new Set(['a', 'an', 'and', 'are', 'at', 'be', 'by', 'for', 'from', 'in', 'is', 'it', 'of', 'on', 'or', 'the', 'to', 'with']);

function tokens(value: string) {
  return new Set(
    value
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, ' ')
      .split(' ')
      .filter((token) => token.length > 2 && !STOP_WORDS.has(token)),
  );
}

function overlap(a: Set<string>, b: Set<string>) {
  let shared = 0;
  for (const token of a) if (b.has(token)) shared += 1;
  return shared / Math.max(1, Math.min(a.size, b.size));
}

function sourceWeight(item: ReaderItem) {
  if (item.provenance === 'direct-institutional') return 70;
  if (item.provenance === 'direct-publisher') return 55;
  if (item.provenance === 'source-filtered-discovery') return 30;
  return 15;
}

export function scoreReaderItem(item: ReaderItem, now = Date.now()) {
  const published = item.publishedAt ? new Date(item.publishedAt).getTime() : 0;
  const ageHours = published ? Math.max(0, (now - published) / 3_600_000) : 168;
  const recency = Math.max(0, 30 - Math.min(30, ageHours / 8));
  const specificity = Math.min(12, tokens(`${item.title} ${item.summary}`).size / 2);
  return Math.round(sourceWeight(item) + recency + specificity);
}

export function explainReaderRank(item: ReaderItem, clusterSize = 1) {
  const reasons: string[] = [];
  if (item.provenance === 'direct-institutional') reasons.push('direct institutional publication');
  else if (item.provenance === 'direct-publisher') reasons.push('direct publisher feed');
  else if (item.provenance === 'source-filtered-discovery') reasons.push('source-filtered discovery signal');
  else reasons.push('contextual monitoring signal');
  if (item.publishedAt && Date.now() - new Date(item.publishedAt).getTime() < 86_400_000) reasons.push('published in the last 24 hours');
  if (clusterSize > 1) reasons.push(`${clusterSize} distinct publisher domains cover this story`);
  return reasons;
}

export function clusterReaderItems(items: ReaderItem[]): ReaderCluster[] {
  const clusters: Array<{ items: ReaderItem[]; tokens: Set<string> }> = [];
  for (const item of items) {
    const itemTokens = tokens(item.title);
    const target = clusters.find((cluster) => overlap(cluster.tokens, itemTokens) >= 0.62);
    if (target) {
      target.items.push(item);
      itemTokens.forEach((token) => target.tokens.add(token));
    } else {
      clusters.push({ items: [item], tokens: itemTokens });
    }
  }

  return clusters.map((cluster) => {
    const itemsByScore = [...cluster.items].sort((a, b) => scoreReaderItem(b) - scoreReaderItem(a));
    const representative = itemsByScore[0];
    const domains = new Set(cluster.items.map((item) => getDomain(item.originalLink || item.link)));
    const bestTier = cluster.items.some((item) => item.provenance === 'direct-institutional')
      ? 'institutional'
      : cluster.items.some((item) => item.provenance === 'direct-publisher')
        ? 'publisher'
        : 'discovery';
    return {
      id: `${representative.link}-${representative.title}`,
      title: representative.title,
      summary: representative.summary,
      representative,
      items: itemsByScore,
      sourceCount: domains.size,
      confidence: bestTier === 'institutional' ? 'high' : bestTier === 'publisher' ? 'medium' : 'contextual',
      whyThisMatters: explainReaderRank(representative, domains.size),
      score: scoreReaderItem(representative) + Math.min(15, Math.max(0, domains.size - 1) * 5),
    };
  });
}

export function sortReaderClusters(clusters: ReaderCluster[], sort: ReaderSortMode) {
  return [...clusters].sort((a, b) => {
    if (sort === 'source-breadth') return b.sourceCount - a.sourceCount || b.score - a.score;
    if (sort === 'newest') {
      const aTime = a.representative.publishedAt ? new Date(a.representative.publishedAt).getTime() : 0;
      const bTime = b.representative.publishedAt ? new Date(b.representative.publishedAt).getTime() : 0;
      return bTime - aTime;
    }
    return b.score - a.score;
  });
}

function publishedTime(item: ReaderItem): number {
  if (!item.publishedAt) return 0;
  const timestamp = new Date(item.publishedAt).getTime();
  return Number.isNaN(timestamp) ? 0 : timestamp;
}

/** KWIN coverage uses an explicit relevance rank, independent of workspace sort. */
export function rankKwinClusters(clusters: ReaderCluster[]): ReaderCluster[] {
  return clusters
    .map((cluster) => {
      const relevantItems = cluster.items
        .filter((item) => item.isKwinRelated)
        .sort((a, b) =>
          (b.kwinRelevanceScore ?? 0) - (a.kwinRelevanceScore ?? 0)
          || publishedTime(b) - publishedTime(a));
      const representative = relevantItems[0];
      if (!representative) return null;

      return {
        ...cluster,
        id: `${representative.link}-${representative.title}`,
        title: representative.title,
        summary: representative.summary,
        representative,
        items: [...relevantItems, ...cluster.items.filter((item) => !item.isKwinRelated)],
        whyThisMatters: representative.kwinRelevanceReasons?.length
          ? representative.kwinRelevanceReasons
          : cluster.whyThisMatters,
      } satisfies ReaderCluster;
    })
    .filter((cluster): cluster is ReaderCluster => cluster !== null)
    .sort((a, b) =>
      (b.representative.kwinRelevanceScore ?? 0) - (a.representative.kwinRelevanceScore ?? 0)
      || publishedTime(b.representative) - publishedTime(a.representative));
}

/** Regional coverage is strictly newest-first; strategic relevance breaks timestamp ties. */
export function rankRegionalClusters(clusters: ReaderCluster[]): ReaderCluster[] {
  return clusters
    .map((cluster) => {
      const items = [...cluster.items].sort((a, b) => publishedTime(b) - publishedTime(a));
      const representative = items[0] ?? cluster.representative;
      const priority = scoreRegionalPriority(representative.title, representative.summary);
      return {
        ...cluster,
        id: `${representative.link}-${representative.title}`,
        title: representative.title,
        summary: representative.summary,
        representative,
        items,
        whyThisMatters: priority.reasons.length ? priority.reasons : cluster.whyThisMatters,
        score: cluster.score + priority.score,
      };
    })
    .sort((a, b) =>
      publishedTime(b.representative) - publishedTime(a.representative)
      || b.score - a.score);
}

export type KwinRelevance = {
  isRelevant: boolean;
  score: number;
  reasons: string[];
};

const IDENTITY_SIGNALS = [
  {
    label: 'KWIN City named in headline',
    pattern: /\bkwin[\s-]+city\b/i,
    titleScore: 100,
    bodyScore: 70,
  },
  {
    label: 'Knowledge Wellbeing Innovation City named',
    pattern:
      /\bknowledge\s*,?\s*well(?:being|ness)\s*(?:and|&)\s*innovation(?:\s+city)?\b/i,
    titleScore: 98,
    bodyScore: 68,
  },
  {
    label: 'KHIR City legacy name identified',
    pattern: /\bkhir[\s-]+city\b/i,
    titleScore: 88,
    bodyScore: 60,
  },
  {
    label: 'KWIN named explicitly',
    pattern: /\bkwin\b/i,
    titleScore: 82,
    bodyScore: 52,
  },
  {
    label: 'Kannada KWIN City named',
    pattern: /ಕ್ವಿನ್\s*ಸಿಟಿ/i,
    titleScore: 96,
    bodyScore: 66,
  },
] as const;

const CONTEXT_SIGNALS = [
  { label: 'Doddaballapura context', pattern: /\bdoddaballapura\b/i, score: 6 },
  { label: 'KIADB context', pattern: /\bkiadb\b/i, score: 5 },
  {
    label: 'North Bengaluru context',
    pattern: /\bnorth(?:ern)?\s+bengaluru\b/i,
    score: 4,
  },
  { label: 'Karnataka context', pattern: /\bkarnataka\b/i, score: 2 },
] as const;

/**
 * Classifies an article from its own editorial text only. Feed titles, search
 * queries, and OPML group names are intentionally excluded because discovery
 * providers can return false positives for even tightly scoped queries.
 */
export function scoreKwinRelevance(title: string, body: string): KwinRelevance {
  const cleanTitle = title.normalize('NFKC');
  const cleanBody = body.normalize('NFKC');
  const identity = IDENTITY_SIGNALS.find(
    (signal) =>
      signal.pattern.test(cleanTitle) || signal.pattern.test(cleanBody),
  );

  if (!identity) return { isRelevant: false, score: 0, reasons: [] };

  const titleMatch = identity.pattern.test(cleanTitle);
  let score = titleMatch ? identity.titleScore : identity.bodyScore;
  const reasons = [
    titleMatch
      ? identity.label
      : identity.label.replace('headline', 'article text'),
  ];

  for (const context of CONTEXT_SIGNALS) {
    if (context.pattern.test(`${cleanTitle} ${cleanBody}`)) {
      score += context.score;
      reasons.push(context.label);
    }
  }

  return { isRelevant: true, score: Math.min(100, score), reasons };
}

export type RegionalPriority = {
  score: number;
  reasons: string[];
};

type SignalGroup = {
  label: string;
  score: number;
  pattern: RegExp;
};

const PRIORITY_SIGNALS: SignalGroup[] = [
  {
    label: 'infrastructure and connectivity',
    score: 36,
    pattern:
      /\b(?:infrastructure|metro|rail(?:way)?|road|highway|expressway|corridor|airport|transit|mobility|logistics|power|energy|water|sewerage|utility|utilities|industrial\s+park|data\s+cent(?:er|re)|construction)\b/i,
  },
  {
    label: 'investment and economic development',
    score: 34,
    pattern:
      /\b(?:invest(?:ment|or|ing)?|capital|funding|fundraise|manufactur(?:e|ing)|factory|plant|facility|campus|technology\s+hub|jobs?|employment|economic\s+(?:growth|development)|industrial\s+development|fdi|crore|billion|million)\b/i,
  },
  {
    label: 'policy, planning, or regulation',
    score: 32,
    pattern:
      /\b(?:policy|policies|regulation|regulatory|approval|approved|cabinet|budget|master\s+plan|development\s+plan|land\s+use|zoning|notification|ordinance|bill|act|government\s+order|tender|public-private|ppp|kiadb|bmrda|bda|bbmp)\b/i,
  },
];

const REGIONAL_CONTEXT =
  /\b(?:bengaluru|bangalore|karnataka|doddaballapura|devanahalli|north\s+bengaluru|north\s+bangalore)\b/i;

/** Explainable domain priority. This boosts strategic coverage; it never hides other news. */
export function scoreRegionalPriority(
  title: string,
  body: string,
): RegionalPriority {
  const titleMatches = PRIORITY_SIGNALS.filter((signal) =>
    signal.pattern.test(title),
  );
  const bodyMatches = PRIORITY_SIGNALS.filter((signal) =>
    signal.pattern.test(body),
  );
  const matched = PRIORITY_SIGNALS.filter(
    (signal) => titleMatches.includes(signal) || bodyMatches.includes(signal),
  );
  const reasons = matched.map((signal) => signal.label);
  const titleScore = titleMatches.reduce(
    (total, signal) => total + signal.score,
    0,
  );
  const bodyOnlyScore = bodyMatches
    .filter((signal) => !titleMatches.includes(signal))
    .reduce((total, signal) => total + Math.round(signal.score * 0.55), 0);
  const contextBoost =
    REGIONAL_CONTEXT.test(`${title} ${body}`) && matched.length ? 8 : 0;

  return {
    score: Math.min(100, titleScore + bodyOnlyScore + contextBoost),
    reasons,
  };
}

import type { ReaderProvenance, ReaderSourceTier } from './types';

export type ReaderSourceFeed = {
  xmlUrl: string;
  htmlUrl?: string;
  title: string;
  groupPath: string[];
};

type SourceTierRule = {
  tier: ReaderSourceTier;
  groupMatch: RegExp;
};

const SOURCE_TIER_RULES: SourceTierRule[] = [
  {
    tier: 'primary',
    groupMatch: /^(Bengaluru Local Desk Feeds|Direct Publisher Feeds)$/i,
  },
  {
    tier: 'official',
    groupMatch: /^(Official Government Discovery Queries \(Verify Original Link\)|Official Government, State & Central Original-Source Signals|Official Government, State & Central Institutional Signals)$/i,
  },
  {
    tier: 'contextual',
    groupMatch: /^(KWIN Critical Alerts|Publisher-Specific KWIN Filters|KWIN Precision Watch|Strategic Context Signals)$/i,
  },
];

const OFFICIAL_HOSTS = new Set([
  'gov.in',
  'nic.in',
  'rbi.org.in',
  'pib.gov.in',
]);

function decodeEntities(input: string): string {
  return input
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .trim();
}

function getAttribute(block: string, attributeName: string): string {
  const match = block.match(new RegExp(`${attributeName}=(['"])(.*?)\\1`, 'i'));
  return match?.[2] ? decodeEntities(match[2]) : '';
}

function normalizeHostname(value: string): string {
  return value.toLowerCase().replace(/^www\./, '');
}

function getHostname(url: string): string {
  try {
    return normalizeHostname(new URL(url).hostname);
  } catch {
    return '';
  }
}

function isOfficialHostname(hostname: string): boolean {
  if (!hostname) {
    return false;
  }

  return hostname.endsWith('.gov.in') || hostname.endsWith('.nic.in') || OFFICIAL_HOSTS.has(hostname);
}

export function classifyReaderSourceTier(feed: ReaderSourceFeed): ReaderSourceTier {
  const hostname = getHostname(feed.xmlUrl) || getHostname(feed.htmlUrl ?? '');

  if (hostname === 'news.google.com') {
    return 'contextual';
  }

  for (const rule of SOURCE_TIER_RULES) {
    if (feed.groupPath.some((segment) => rule.groupMatch.test(segment))) {
      return rule.tier;
    }
  }

  if (isOfficialHostname(hostname)) {
    return 'official';
  }

  return 'contextual';
}

export function getReaderProvenance(feed: ReaderSourceFeed): ReaderProvenance {
  const hostname = getHostname(feed.xmlUrl);
  if (hostname === 'news.google.com') {
    return feed.groupPath.some((segment) => /Official Government/i.test(segment))
      ? 'source-filtered-discovery'
      : 'contextual-monitoring';
  }

  if (classifyReaderSourceTier(feed) === 'official') return 'direct-institutional';
  if (feed.groupPath.some((segment) => /Direct Publisher|Local Desk/i.test(segment))) return 'direct-publisher';
  return 'contextual-monitoring';
}

export function parseReaderFeedsFromOpml(opmlXml: string): ReaderSourceFeed[] {
  const bodyMatch = opmlXml.match(/<body[\s\S]*<\/body>/i);
  if (!bodyMatch) {
    return [];
  }

  const body = bodyMatch[0];
  const tokenPattern = /<outline\b[^>]*\/?>|<\/outline>/gi;
  const feedEntries: ReaderSourceFeed[] = [];
  const stack: Array<{ title: string }> = [];

  for (const token of body.match(tokenPattern) ?? []) {
    if (token.startsWith('</outline')) {
      stack.pop();
      continue;
    }

    const isSelfClosing = token.endsWith('/>');
    const text = getAttribute(token, 'text') || getAttribute(token, 'title');
    const xmlUrl = getAttribute(token, 'xmlUrl');
    const htmlUrl = getAttribute(token, 'htmlUrl');

    if (xmlUrl) {
      feedEntries.push({
        xmlUrl,
        htmlUrl: htmlUrl || undefined,
        title: text || xmlUrl,
        groupPath: stack.map((entry) => entry.title).filter(Boolean),
      });
      continue;
    }

    if (!isSelfClosing) {
      stack.push({ title: text });
    }
  }

  return feedEntries;
}

