async function copyText(value: string) {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(value);
    return;
  }

  const textarea = document.createElement('textarea');
  textarea.value = value;
  textarea.setAttribute('readonly', 'true');
  textarea.style.position = 'fixed';
  textarea.style.left = '-9999px';
  document.body.appendChild(textarea);
  textarea.select();
  document.execCommand('copy');
  textarea.remove();
}

export default function ShareActions({
  title,
  text,
  url = DEFAULT_SHARE_URL,
  copyLabel = 'Copy',
  copiedLabel = 'Copied',
  shareLabel = 'Share',
  xLabel = 'Post to X',
  className,
  tone = 'light',
}: ShareActionsProps) {
  const [copied, setCopied] = useState(false);
  const shareText = `${text}\n${url}`;
  const xIntentHref = `${X_INTENT_URL}?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}&via=${encodeURIComponent(X_HANDLE)}`;
  const buttonClass =
    tone === 'dark'
      ? 'border-white/12 bg-white/[0.06] text-white hover:border-white/24 hover:bg-white/[0.10]'
      : 'border-slate-200 bg-white text-slate-900 hover:border-slate-300 hover:bg-slate-50';

  const handleCopy = async () => {
    await copyText(shareText);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1800);
  };

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title, text, url });
        return;
      } catch {
        return;
      }
    }

    await handleCopy();
  };

  return (
    <div className={`flex flex-wrap items-center gap-2 ${className ?? ''}`} aria-live="polite">
      <button
        type="button"
        onClick={handleCopy}
        className={`inline-flex items-center gap-2 border px-3.5 py-2 text-xs font-bold transition ${buttonClass}`}
      >
        <CopyIcon />
        {copied ? copiedLabel : copyLabel}
      </button>
      <button
        type="button"
        onClick={handleShare}
        className={`inline-flex items-center gap-2 border px-3.5 py-2 text-xs font-bold transition ${buttonClass}`}
      >
        <ShareIcon />
        {shareLabel}
      </button>
      <a
        href={xIntentHref}
        target="_blank"
        rel="noopener noreferrer"
        className={`inline-flex items-center gap-2 border px-3.5 py-2 text-xs font-bold transition ${buttonClass}`}
      >
        <XIcon />
        {xLabel}
      </a>
    </div>
  );
}

