const ACQ_SOURCE_ID = 'acquisition-notification-buffers-derived';
export const ACQ_PHASES = ['phase-1', 'phase-2', 'phase-3'] as const;
export type AcquisitionPhaseId = (typeof ACQ_PHASES)[number];
export type AcquisitionPhaseVisibility = Record<AcquisitionPhaseId, boolean>;
export type MapPresentation = 'overview' | 'immersive';

const THREE_DIMENSIONAL_BUILDINGS_LAYER_ID = 'kwin-context-buildings-3d';

/**
 * Switches between an orientation-first overview and Mapbox's available 3D
 * building context. The building layer is deliberately contextual: it is not
 * a KWIN masterplan or a representation of proposed project assets.
 */
export function setMapPresentation(map: mapboxgl.Map, presentation: MapPresentation) {
  if (presentation === 'overview') {
    if (map.getLayer(THREE_DIMENSIONAL_BUILDINGS_LAYER_ID)) {
      map.setLayoutProperty(THREE_DIMENSIONAL_BUILDINGS_LAYER_ID, 'visibility', 'none');
    }
    map.easeTo({ pitch: 0, bearing: 0, duration: 700, essential: true });
    return;
  }

  try {
    if (!map.getLayer(THREE_DIMENSIONAL_BUILDINGS_LAYER_ID)) {
      map.addLayer({
        id: THREE_DIMENSIONAL_BUILDINGS_LAYER_ID,
        source: 'composite',
        'source-layer': 'building',
        filter: ['==', ['get', 'extrude'], 'true'],
        type: 'fill-extrusion',
        minzoom: 13,
        paint: {
          'fill-extrusion-color': '#94a3b8',
          'fill-extrusion-height': ['coalesce', ['get', 'height'], 0],
          'fill-extrusion-base': ['coalesce', ['get', 'min_height'], 0],
          'fill-extrusion-opacity': 0.72,
        },
      });
    } else {
      map.setLayoutProperty(THREE_DIMENSIONAL_BUILDINGS_LAYER_ID, 'visibility', 'visible');
    }
  } catch {
    // Some Mapbox styles may not expose a composite building source. The
    // pitched contextual orientation remains useful without it.
  }

  map.easeTo({ pitch: 58, bearing: -24, zoom: Math.max(map.getZoom(), 12.5), duration: 900, essential: true });
}

function getAcqPhaseFillLayerId(phase: AcquisitionPhaseId) {
  return `acquisition-notification-buffers-${phase}-fill`;
}

function getAcqPhaseLineLayerId(phase: AcquisitionPhaseId) {
  return `acquisition-notification-buffers-${phase}-line`;
}

function getAcqPhaseStyle(phase: AcquisitionPhaseId) {
  if (phase === 'phase-1') {
    return { fill: '#f59e0b', line: '#b45309' };
  }

  if (phase === 'phase-2') {
    return { fill: '#14b8a6', line: '#0f766e' };
  }

  return { fill: '#8b5cf6', line: '#6d28d9' };
}

export async function addAcquisitionNotificationBuffers(map: mapboxgl.Map) {
  if (map.getSource(ACQ_SOURCE_ID)) {
    return;
  }

  try {
    const response = await fetch('/api/value-add/spatial-explorer/export');
    if (!response.ok) {
      return;
    }

    const geoJson = await response.json();
    map.addSource(ACQ_SOURCE_ID, {
      type: 'geojson',
      data: geoJson,
    });

    for (const phase of ACQ_PHASES) {
      const style = getAcqPhaseStyle(phase);
      const fillLayerId = getAcqPhaseFillLayerId(phase);
      const lineLayerId = getAcqPhaseLineLayerId(phase);

      map.addLayer({
        id: fillLayerId,
        type: 'fill',
        source: ACQ_SOURCE_ID,
        filter: ['==', ['get', 'phase'], phase],
        paint: {
          'fill-color': style.fill,
          'fill-opacity': 0.18,
        },
        layout: {
          visibility: 'none',
        },
      });

      map.addLayer({
        id: lineLayerId,
        type: 'line',
        source: ACQ_SOURCE_ID,
        filter: ['==', ['get', 'phase'], phase],
        paint: {
          'line-color': style.line,
          'line-width': 2,
          'line-dasharray': [2, 2],
        },
        layout: {
          visibility: 'none',
        },
      });

      map.on('click', fillLayerId, (event) => {
        const feature = event.features?.[0];
        if (!feature) return;

        const properties = feature.properties ?? {};
        const title = typeof properties.corridor === 'string' ? properties.corridor : 'Derived acquisition zone';
        const phaseValue = typeof properties.phase === 'string' ? properties.phase : 'phase-unknown';
        const confidence = typeof properties.confidence === 'string' ? properties.confidence : 'low';

        new mapboxgl.Popup({ closeButton: true, closeOnClick: true })
          .setLngLat(event.lngLat)
          .setHTML(
            `<div style="font-family:system-ui,-apple-system,sans-serif;max-width:260px;">
              <p style="margin:0 0 4px 0;font-size:11px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:#6F3F00;">Acquisition Layer (Derived)</p>
              <p style="margin:0 0 4px 0;font-size:14px;font-weight:700;color:#0f172a;">${title}</p>
              <p style="margin:0 0 3px 0;font-size:12px;color:#334155;"><strong>Phase:</strong> ${phaseValue}</p>
              <p style="margin:0;font-size:12px;color:#334155;"><strong>Confidence:</strong> ${confidence}</p>
            </div>`
          )
          .addTo(map);
      });

      map.on('mouseenter', fillLayerId, () => {
        map.getCanvas().style.cursor = 'pointer';
      });

      map.on('mouseleave', fillLayerId, () => {
        map.getCanvas().style.cursor = '';
      });
    }
  } catch {
    // Fail silently to avoid breaking base map interactions.
  }
}

export function setAcquisitionNotificationVisibility(map: mapboxgl.Map, phaseVisibility: AcquisitionPhaseVisibility) {
  for (const phase of ACQ_PHASES) {
    const fillLayerId = getAcqPhaseFillLayerId(phase);
    const lineLayerId = getAcqPhaseLineLayerId(phase);
    const visibility = phaseVisibility[phase] ? 'visible' : 'none';

    if (map.getLayer(fillLayerId)) {
      map.setLayoutProperty(fillLayerId, 'visibility', visibility);
    }

    if (map.getLayer(lineLayerId)) {
      map.setLayoutProperty(lineLayerId, 'visibility', visibility);
    }
  }
}

'use client';

import { useState } from 'react';
import type { AccessibilityResult, ValueAddEnvelope } from '@/types/value-add';

export default function AccessibilityCalculator() {
  const [origin, setOrigin] = useState('KWIN City');
  const [destination, setDestination] = useState('Bengaluru International Airport');
  const [mode, setMode] = useState<'road' | 'transit' | 'air'>('road');
  const [includeProjected, setIncludeProjected] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<ValueAddEnvelope<AccessibilityResult> | null>(null);

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const response = await fetch('/api/value-add/accessibility', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          origin: origin.trim(),
          destination: destination.trim() || undefined,
          mode,
          includeProjected,
        }),
      });

      const payload = (await response.json()) as ValueAddEnvelope<AccessibilityResult> | { error?: string };
      if (!response.ok) {
        const message = 'error' in payload && typeof payload.error === 'string' ? payload.error : 'Unable to calculate accessibility.';
        setError(message);
        setResult(null);
        return;
      }

      setResult(payload as ValueAddEnvelope<AccessibilityResult>);
    } catch {
      setError('Unable to contact the service. Please try again.');
      setResult(null);
    } finally {
      setLoading(false);
    }
  }

  return (
    <section className="rounded-3xl border border-slate-200 bg-white p-6 md:p-8 shadow-sm">
      <h2 className="text-2xl font-bold text-slate-900">Accessibility Calculator</h2>
