'use client';

import { createContext, useContext, useMemo } from 'react';
import { translate, type Locale } from '@/lib/i18n/messages';
import { LocaleProvider, useLocale } from '@/lib/i18n/locale-context';

type I18nContextValue = {
  locale: Locale;
  setLocale: (nextLocale: Locale) => void;
  t: (key: string) => string;
};

const I18nContext = createContext<I18nContextValue | null>(null);

export default function I18nProvider({
  initialLocale,
  children,
}: {
  initialLocale?: string;
  children: React.ReactNode;
}) {
  return (
    <LocaleProvider initialLocale={initialLocale}>
      <I18nProviderInner>{children}</I18nProviderInner>
    </LocaleProvider>
  );
}

function I18nProviderInner({ children }: { children: React.ReactNode }) {
  const { locale, setLocale } = useLocale();
  const value = useMemo<I18nContextValue>(() => {
    const t = (key: string): string => translate(locale, key);

    return { locale, setLocale, t };
  }, [locale, setLocale]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useI18n must be used within I18nProvider');
  }
  return context;
}

import { DEFAULT_LOCALE, type Locale } from '@/lib/i18n/locales';

type Primitive = string | number | boolean | bigint | symbol | null | undefined;

export type DeepPartial<T> =
  T extends Primitive
    ? T
    : T extends Array<infer Item>
    ? Array<DeepPartial<Item>>
    : { [Key in keyof T]?: DeepPartial<T[Key]> };

export type LocalizedValue<T> = Record<typeof DEFAULT_LOCALE, T> & Partial<Record<Locale, T>>;

import type { DeepPartial } from './types';

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function mergeUnknownDeep(base: unknown, overrides?: unknown): unknown {
  if (overrides === undefined) {
    return base;
  }

  if (Array.isArray(base)) {
    return overrides ?? base;
  }

  if (!isRecord(base) || !isRecord(overrides)) {
    return overrides ?? base;
  }

  const result: Record<string, unknown> = { ...base };
  const overrideRecord = overrides;

  for (const key of Object.keys(overrideRecord)) {
    const overrideValue = overrideRecord[key];
    if (overrideValue === undefined) {
      continue;
    }

    const baseValue = result[key];
    result[key] = isRecord(baseValue) && isRecord(overrideValue)
      ? mergeUnknownDeep(baseValue, overrideValue)
      : overrideValue;
  }

  return result;
}

export function mergeDeep<T>(base: T, overrides?: DeepPartial<T>): T {
  return mergeUnknownDeep(base, overrides) as T;
}

export function resolvePath(obj: unknown, key: string): string | undefined {
  const parts = key.split('.');
  let current: unknown = obj;

  for (const part of parts) {
    if (!isRecord(current)) {
      return undefined;
    }
    current = current[part];
  }

  return typeof current === 'string' ? current : undefined;
}

