import { createContext, useContext, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getLocaleDefinition, normalizeLocale, type Locale } from '@/lib/i18n/locales';

type LocaleContextValue = {
  locale: Locale;
  setLocale: (nextLocale: Locale) => void;
};

const LocaleContext = createContext<LocaleContextValue | null>(null);

export function LocaleProvider({
  initialLocale,
  children,
}: {
  initialLocale?: string;
  children: React.ReactNode;
}) {
  const router = useRouter();
  const [locale, setLocaleState] = useState<Locale>(normalizeLocale(initialLocale));

  const value = useMemo<LocaleContextValue>(() => {
    const setLocale = (nextLocale: Locale) => {
      const normalized = normalizeLocale(nextLocale);
      setLocaleState(normalized);
      document.documentElement.lang = getLocaleDefinition(normalized).htmlLang;
      localStorage.setItem('kwin-locale', normalized);
      document.cookie = `kwin_locale=${normalized}; path=/; max-age=31536000; samesite=lax`;
      router.refresh();
    };

    return { locale, setLocale };
  }, [locale, router]);

  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() {
  const context = useContext(LocaleContext);
  if (!context) {
    throw new Error('useLocale must be used within LocaleProvider');
  }
  return context;
}

export const LOCALE_DEFINITIONS = [
  { code: 'en', label: 'English', nativeLabel: 'English', htmlLang: 'en-IN' },
  { code: 'kn', label: 'Kannada', nativeLabel: 'ಕನ್ನಡ', htmlLang: 'kn-IN' },
  { code: 'hi', label: 'Hindi', nativeLabel: 'हिन्दी', htmlLang: 'hi-IN' },
  { code: 'ta', label: 'Tamil', nativeLabel: 'தமிழ்', htmlLang: 'ta-IN' },
  { code: 'te', label: 'Telugu', nativeLabel: 'తెలుగు', htmlLang: 'te-IN' },
  { code: 'es', label: 'Spanish', nativeLabel: 'Español', htmlLang: 'es-ES' },
] as const;

export type Locale = (typeof LOCALE_DEFINITIONS)[number]['code'];

export type LocaleDetails = Omit<(typeof LOCALE_DEFINITIONS)[number], 'code'>;

export const SUPPORTED_LOCALES = LOCALE_DEFINITIONS.map(({ code }) => code) as Locale[];
export const DEFAULT_LOCALE = 'en' as const satisfies Locale;

export const LOCALE_DETAILS = LOCALE_DEFINITIONS.reduce((acc, definition) => {
  acc[definition.code] = {
    label: definition.label,
    nativeLabel: definition.nativeLabel,
    htmlLang: definition.htmlLang,
  };
  return acc;
}, {} as Record<Locale, LocaleDetails>);

export const HTML_LANG = SUPPORTED_LOCALES.reduce((acc, locale) => {
  acc[locale] = LOCALE_DETAILS[locale].htmlLang;
  return acc;
}, {} as Record<Locale, string>);

export function normalizeLocale(value?: string | null): Locale {
  if (!value) return DEFAULT_LOCALE;
  const lower = value.toLowerCase();
  if (SUPPORTED_LOCALES.includes(lower as Locale)) return lower as Locale;
  return DEFAULT_LOCALE;
}

export function getLocaleDefinition(locale: Locale): LocaleDetails {
  return LOCALE_DETAILS[locale] ?? LOCALE_DETAILS[DEFAULT_LOCALE];
}

export function getIntlLocale(locale: Locale): string {
  const map: Record<Locale, string> = {
    en: 'en-IN',
    kn: 'kn-IN',
    hi: 'hi-IN',
    ta: 'ta-IN',
    te: 'te-IN',
    es: 'es-ES',
  };
  return map[locale] ?? map[DEFAULT_LOCALE];
}

import {
  DEFAULT_LOCALE,
  LOCALE_DEFINITIONS,
  LOCALE_DETAILS,
  SUPPORTED_LOCALES,
  getIntlLocale,
  getLocaleDefinition,
  normalizeLocale,
  type Locale,
} from '@/lib/i18n/locales';
import { defaultMessages, type MessageDictionary } from './catalog/default-messages';
import { localeMessageOverrides } from './catalog/locale-overrides';
import { SPANISH_INLINE_FALLBACKS } from './catalog/spanish-inline-fallbacks';
import type { LocalizedValue } from './catalog/types';
import { mergeDeep, resolvePath } from './catalog/utils';

export const messages = SUPPORTED_LOCALES.reduce((catalog, locale) => {
  catalog[locale] = locale === DEFAULT_LOCALE
    ? defaultMessages
    : mergeDeep(defaultMessages, localeMessageOverrides[locale]) as MessageDictionary;
  return catalog;
}, {} as Record<Locale, MessageDictionary>);

export function pickLocalizedValue<T>(locale: Locale, values: LocalizedValue<T>): T {
  const resolved = (values[locale] ?? values[DEFAULT_LOCALE]) as T;

  if (locale === 'es' && values.es === undefined && typeof resolved === 'string') {
    return (SPANISH_INLINE_FALLBACKS[resolved] ?? resolved) as T;
  }

  return resolved;
}

export function translate(locale: Locale, key: string): string {
  return resolvePath(messages[locale], key)
    ?? resolvePath(messages[DEFAULT_LOCALE], key)
    ?? key;
}

