const DAY_MS = 86_400_000;

function ageDays(isoDate: string): number {
  const timestamp = new Date(isoDate).getTime();
  return Number.isNaN(timestamp) ? Number.MAX_SAFE_INTEGER : Math.max(0, Math.floor((Date.now() - timestamp) / DAY_MS));
}

function evidenceRecord(evidence: DurableRailEvidence, targetDays: number) {
  return {
    isoDate: evidence.qualifiedAt.slice(0, 10), ageDays: ageDays(evidence.qualifiedAt), targetDays,
    evidenceType: "durable-automated" as const, policyVersion: evidence.policyVersion,
    commitSha: evidence.commitSha, evidenceUrl: evidence.providerRunUrl,
  };
}

/**
 * Resolves the public freshness signal from durable operational evidence.
 * The checked-in content date remains a safe fallback when storage is empty or
 * unavailable, while a newer successful SEO run advances content freshness.
 */
export async function getCurrentSiteFreshnessStatus(): Promise<SiteFreshnessStatus> {
  let baseline: SiteFreshnessStatus;
  try {
    const latestRun = await getLatestSeoAgencyRun();
    baseline = getSiteFreshnessStatus(latestRun?.generatedAt);
  } catch {
    baseline = getSiteFreshnessStatus();
  }

  let evidence: Partial<Record<FreshnessRail, DurableRailEvidence>> | null = null;
  try { evidence = await getLatestDurableRailEvidence(); } catch { evidence = null; }
  const content = evidence?.content ? evidenceRecord(evidence.content, FRESHNESS_TARGET_DAYS.content) : { ...baseline.content, targetDays: FRESHNESS_TARGET_DAYS.content, evidenceType: "documentation-fallback" as const };
  const factualAudit = evidence?.factual_audit ? evidenceRecord(evidence.factual_audit, FRESHNESS_TARGET_DAYS.factualAudit) : { ...baseline.factualAudit, targetDays: FRESHNESS_TARGET_DAYS.factualAudit, evidenceType: "documentation-fallback" as const };
  const executionStatus = evidence?.execution_status ? evidenceRecord(evidence.execution_status, FRESHNESS_TARGET_DAYS.executionStatus) : { ...baseline.executionStatus, targetDays: FRESHNESS_TARGET_DAYS.executionStatus, evidenceType: "documentation-fallback" as const };
  const count = [evidence?.content, evidence?.factual_audit, evidence?.execution_status].filter(Boolean).length;
  const telemetryAvailable = count === 3;
  return {
    degraded: !telemetryAvailable || content.ageDays > FRESHNESS_TARGET_DAYS.content || factualAudit.ageDays > FRESHNESS_TARGET_DAYS.factualAudit || executionStatus.ageDays > FRESHNESS_TARGET_DAYS.executionStatus,
    telemetryAvailable,
    telemetryMode: count === 3 ? "durable" : count > 0 ? "hybrid" : "documentation-fallback",
    content, factualAudit, executionStatus,
  };
}

export const FRESHNESS_TARGET_DAYS = {
  content: 3,
  factualAudit: 14,
  executionStatus: 14,
} as const;

type FreshnessAges = {
  contentAgeDays: number;
  factualAuditAgeDays: number;
  executionStatusAgeDays: number;
};

function railSlaScore(ageDays: number, targetDays: number): number {
  const safeAge = Math.max(0, ageDays);
  if (safeAge <= targetDays) return 100;
  return Math.max(0, Math.round((targetDays / safeAge) * 100));
}

/**
 * Measures compliance with the published freshness windows. All rails must be
 * within target for 100; the worst overdue rail determines the score so one
 * stale control cannot be hidden by averaging it with healthy controls.
 */
export function calculateFreshnessSlaScore(ages: FreshnessAges): number {
  return Math.min(
    railSlaScore(ages.contentAgeDays, FRESHNESS_TARGET_DAYS.content),
    railSlaScore(ages.factualAuditAgeDays, FRESHNESS_TARGET_DAYS.factualAudit),
    railSlaScore(ages.executionStatusAgeDays, FRESHNESS_TARGET_DAYS.executionStatus),
  );
}

import { readFileSync } from "node:fs";
import { SITE_CONFIG } from "@/config/site.config";
import { FRESHNESS_TARGET_DAYS } from "./freshness-score";

const DAY_MS = 86_400_000;
const CONTENT_WARN_DAYS = FRESHNESS_TARGET_DAYS.content;
const AUDIT_WARN_DAYS = FRESHNESS_TARGET_DAYS.factualAudit;
const EXECUTION_WARN_DAYS = FRESHNESS_TARGET_DAYS.executionStatus;
// These values mirror the checked-in operational records below. Vercel server
// functions do not reliably ship repository documentation files, so they keep
// the freshness signal available when those files are absent at runtime.
const FACTUAL_AUDIT_FALLBACK_DATE = "2026-08-09";
const EXECUTION_STATUS_FALLBACK_DATE = "2026-08-08";

type FreshnessRecord = {
  isoDate: string;
  ageDays: number;
  targetDays?: number;
  evidenceType?: "durable-automated" | "documentation-fallback";
  policyVersion?: string;
  commitSha?: string | null;
  evidenceUrl?: string | null;
};

export type SiteFreshnessStatus = {
  degraded: boolean;
  telemetryAvailable?: boolean;
  telemetryMode?: "durable" | "hybrid" | "documentation-fallback";
  content: FreshnessRecord;
  factualAudit: FreshnessRecord;
  executionStatus: FreshnessRecord;
};

function parseDate(isoDate: string, source: string) {
  const timestamp = new Date(`${isoDate}T00:00:00Z`).getTime();
  if (Number.isNaN(timestamp)) {
    throw new Error(`Invalid YYYY-MM-DD date for ${source}: ${isoDate}`);
  }
  return timestamp;
}

function getAgeDays(timestamp: number) {
  return Math.max(0, Math.floor((Date.now() - timestamp) / DAY_MS));
}

function toFreshnessRecord(isoDate: string, source: string): FreshnessRecord {
  return {
    isoDate,
    ageDays: getAgeDays(parseDate(isoDate, source)),
  };
}

function readDatedField(
  path: string,
  matcher: RegExp,
  fallbackDate: string,
): FreshnessRecord {
  try {
    const content = readFileSync(path, "utf8");
    const match = content.match(matcher);
    if (!match) {
      throw new Error(`${path} must declare a YYYY-MM-DD date.`);
    }

    return toFreshnessRecord(match[1], path);
  } catch (error) {
    // Freshness telemetry must never turn a missing, untraced documentation
    // file in a serverless runtime into a site-wide rendering failure.
    console.warn(
      `Using embedded freshness baseline for ${path}: ${error instanceof Error ? error.message : String(error)}`,
    );
    return toFreshnessRecord(fallbackDate, `${path} fallback`);
  }
}

function newestContentDate(operationalRefreshAt?: string | null): string {
  if (!operationalRefreshAt) return SITE_CONFIG.lastUpdatedISO;
  const timestamp = new Date(operationalRefreshAt).getTime();
  if (Number.isNaN(timestamp)) return SITE_CONFIG.lastUpdatedISO;
  const operationalDate = new Date(timestamp).toISOString().slice(0, 10);
  return operationalDate > SITE_CONFIG.lastUpdatedISO
    ? operationalDate
    : SITE_CONFIG.lastUpdatedISO;
}

export function getSiteFreshnessStatus(
  operationalRefreshAt?: string | null,
): SiteFreshnessStatus {
  const contentDate = newestContentDate(operationalRefreshAt);
  const content = {
    isoDate: contentDate,
    ageDays: getAgeDays(parseDate(contentDate, "content freshness")),
  };
  const factualAudit = readDatedField(
    "docs/FACTUAL_CLAIM_AUDIT.md",
    /^Date:\s*(\d{4}-\d{2}-\d{2})$/m,
    FACTUAL_AUDIT_FALLBACK_DATE,
  );
  const executionStatus = readDatedField(
    "docs/KWIN_VALUE_ADD_EXECUTION_STATUS.md",
    /^-\s*Date:\s*(\d{4}-\d{2}-\d{2})$/m,
    EXECUTION_STATUS_FALLBACK_DATE,
  );

  const degraded =
    content.ageDays > CONTENT_WARN_DAYS ||
    factualAudit.ageDays > AUDIT_WARN_DAYS ||
    executionStatus.ageDays > EXECUTION_WARN_DAYS;

  return {
    degraded,
    telemetryAvailable: false,
    telemetryMode: "documentation-fallback",
    content,
    factualAudit,
    executionStatus,
  };
}

export const VERIFICATION_SUITES = ['content_refresh', 'factual_audit', 'execution_status'] as const;
export const VERIFICATION_OUTCOMES = ['passed', 'failed', 'partial', 'skipped', 'timed_out', 'indeterminate', 'cancelled'] as const;
export const FRESHNESS_RAILS = ['content', 'factual_audit', 'execution_status'] as const;

export type VerificationSuite = (typeof VERIFICATION_SUITES)[number];
export type VerificationOutcome = (typeof VERIFICATION_OUTCOMES)[number];
export type FreshnessRail = (typeof FRESHNESS_RAILS)[number];
export type VerificationProvider = 'github_actions' | 'vercel_cron' | 'manual' | 'local';
export type VerificationEnvironment = 'production' | 'preview' | 'ci' | 'development';

export type VerificationControl = {
  id: string;
  required: boolean;
  outcome: Exclude<VerificationOutcome, 'partial'>;
  summary?: string;
  durationMs?: number;
  metrics?: Record<string, string | number | boolean | null>;
};

export type VerificationSubmission = {
  idempotencyKey: string;
  suite: VerificationSuite;
  outcome: VerificationOutcome;
  policyVersion: string;
  startedAt: string;
  completedAt: string;
  commitSha?: string;
  environment: VerificationEnvironment;
  provider: VerificationProvider;
  providerRunId?: string;
  providerRunUrl?: string;
  trigger: 'schedule' | 'workflow_dispatch' | 'deployment' | 'retry' | 'manual' | 'request';
  controls: VerificationControl[];
  manifest?: Record<string, unknown>;
  failureCode?: string;
  failureSummary?: string;
};

export type VerificationReceipt = {
  attemptId: string;
  outcome: VerificationOutcome;
  qualified: boolean;
  rail: FreshnessRail;
  idempotent: boolean;
};

export type DurableRailEvidence = {
  rail: FreshnessRail;
  qualifiedAt: string;
  expiresAt: string;
  policyVersion: string;
  commitSha: string | null;
  provider: VerificationProvider;
  providerRunUrl: string | null;
};

import { createHash } from 'node:crypto';

export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`)
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

export function sha256Fingerprint(value: unknown): string {
  return createHash('sha256').update(canonicalJson(value)).digest('hex');
}

import { FRESHNESS_TARGET_DAYS } from './freshness-score';
import type { FreshnessRail, VerificationSubmission, VerificationSuite } from './verification-contracts';

type VerificationPolicy = {
  version: string;
  suite: VerificationSuite;
  rail: FreshnessRail;
  targetDays: number;
  requiredControls: readonly string[];
};

export const VERIFICATION_POLICIES: Record<VerificationSuite, VerificationPolicy> = {
  content_refresh: {
    version: 'content-refresh/v1', suite: 'content_refresh', rail: 'content',
    targetDays: FRESHNESS_TARGET_DAYS.content,
    requiredControls: ['authorization', 'source-health', 'live-inputs', 'content-validation', 'supabase-persistence', 'post-write-read'],
  },
  factual_audit: {
    version: 'factual-audit/v1', suite: 'factual_audit', rail: 'factual_audit',
    targetDays: FRESHNESS_TARGET_DAYS.factualAudit,
    requiredControls: ['operations-current', 'primary-source-health', 'source-registry', 'content-staleness', 'factual-integrity', 'discovery-signals'],
  },
  execution_status: {
    version: 'execution-status/v1', suite: 'execution_status', rail: 'execution_status',
    targetDays: FRESHNESS_TARGET_DAYS.executionStatus,
    requiredControls: ['node-runtime', 'type-check', 'unit-tests', 'migration-verification', 'vercel-config', 'pwa-verification', 'production-build'],
  },
};

export function evaluateVerification(submission: VerificationSubmission): { qualified: boolean; rail: FreshnessRail; reasons: string[] } {
  const policy = VERIFICATION_POLICIES[submission.suite];
  const reasons: string[] = [];
  if (submission.policyVersion !== policy.version) reasons.push('policy-version-mismatch');
  if (submission.outcome !== 'passed') reasons.push(`outcome-${submission.outcome}`);
  if (submission.suite === 'content_refresh' && submission.environment !== 'production') reasons.push('content-not-production');
  if (submission.suite === 'content_refresh' && !['github_actions', 'vercel_cron'].includes(submission.provider)) reasons.push('content-provider-not-trusted');
  if (submission.suite !== 'content_refresh' && submission.environment !== 'ci') reasons.push('audit-not-ci');
  if (submission.suite !== 'content_refresh' && submission.provider !== 'github_actions') reasons.push('audit-provider-not-trusted');
  const controls = new Map<string, VerificationSubmission['controls'][number]>();
  for (const control of submission.controls) {
    if (controls.has(control.id)) reasons.push(`duplicate-control:${control.id}`);
    else controls.set(control.id, control);
  }
  for (const required of policy.requiredControls) {
    const control = controls.get(required);
    if (!control?.required) reasons.push(`required-control-not-declared-required:${required}`);
    if (control?.outcome !== 'passed') reasons.push(`required-control-not-passed:${required}`);
  }
  if (submission.controls.some((control) => control.required && control.outcome !== 'passed')) reasons.push('required-control-failed');
  return { qualified: reasons.length === 0, rail: policy.rail, reasons };
}

export function qualificationExpiry(rail: FreshnessRail, qualifiedAt: string): string {
  const policy = Object.values(VERIFICATION_POLICIES).find((candidate) => candidate.rail === rail);
  const timestamp = new Date(qualifiedAt).getTime();
  return new Date(timestamp + (policy?.targetDays ?? 0) * 86_400_000).toISOString();
}

import type { VerificationSubmission } from './verification-contracts';
import { sha256Fingerprint } from './verification-fingerprint';
import { evaluateVerification, qualificationExpiry } from './verification-policy';

export function buildVerificationRecord(submission: VerificationSubmission) {
  const evaluation = evaluateVerification(submission);
  const manifest = { ...(submission.manifest ?? {}), qualificationReasons: evaluation.reasons };
  return {
    evaluation,
    manifest,
    manifestSha256: sha256Fingerprint(manifest),
    requestSha256: sha256Fingerprint(submission),
    expiresAt: qualificationExpiry(evaluation.rail, submission.completedAt),
  };
}

import { getSupabaseAdmin } from '@/lib/server/supabase-client';
import type { DurableRailEvidence, FreshnessRail, VerificationSubmission } from './verification-contracts';
import { VERIFICATION_POLICIES } from './verification-policy';
import { buildVerificationRecord } from './verification-record';

export async function recordVerification(submission: VerificationSubmission) {
  const supabase = getSupabaseAdmin();
  if (!supabase) throw new Error('operational-evidence-storage-unavailable');
  const record = buildVerificationRecord(submission);
  const transaction = await supabase.rpc('record_operational_verification', {
    p_idempotency_key: submission.idempotencyKey, p_request_sha256: record.requestSha256,
    p_suite: submission.suite, p_outcome: submission.outcome, p_qualified: record.evaluation.qualified,
    p_policy_version: submission.policyVersion, p_started_at: submission.startedAt, p_completed_at: submission.completedAt,
    p_commit_sha: submission.commitSha ?? null, p_environment: submission.environment, p_provider: submission.provider,
    p_provider_run_id: submission.providerRunId ?? null, p_provider_run_url: submission.providerRunUrl ?? null,
    p_trigger_name: submission.trigger, p_controls: submission.controls, p_manifest: record.manifest,
    p_manifest_sha256: record.manifestSha256, p_failure_code: submission.failureCode ?? null,
    p_failure_summary: submission.failureSummary ?? null, p_rail: record.evaluation.rail,
    p_expires_at: record.expiresAt,
  });
  if (transaction.error || !transaction.data?.[0]) {
    const message = transaction.error?.message ?? 'unknown';
    if (message.includes('idempotency-key-payload-conflict')) throw new Error('idempotency-key-payload-conflict');
    throw new Error(`operational-evidence-transaction-failed:${message}`);
  }
  const receipt = transaction.data[0];
  const attempt = await supabase.from('operational_verification_attempts').select('*').eq('id', receipt.attempt_id).single();
  if (attempt.error || !attempt.data) throw new Error(`operational-evidence-read-after-write-failed:${attempt.error?.message ?? 'unknown'}`);
  return { attempt: attempt.data, idempotent: !receipt.inserted };
}

export async function getLatestDurableRailEvidence(): Promise<Partial<Record<FreshnessRail, DurableRailEvidence>> | null> {
  const supabase = getSupabaseAdmin();
  if (!supabase) return null;
  const result = await supabase.from('operational_freshness_qualifications').select('*').order('qualified_at', { ascending: false }).limit(100);
  if (result.error || !result.data) return null;
  const attemptIds = [...new Set(result.data.map((qualification) => qualification.attempt_id))];
  const attemptsResult = attemptIds.length
    ? await supabase.from('operational_verification_attempts').select('*').in('id', attemptIds)
    : { data: [], error: null };
  if (attemptsResult.error || !attemptsResult.data) return null;
  const attempts = new Map(attemptsResult.data.map((attempt) => [attempt.id, attempt]));
  const output: Partial<Record<FreshnessRail, DurableRailEvidence>> = {};
  for (const qualification of result.data) {
    const rail = qualification.rail as FreshnessRail;
    if (output[rail]) continue;
    const currentPolicy = Object.values(VERIFICATION_POLICIES).find((policy) => policy.rail === rail);
    if (!currentPolicy || qualification.policy_version !== currentPolicy.version) continue;
    const attempt = attempts.get(qualification.attempt_id);
    if (!attempt || !attempt.qualified) continue;
    output[rail] = {
      rail, qualifiedAt: qualification.qualified_at, expiresAt: qualification.expires_at,
      policyVersion: qualification.policy_version, commitSha: qualification.commit_sha,
      provider: attempt.provider as DurableRailEvidence['provider'], providerRunUrl: attempt.provider_run_url,
    };
  }
  return output;
}

export async function beginSchedulerHeartbeat(input: { idempotencyKey: string; provider: 'github_actions' | 'vercel_cron' | 'manual' | 'local'; scheduleId: string; invocationId: string }) {
  const supabase = getSupabaseAdmin();
  if (!supabase) return false;
  const result = await supabase.from('operational_scheduler_heartbeats').upsert({
    idempotency_key: input.idempotencyKey, provider: input.provider, schedule_id: input.scheduleId,
    invocation_id: input.invocationId, outcome: 'received', duration_ms: null, failure_code: null, completed_at: null,
  }, { onConflict: 'idempotency_key', ignoreDuplicates: true });
  return !result.error;
}

export async function completeSchedulerHeartbeat(idempotencyKey: string, input: { outcome: 'passed' | 'failed' | 'partial' | 'timed_out' | 'indeterminate'; durationMs: number; failureCode?: string }) {
  const supabase = getSupabaseAdmin();
  if (!supabase) return false;
  const result = await supabase.from('operational_scheduler_heartbeats').update({
    outcome: input.outcome, duration_ms: input.durationMs, failure_code: input.failureCode ?? null, completed_at: new Date().toISOString(),
  }).eq('idempotency_key', idempotencyKey);
  return !result.error;
}

import { VERIFICATION_OUTCOMES, VERIFICATION_SUITES, type VerificationSubmission } from './verification-contracts';

const SHA = /^[0-9a-f]{40}$/;
const ID = /^[a-z0-9][a-z0-9._:/-]{1,119}$/i;
const MAX_ATTEMPT_DURATION_MS = 24 * 60 * 60_000;

function isObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function optionalHttpsUrl(value: unknown): string | undefined {
  if (value == null) return undefined;
  if (typeof value !== 'string' || value.length > 2_048) throw new Error('invalid-provider-url');
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' || url.username || url.password) throw new Error();
    return url.toString();
  } catch { throw new Error('invalid-provider-url'); }
}

function scalarMetrics(value: unknown): VerificationSubmission['controls'][number]['metrics'] | undefined {
  if (value == null) return undefined;
  if (!isObject(value) || Object.keys(value).length > 50) throw new Error('invalid-control-metrics');
  const output: NonNullable<VerificationSubmission['controls'][number]['metrics']> = {};
  for (const [key, metric] of Object.entries(value)) {
    if (!ID.test(key) || !['string', 'number', 'boolean'].includes(typeof metric) && metric !== null) throw new Error('invalid-control-metrics');
    if (typeof metric === 'number' && !Number.isFinite(metric)) throw new Error('invalid-control-metrics');
    output[key] = typeof metric === 'string' ? metric.slice(0, 500) : metric as number | boolean | null;
  }
  return output;
}

export function parseVerificationSubmission(value: unknown): VerificationSubmission {
  if (!isObject(value)) throw new Error('invalid-body');
  if (!VERIFICATION_SUITES.includes(value.suite as never)) throw new Error('invalid-suite');
  if (!VERIFICATION_OUTCOMES.includes(value.outcome as never)) throw new Error('invalid-outcome');
  if (typeof value.idempotencyKey !== 'string' || !ID.test(value.idempotencyKey)) throw new Error('invalid-idempotency-key');
  if (typeof value.policyVersion !== 'string' || !ID.test(value.policyVersion)) throw new Error('invalid-policy-version');
  const startedAt = new Date(String(value.startedAt));
  const completedAt = new Date(String(value.completedAt));
  if (Number.isNaN(startedAt.getTime()) || Number.isNaN(completedAt.getTime()) || completedAt < startedAt) throw new Error('invalid-timestamps');
  if (startedAt.getTime() > Date.now() + 10 * 60_000) throw new Error('future-timestamp');
  if (completedAt.getTime() > Date.now() + 10 * 60_000) throw new Error('future-timestamp');
  if (completedAt.getTime() - startedAt.getTime() > MAX_ATTEMPT_DURATION_MS) throw new Error('attempt-duration-too-long');
  if (value.commitSha != null && (typeof value.commitSha !== 'string' || !SHA.test(value.commitSha))) throw new Error('invalid-commit-sha');
  const providerRunUrl = optionalHttpsUrl(value.providerRunUrl);
  if (!['production', 'preview', 'ci', 'development'].includes(String(value.environment))) throw new Error('invalid-environment');
  if (!['github_actions', 'vercel_cron', 'manual', 'local'].includes(String(value.provider))) throw new Error('invalid-provider');
  if (!['schedule', 'workflow_dispatch', 'deployment', 'retry', 'manual', 'request'].includes(String(value.trigger))) throw new Error('invalid-trigger');
  if (!Array.isArray(value.controls) || value.controls.length === 0 || value.controls.length > 100) throw new Error('invalid-controls');
  const controlIds = new Set<string>();
  const controls = value.controls.map((control) => {
    if (!isObject(control) || typeof control.id !== 'string' || !ID.test(control.id)) throw new Error('invalid-control');
    if (controlIds.has(control.id)) throw new Error('duplicate-control');
    controlIds.add(control.id);
    if (typeof control.required !== 'boolean' || !VERIFICATION_OUTCOMES.includes(control.outcome as never) || control.outcome === 'partial') throw new Error('invalid-control-outcome');
    return {
      id: control.id, required: control.required, outcome: control.outcome as VerificationSubmission['controls'][number]['outcome'],
      summary: typeof control.summary === 'string' ? control.summary.slice(0, 500) : undefined,
      durationMs: typeof control.durationMs === 'number' && control.durationMs >= 0 ? Math.round(control.durationMs) : undefined,
      metrics: scalarMetrics(control.metrics),
    };
  });
  return {
    idempotencyKey: value.idempotencyKey,
    suite: value.suite as VerificationSubmission['suite'], outcome: value.outcome as VerificationSubmission['outcome'],
    policyVersion: value.policyVersion, startedAt: startedAt.toISOString(), completedAt: completedAt.toISOString(),
    commitSha: value.commitSha as string | undefined,
    environment: value.environment as VerificationSubmission['environment'],
    provider: value.provider as VerificationSubmission['provider'],
    providerRunId: typeof value.providerRunId === 'string' ? value.providerRunId.slice(0, 200) : undefined,
    providerRunUrl,
    trigger: value.trigger as VerificationSubmission['trigger'],
    controls, manifest: isObject(value.manifest) ? value.manifest : {},
    failureCode: typeof value.failureCode === 'string' ? value.failureCode.slice(0, 120) : undefined,
    failureSummary: typeof value.failureSummary === 'string' ? value.failureSummary.slice(0, 1000) : undefined,
  };
}

import { createHmac, timingSafeEqual } from 'node:crypto';

export const EVIDENCE_TIMESTAMP_HEADER = 'x-kwin-evidence-timestamp';
export const EVIDENCE_NONCE_HEADER = 'x-kwin-evidence-nonce';
export const EVIDENCE_SIGNATURE_HEADER = 'x-kwin-evidence-signature';
const MAX_CLOCK_SKEW_MS = 5 * 60_000;

export function signEvidencePayload(secret: string, timestamp: string, nonce: string, body: string): string {
  return createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
}

export function verifyEvidenceSignature(args: { secret: string; timestamp: string | null; nonce: string | null; signature: string | null; body: string; now?: number }): boolean {
  if (!args.timestamp || !/^\d{13}$/.test(args.timestamp) || !args.nonce || !args.signature || !/^[a-f0-9]{64}$/i.test(args.signature) || !/^[a-zA-Z0-9_-]{16,120}$/.test(args.nonce)) return false;
  const timestamp = Number(args.timestamp);
  if (!Number.isFinite(timestamp) || Math.abs((args.now ?? Date.now()) - timestamp) > MAX_CLOCK_SKEW_MS) return false;
  const expected = Buffer.from(signEvidencePayload(args.secret, args.timestamp, args.nonce, args.body));
  const received = Buffer.from(args.signature);
  return expected.length === received.length && timingSafeEqual(expected, received);
}

import { describe, expect, it } from 'vitest';
import { shouldOfferInstall, type InstallPromptState } from '../install-policy';

const EMPTY: InstallPromptState = { installedAt: null, dismissedUntil: null, optedOut: false, lastShownAt: null, visitCount: 1 };
const NOW = Date.parse('2026-08-15T12:00:00Z');

function offer(state: InstallPromptState, overrides: Partial<Parameters<typeof shouldOfferInstall>[0]> = {}) {
  return shouldOfferInstall({
    state, now: NOW, isStandalone: false, isIos: false, hasNativePrompt: true,
    minimumIosVisits: 3, repeatOfferDays: 90, ...overrides,
  });
}

describe('PWA install prompt policy', () => {
  it('never prompts standalone, remembered-installed, or opted-out users', () => {
    expect(offer(EMPTY, { isStandalone: true })).toBe(false);
    expect(offer({ ...EMPTY, installedAt: NOW - 1 })).toBe(false);
    expect(offer({ ...EMPTY, optedOut: true })).toBe(false);
  });

  it('honors both dismissal and repeat-offer cooldowns', () => {
    expect(offer({ ...EMPTY, dismissedUntil: NOW + 1 })).toBe(false);
    expect(offer({ ...EMPTY, lastShownAt: NOW - 30 * 86_400_000 })).toBe(false);
    expect(offer({ ...EMPTY, lastShownAt: NOW - 91 * 86_400_000 })).toBe(true);
  });

  it('requires engagement before showing manual iOS instructions', () => {
    expect(offer({ ...EMPTY, visitCount: 2 }, { isIos: true, hasNativePrompt: false })).toBe(false);
    expect(offer({ ...EMPTY, visitCount: 3 }, { isIos: true, hasNativePrompt: false })).toBe(true);
  });

  it('does not invent manual-install eligibility for unsupported browsers', () => {
    expect(offer(EMPTY, { isIos: false, hasNativePrompt: false })).toBe(false);
  });
});

