function buildHealthChecks(signals: KwinNewsSignal[], publishAttempts: PublishAttempt[]) {
  const topScore = signals[0]?.relevanceScore ?? 0;
  const hasSignals = signals.length > 0;
  const facebookAttempt = publishAttempts.find((attempt) => attempt.platform === 'facebook');

  return [
    {
      label: 'KWIN relevance',
      status: topScore >= 55 ? ('pass' as const) : ('warn' as const),
      detail:
        topScore >= 55
          ? `Top signal scored ${topScore}.`
          : hasSignals
            ? `Top signal scored ${topScore}; treat it as contextual intelligence, not a project-specific milestone.`
            : 'No high-scoring live signal; used evergreen portal content.',
    },
    {
      label: 'Evidence safety',
      status: 'pass' as const,
      detail: 'The generated queue keeps all project-sensitive claims behind evidence labels.',
    },
    {
      label: 'Direct publishing',
      status: facebookAttempt?.status === 'published' ? ('pass' as const) : ('warn' as const),
      detail: facebookAttempt?.note ?? 'Direct publishing is disabled until platform credentials and approval rules are configured.',
    },
  ];
}

export function createKwinSeoAgencyRun(options: {
  now?: Date;
  newsSignals?: KwinNewsSignal[];
  publishAttempts?: PublishAttempt[];
} = {}): KwinSeoAgencyRun {
  const now = options.now ?? new Date();
  const runDate = getKwinLocalDate(now);
  const generatedAt = now.toISOString();
  const topic = selectTopic(now);
  const signals = pickSignals(options.newsSignals ?? []);
  const dailyBrief = buildDailyBrief(topic, signals, runDate);
  const dailyArticle = buildDailyArticle(topic, dailyBrief, signals, runDate, generatedAt);
  const socialQueue = buildSocialQueue(topic, dailyBrief, runDate);
  const snapshots = buildSnapshots(topic, signals);
  const publishAttempts = options.publishAttempts ?? [];

  return {
    id: runDate,
    runDate,
    generatedAt,
    agencyName: SEO_AGENCY_NAME,
    mission: SEO_AGENCY_MISSION,
    topic,
    dailyBrief,
    dailyArticle,
    newsSignals: signals,
    socialQueue,
    snapshots,
    publishAttempts,
    healthChecks: buildHealthChecks(signals, publishAttempts),
  };
}

import { createKwinSeoAgencyRun } from './content';
import { fetchKwinNewsSignals } from './news';
import { getPublishingReadiness, publishSeoAgencyRun } from './publisher';
import { saveSeoAgencyRun } from './store';
import type { KwinNewsSignal, KwinSeoAgencyRun } from './types';

type AgencyJobResult = {
  run: KwinSeoAgencyRun;
  storageBackend: 'supabase' | 'file';
  liveInputStatus: 'live' | 'fallback';
  warning?: string;
};

export async function runKwinSeoAgencyJob(now = new Date()): Promise<AgencyJobResult> {
  let newsSignals: KwinNewsSignal[] = [];
  let warning: string | undefined;

  try {
    newsSignals = await fetchKwinNewsSignals();
  } catch (error) {
    warning = error instanceof Error ? error.message : 'News signal fetch failed.';
  }

  const draftRun = createKwinSeoAgencyRun({ now, newsSignals });
  const publishing = await publishSeoAgencyRun(draftRun);
  const publishingReadiness = getPublishingReadiness();
  const run = {
    ...createKwinSeoAgencyRun({
      now,
      newsSignals,
      publishAttempts: publishing.attempts,
    }),
    socialQueue: publishing.socialQueue,
    publishingReadiness,
  };

  if (warning) {
    run.healthChecks = [
      {
        label: 'News fetch',
        status: 'warn',
        detail: `Live feed fetch had an issue, so the agency used the evergreen KWIN content reservoir. ${warning}`,
      },
      ...run.healthChecks,
    ];
  }

  const saveResult = await saveSeoAgencyRun(run);

  return {
    run,
    storageBackend: saveResult.backend,
    liveInputStatus: newsSignals.length > 0 && !warning ? 'live' : 'fallback',
    warning: saveResult.warning ?? warning,
  };
}

