const MAX_FEEDS = 20;
const MAX_ITEMS_PER_FEED = 8;
const REQUEST_TIMEOUT_MS = 9000;

const RELEVANCE_TERMS: Array<{ term: string; weight: number }> = [
  { term: 'kwin city', weight: 40 },
  { term: 'knowledge wellbeing innovation city', weight: 40 },
  { term: 'kwin', weight: 32 },
  { term: 'doddaballapura', weight: 24 },
  { term: 'north bengaluru', weight: 22 },
  { term: 'kiadb', weight: 22 },
  { term: 'karnataka industrial areas development board', weight: 22 },
  { term: 'bengaluru airport', weight: 14 },
  { term: 'devanahalli', weight: 14 },
  { term: 'strr', weight: 14 },
  { term: 'satellite town ring road', weight: 14 },
  { term: 'semiconductor', weight: 12 },
  { term: 'aerospace', weight: 10 },
  { term: 'health tech', weight: 10 },
  { term: 'medical technology', weight: 10 },
  { term: 'innovation district', weight: 10 },
  { term: 'industrial township', weight: 10 },
  { term: 'urban development', weight: 8 },
  { term: 'karnataka', weight: 6 },
  { term: 'bengaluru', weight: 5 },
];

function decodeEntities(input: string): string {
  return input
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .trim();
}

function stripHtml(input: string): string {
  return decodeEntities(input)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function summarize(input: string, maxLen = 320): string {
  const clean = stripHtml(input);
  if (!clean) return 'Open the original source for the full context.';
  if (clean.length <= maxLen) return clean;
  return `${clean.slice(0, maxLen).trimEnd()}...`;
}

function getTagValue(block: string, tags: string[]): string {
  for (const tag of tags) {
    const match = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
    if (match?.[1]) return decodeEntities(match[1]);
  }
  return '';
}

function getFeedTitle(feedXml: string, sourceUrl: string): string {
  const channelTitle = feedXml.match(/<channel[\s\S]*?<title[^>]*>([\s\S]*?)<\/title>/i)?.[1];
  const title = stripHtml(channelTitle ? decodeEntities(channelTitle) : getTagValue(feedXml, ['title']));
  if (title) return title;
  try {
    return new URL(sourceUrl).hostname.replace(/^www\./, '');
  } catch {
    return 'External source';
  }
}

function getAtomLink(block: string): string {
  const alternate = block.match(/<link\b[^>]*rel=["']alternate["'][^>]*href=["']([^"']+)["'][^>]*>/i);
  if (alternate?.[1]) return decodeEntities(alternate[1]);
  const generic = block.match(/<link\b[^>]*href=["']([^"']+)["'][^>]*>/i);
  return generic?.[1] ? decodeEntities(generic[1]) : '';
}

function parseDateMaybe(input: string): string | null {
  if (!input) return null;
  const date = new Date(input);
  if (Number.isNaN(date.getTime())) return null;
  return date.toISOString();
}

function parseFeed(feedXml: string, sourceUrl: string): FeedItem[] {
  const source = getFeedTitle(feedXml, sourceUrl);
  const rssItems = feedXml.match(/<item\b[\s\S]*?<\/item>/gi) ?? [];
  const atomEntries = feedXml.match(/<entry\b[\s\S]*?<\/entry>/gi) ?? [];
  const parsed: FeedItem[] = [];

  for (const item of rssItems.slice(0, MAX_ITEMS_PER_FEED)) {
    const title = stripHtml(getTagValue(item, ['title'])) || 'Untitled article';
    const url = decodeEntities(getTagValue(item, ['link']));
    const rawSummary = getTagValue(item, ['description', 'content:encoded', 'content']);
    if (!url) continue;
    parsed.push({
      title,
      url,
      source,
      summary: summarize(rawSummary || title),
      publishedAt: parseDateMaybe(getTagValue(item, ['pubDate', 'dc:date', 'published', 'updated'])),
    });
  }

  for (const entry of atomEntries.slice(0, MAX_ITEMS_PER_FEED)) {
    const title = stripHtml(getTagValue(entry, ['title'])) || 'Untitled article';
    const url = getAtomLink(entry);
    const rawSummary = getTagValue(entry, ['summary', 'content']);
    if (!url) continue;
    parsed.push({
      title,
      url,
      source,
      summary: summarize(rawSummary || title),
      publishedAt: parseDateMaybe(getTagValue(entry, ['published', 'updated'])),
    });
  }

  return parsed;
}

function extractOpmlFeedUrls(opmlXml: string): string[] {
  const matches = [...opmlXml.matchAll(/xmlUrl=["']([^"']+)["']/gi)];
  return [...new Set(matches.map((match) => decodeEntities(match[1])).filter(Boolean))].slice(0, MAX_FEEDS);
}

async function fetchTextWithTimeout(url: string): Promise<string> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(url, {
      method: 'GET',
      signal: controller.signal,
      headers: {
        'User-Agent': 'KWINSeoAgency/1.0 (+https://kwin-city.com)',
        Accept: 'application/rss+xml, application/atom+xml, text/xml, application/xml, text/plain;q=0.8, */*;q=0.5',
      },
      cache: 'no-store',
    });
    if (!response.ok) {
      throw new Error(`Fetch failed for ${url}: ${response.status}`);
    }
    return response.text();
  } finally {
    clearTimeout(timeout);
  }
}

async function loadDefaultOpml(): Promise<string> {
  const opmlPath = path.join(process.cwd(), 'public', 'feeds', 'kwin-city-news-feeds.opml');
  return fs.readFile(opmlPath, 'utf8');
}

function evidenceStatusFor(matchedTerms: string[]): EvidenceStatus {
  const normalized = matchedTerms.map((term) => term.toLowerCase());
  if (normalized.some((term) => term.includes('kiadb'))) {
    return 'contextual';
  }
  if (normalized.some((term) => term.includes('kwin'))) {
    return 'pending';
  }
  return 'contextual';
}

function recommendedAngleFor(matchedTerms: string[]): string {
  const normalized = matchedTerms.map((term) => term.toLowerCase());
  if (normalized.some((term) => term.includes('kwin'))) {
    return 'Lead with KWIN City relevance, then label what is verified, contextual, or still pending.';
  }
  if (normalized.some((term) => term.includes('doddaballapura') || term.includes('north bengaluru'))) {
    return 'Frame this as regional context for North Bengaluru rather than proof of a KWIN-specific milestone.';
  }
  if (normalized.some((term) => term.includes('semiconductor') || term.includes('aerospace'))) {
    return 'Use this as sector context and avoid implying a confirmed KWIN tenant or investment unless the source states it.';
  }
  return 'Use this as contextual intelligence and route readers to the portal evidence ledger for project-specific claims.';
}

export function scoreKwinRelevance(item: Pick<FeedItem, 'title' | 'summary' | 'source'>): {
  relevanceScore: number;
  matchedTerms: string[];
} {
  const haystack = `${item.title} ${item.summary} ${item.source}`.toLowerCase();
  let score = 0;
  const matchedTerms: string[] = [];

  for (const { term, weight } of RELEVANCE_TERMS) {
    if (haystack.includes(term)) {
      score += weight;
      matchedTerms.push(term);
    }
  }

  const sourceBoost = /google news|the hindu|deccan herald|times of india|new indian express/i.test(item.source) ? 4 : 0;
  const directKwinBoost = matchedTerms.some((term) => term.includes('kwin')) ? 18 : 0;
  const relevanceScore = Math.min(100, score + sourceBoost + directKwinBoost);

  return {
    relevanceScore,
    matchedTerms,
  };
}

export async function fetchKwinNewsSignals(): Promise<KwinNewsSignal[]> {
  const opmlXml = await loadDefaultOpml();
  const feedUrls = extractOpmlFeedUrls(opmlXml);
  const settled = await Promise.allSettled(
    feedUrls.map(async (feedUrl) => {
      const feedXml = await fetchTextWithTimeout(feedUrl);
      return parseFeed(feedXml, feedUrl);
    }),
  );

  const feedItems = settled.flatMap((result) => (result.status === 'fulfilled' ? result.value : []));
  const deduped = new Map<string, FeedItem>();
  for (const item of feedItems) {
    const key = item.url || `${item.source}:${item.title}`;
    if (!deduped.has(key)) {
      deduped.set(key, item);
    }
  }

  return [...deduped.values()]
    .map((item) => {
      const { relevanceScore, matchedTerms } = scoreKwinRelevance(item);
      return {
        title: item.title,
        url: item.url,
        source: item.source,
        summary: item.summary,
        publishedAt: item.publishedAt,
        relevanceScore,
        matchedTerms,
        evidenceStatus: evidenceStatusFor(matchedTerms),
        recommendedAngle: recommendedAngleFor(matchedTerms),
      };
    })
    .filter((signal) => signal.relevanceScore >= 12)
    .sort((a, b) => b.relevanceScore - a.relevanceScore)
    .slice(0, 12);
}

import { createHash, randomUUID } from "node:crypto";
import { getSupabaseAdmin } from "@/lib/server/supabase-client";
import type {
  KwinSeoAgencyRun,
  PublishAttempt,
  SocialPlatform,
  SocialPostDraft,
} from "./types";

type Reservation = { id: string; leaseToken: string };

function normalizeUrl(value: string): string {
  try {
    const url = new URL(value);
    url.hash = "";
    for (const key of [...url.searchParams.keys()]) {
      if (key.startsWith("utm_") || ["fbclid", "gclid"].includes(key)) {
        url.searchParams.delete(key);
      }
    }
    url.hostname = url.hostname.toLowerCase();
    return url.toString().replace(/\/$/, "");
  } catch {
    return value.trim().toLowerCase();
  }
}

/** External stories are permanent; evergreen topics get one slot per month. */
export function publicationSubject(run: KwinSeoAgencyRun): string {
  const source = run.newsSignals[0]?.url;
  if (source) {
    try {
      const sourceHost = new URL(source).hostname.replace(/^www\./, "");
      const siteHost = new URL(run.dailyArticle.canonicalUrl).hostname.replace(
        /^www\./,
        "",
      );
      // Keep the external subject compatible with the original v1 ledger.
      if (sourceHost !== siteHost) return normalizeUrl(source);
    } catch {
      return normalizeUrl(source);
    }
  }
  const month = /^\d{4}-\d{2}/.exec(run.runDate)?.[0] ?? "unknown-month";
  return `evergreen:${run.topic.id}:${month}`;
}

export function publicationFingerprint(
  platform: SocialPlatform,
  run: KwinSeoAgencyRun,
): string {
  return createHash("sha256")
    .update(`v1|${platform}|${publicationSubject(run)}`)
    .digest("hex");
}

async function reserve(
  draft: SocialPostDraft,
  run: KwinSeoAgencyRun,
): Promise<Reservation | null> {
  const supabase = getSupabaseAdmin();
  if (!supabase) throw new Error("Supabase admin client is not configured");
  const leaseToken = randomUUID();
  const sourceUrl = publicationSubject(run);
  const { data, error } = await supabase.rpc(
    "acquire_social_publish_reservation",
    {
      p_platform: draft.platform,
      p_fingerprint: publicationFingerprint(draft.platform, run),
      p_source_url: sourceUrl,
      p_run_id: run.id,
      p_lease_token: leaseToken,
    },
  );
  if (error) {
    throw new Error(
      `Could not reserve ${draft.platform} publication: ${error.message}`,
    );
  }
  const result = data?.[0];
  return result?.acquired && result.reservation_id
    ? { id: result.reservation_id, leaseToken }
    : null;
}

async function complete(
  reservation: Reservation,
  attempt: PublishAttempt,
): Promise<void> {
  const supabase = getSupabaseAdmin();
  if (!supabase) throw new Error("Supabase admin client became unavailable");
  const status = attempt.status === "skipped" ? "failed" : attempt.status;
  const { error } = await supabase
    .from("social_publish_reservations")
    .update({
      status,
      platform_post_id: attempt.platformPostId ?? null,
      failure_reason: status === "published" ? null : attempt.note,
      published_at: status === "published" ? new Date().toISOString() : null,
    })
    .eq("id", reservation.id)
    .eq("lease_token", reservation.leaseToken);
  if (error) {
    throw new Error(
      `Could not record ${attempt.platform} publication: ${error.message}`,
    );
  }
}

export async function publishOnce(
  draft: SocialPostDraft,
  run: KwinSeoAgencyRun,
  publish: (draft: SocialPostDraft) => Promise<PublishAttempt>,
): Promise<PublishAttempt> {
  let reservation: Reservation | null;
  try {
    reservation = await reserve(draft, run);
  } catch (error) {
    return {
      platform: draft.platform,
      status: "skipped",
      note: `Skipped safely: idempotency storage is unavailable (${error instanceof Error ? error.message : "unknown error"}).`,
    };
  }
  if (!reservation) {
    return {
      platform: draft.platform,
      status: "skipped",
      note: "Skipped: this platform already handled the same publication subject.",
    };
  }

  let attempt: PublishAttempt;
  try {
    attempt = await publish(draft);
  } catch (error) {
    attempt = {
      platform: draft.platform,
      status: "indeterminate",
      note: `Provider outcome is unknown: ${error instanceof Error ? error.message : "unexpected publisher error"}`,
    };
  }
  try {
    await complete(reservation, attempt);
  } catch (error) {
    return {
      ...attempt,
      note: `${attempt.note} Audit update failed (${error instanceof Error ? error.message : "unknown error"}); the reservation remains held to prevent an automatic duplicate.`,
    };
  }
  return attempt;
}

import { SOCIAL_PLATFORM_CONFIGS, SOCIAL_PLATFORM_ORDER } from "./config";
import { publishOnce } from "./publish-deduplication";
import type {
  AgencyReadinessCheck,
  KwinSeoAgencyRun,
  PublishAttempt,
  SocialPlatform,
  SocialPostDraft,
} from "./types";

type PublishingResult = {
  attempts: PublishAttempt[];
  socialQueue: SocialPostDraft[];
};

type GraphResponse = {
  id?: string;
  post_id?: string;
  error?: {
    message?: string;
  };
};

type XPostResponse = {
  data?: {
    id?: string;
  };
  errors?: Array<{
    detail?: string;
    title?: string;
  }>;
};

const GRAPH_API_VERSION = process.env.META_GRAPH_API_VERSION || "v25.0";
const GRAPH_API_BASE = `https://graph.facebook.com/${GRAPH_API_VERSION}`;
const REQUEST_TIMEOUT_MS =
  Number(process.env.SOCIAL_REQUEST_TIMEOUT_MS) || 25_000;

class ProviderError extends Error {
  constructor(
    message: string,
    readonly outcome: "rejected" | "indeterminate",
  ) {
    super(message);
    this.name = "ProviderError";
  }
}

async function providerFetch(
  input: string,
  init: RequestInit,
): Promise<Response> {
  try {
    return await fetch(input, {
      ...init,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
  } catch (error) {
    throw new ProviderError(
      `Request outcome is unknown (${error instanceof Error ? error.message : "network failure"}).`,
      "indeterminate",
    );
  }
}

function providerFailure(
  platform: SocialPlatform,
  error: unknown,
): PublishAttempt {
  return {
    platform,
    status:
      error instanceof ProviderError && error.outcome === "indeterminate"
        ? "indeterminate"
        : "failed",
    note:
      error instanceof Error ? error.message : `${platform} publish failed.`,
  };
}

function publishingEnabled(): boolean {
  return process.env.SOCIAL_PUBLISHING_ENABLED === "true";
}

function autoApproveEnabled(): boolean {
  return process.env.SOCIAL_AUTO_APPROVE === "true";
}

function missingEnv(keys: string[]): string[] {
  return keys.filter((key) => !process.env[key]);
}

export function getPublishingReadiness(): AgencyReadinessCheck[] {
  const enabled = publishingEnabled();
  const approvedByRule = autoApproveEnabled();

  return SOCIAL_PLATFORM_ORDER.map((platform) => {
    const config = SOCIAL_PLATFORM_CONFIGS[platform];
    const missing = missingEnv(config.requiredEnv);

    if (!config.directPublish) {
      return {
        id: platform,
        label: config.label,
        status: "manual",
        detail: config.publishNote,
        optionalEnv: config.optionalEnv,
      };
    }

    if (!enabled) {
      return {
        id: platform,
        label: config.label,
        status: "disabled",
        detail: "Direct publishing is disabled by SOCIAL_PUBLISHING_ENABLED.",
        missingEnv: missing,
        optionalEnv: config.optionalEnv,
      };
    }

    if (!approvedByRule) {
      return {
        id: platform,
        label: config.label,
        status: "blocked",
        detail:
          "Direct publishing requires SOCIAL_AUTO_APPROVE=true or a human approval adapter.",
        missingEnv: missing,
        optionalEnv: config.optionalEnv,
      };
    }

    if (missing.length > 0) {
      return {
        id: platform,
        label: config.label,
        status: "blocked",
        detail: `Missing required environment variables: ${missing.join(", ")}.`,
        missingEnv: missing,
        optionalEnv: config.optionalEnv,
      };
    }

    return {
      id: platform,
      label: config.label,
      status: "ready",
      detail: config.publishNote,
      optionalEnv: config.optionalEnv,
    };
  });
}

async function postGraph(
  pathname: string,
  params: Record<string, string>,
): Promise<GraphResponse> {
  const response = await providerFetch(`${GRAPH_API_BASE}${pathname}`, {
    method: "POST",
    body: new URLSearchParams(params),
  });
  const payload = (await response.json()) as GraphResponse;
  if (!response.ok || payload.error) {
    throw new ProviderError(
      payload.error?.message || `Meta Graph API returned ${response.status}`,
      "rejected",
    );
  }
  return payload;
}

function trimToPlatform(text: string, platform: SocialPlatform): string {
  const limit = SOCIAL_PLATFORM_CONFIGS[platform].captionLimit;
  if (!limit || text.length <= limit) return text;
  return `${text.slice(0, Math.max(0, limit - 1)).trimEnd()}…`;
}

function composePostText(
  draft: SocialPostDraft,
  platform: SocialPlatform,
): string {
  const hashtagLimit =
    SOCIAL_PLATFORM_CONFIGS[platform].hashtagLimit ?? draft.hashtags.length;
  const hashtags = draft.hashtags.slice(0, hashtagLimit).join(" ");
  const parts = [draft.body, hashtags].filter(Boolean);
  return trimToPlatform(parts.join("\n\n"), platform);
}

async function publishFacebook(
  draft: SocialPostDraft,
): Promise<PublishAttempt> {
  const pageId = process.env.META_PAGE_ID;
  const accessToken = process.env.META_PAGE_ACCESS_TOKEN;
  const missing = missingEnv(SOCIAL_PLATFORM_CONFIGS.facebook.requiredEnv);

  if (missing.length > 0 || !pageId || !accessToken) {
    return {
      platform: "facebook",
      status: "skipped",
      note: `Missing required environment variables: ${missing.join(", ")}.`,
    };
  }

  try {
    const payload = await postGraph(`/${pageId}/feed`, {
      message: draft.body,
      link: draft.link,
      access_token: accessToken,
    });

    return {
      platform: "facebook",
      status: "published",
      note: "Published to Facebook Page feed.",
      platformPostId: payload.id ?? payload.post_id,
    };
  } catch (error) {
    return providerFailure("facebook", error);
  }
}

async function publishInstagram(
  draft: SocialPostDraft,
): Promise<PublishAttempt> {
  const accountId = process.env.INSTAGRAM_BUSINESS_ACCOUNT_ID;
  const accessToken = process.env.META_PAGE_ACCESS_TOKEN;
  const imageUrl = process.env.SOCIAL_DEFAULT_IMAGE_URL || draft.mediaUrl;
  const config = SOCIAL_PLATFORM_CONFIGS.instagram;
  const missing = missingEnv(config.requiredEnv);

  if (missing.length > 0 || !accountId || !accessToken) {
    return {
      platform: "instagram",
      status: "skipped",
      note: `Missing required environment variables: ${missing.join(", ")}.`,
    };
  }

  if (!imageUrl) {
    return {
      platform: "instagram",
      status: "skipped",
      note: "Missing Instagram media URL. Set SOCIAL_DEFAULT_IMAGE_URL or use a generated draft mediaUrl.",
    };
  }

  try {
    const caption = composePostText(draft, "instagram");
    const container = await postGraph(`/${accountId}/media`, {
      image_url: imageUrl,
      caption,
      ...(draft.altText ? { alt_text: draft.altText.slice(0, 1000) } : {}),
      access_token: accessToken,
    });

    if (!container.id) {
      throw new ProviderError(
        "Instagram media container did not return an id.",
        "rejected",
      );
    }

    const published = await postGraph(`/${accountId}/media_publish`, {
      creation_id: container.id,
      access_token: accessToken,
    });

    return {
      platform: "instagram",
      status: "published",
      note: "Published to Instagram Business account.",
      platformPostId: published.id,
    };
  } catch (error) {
    return providerFailure("instagram", error);
  }
}

async function publishLinkedIn(
  draft: SocialPostDraft,
): Promise<PublishAttempt> {
  const accessToken = process.env.LINKEDIN_ACCESS_TOKEN;
  const authorUrn = process.env.LINKEDIN_AUTHOR_URN;
  const version = process.env.LINKEDIN_VERSION || "202604";
  const missing = missingEnv(SOCIAL_PLATFORM_CONFIGS.linkedin.requiredEnv);

  if (missing.length > 0 || !accessToken || !authorUrn) {
    return {
      platform: "linkedin",
      status: "skipped",
      note: `Missing required environment variables: ${missing.join(", ")}.`,
    };
  }

  try {
    const response = await providerFetch(
      "https://api.linkedin.com/rest/posts",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json",
          "Linkedin-Version": version,
          "X-Restli-Protocol-Version": "2.0.0",
        },
        body: JSON.stringify({
          author: authorUrn,
          commentary: composePostText(draft, "linkedin"),
          visibility: "PUBLIC",
          distribution: {
            feedDistribution: "MAIN_FEED",
            targetEntities: [],
            thirdPartyDistributionChannels: [],
          },
          lifecycleState: "PUBLISHED",
          isReshareDisabledByAuthor: false,
        }),
      },
    );

    const body = await response.text();
    if (!response.ok) {
      throw new ProviderError(
        body || `LinkedIn API returned ${response.status}`,
        "rejected",
      );
    }

    return {
      platform: "linkedin",
      status: "published",
      note: "Published to LinkedIn.",
      platformPostId: response.headers.get("x-restli-id") ?? undefined,
    };
  } catch (error) {
    return providerFailure("linkedin", error);
  }
}

async function publishX(draft: SocialPostDraft): Promise<PublishAttempt> {
  const accessToken = process.env.X_USER_ACCESS_TOKEN;
  const missing = missingEnv(SOCIAL_PLATFORM_CONFIGS.x.requiredEnv);

  if (missing.length > 0 || !accessToken) {
    return {
      platform: "x",
      status: "skipped",
      note: `Missing required environment variables: ${missing.join(", ")}.`,
    };
  }

  try {
    const response = await providerFetch("https://api.x.com/2/tweets", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        text: composePostText(draft, "x"),
      }),
    });
    const payload = (await response.json()) as XPostResponse;
    if (!response.ok || payload.errors?.length) {
      const detail = payload.errors
        ?.map((error) => error.detail || error.title)
        .filter(Boolean)
        .join("; ");
      throw new ProviderError(
        detail || `X API returned ${response.status}`,
        "rejected",
      );
    }

    return {
      platform: "x",
      status: "published",
      note: "Published to X.",
      platformPostId: payload.data?.id,
    };
  } catch (error) {
    return providerFailure("x", error);
  }
}

const PLATFORM_PUBLISHERS: Record<
  SocialPlatform,
  (draft: SocialPostDraft) => Promise<PublishAttempt>
> = {
  facebook: publishFacebook,
  instagram: publishInstagram,
  linkedin: publishLinkedIn,
  x: publishX,
};

function skippedAttempt(
  platform: SocialPlatform,
  note: string,
): PublishAttempt {
  return {
    platform,
    status: "skipped",
    note,
  };
}

function preflightAttempt(draft: SocialPostDraft): PublishAttempt | null {
  const config = SOCIAL_PLATFORM_CONFIGS[draft.platform];
  const missing = missingEnv(config.requiredEnv);
  if (missing.length > 0) {
    return skippedAttempt(
      draft.platform,
      `Missing required environment variables: ${missing.join(", ")}.`,
    );
  }
  if (
    draft.platform === "instagram" &&
    !draft.mediaUrl &&
    !process.env.SOCIAL_DEFAULT_IMAGE_URL
  ) {
    return skippedAttempt(
      draft.platform,
      "Missing Instagram media URL. Set SOCIAL_DEFAULT_IMAGE_URL or provide draft.mediaUrl.",
    );
  }
  return null;
}

function applyAttemptsToQueue(
  queue: SocialPostDraft[],
  attempts: PublishAttempt[],
  approvedByRule: boolean,
): SocialPostDraft[] {
  return queue.map((draft) => {
    const attempt = attempts.find((item) => item.platform === draft.platform);
    if (!attempt) return draft;
    return {
      ...draft,
      approvalStatus: approvedByRule
        ? "approved_by_rule"
        : draft.approvalStatus,
      publishStatus: attempt.status,
      platformPostId: attempt.platformPostId,
      publishNote: attempt.note,
    };
  });
}

export async function publishSeoAgencyRun(
  run: KwinSeoAgencyRun,
): Promise<PublishingResult> {
  const enabled = publishingEnabled();
  const approvedByRule = autoApproveEnabled();

  if (!enabled) {
    const attempts = run.socialQueue.map((draft) =>
      skippedAttempt(
        draft.platform,
        "SOCIAL_PUBLISHING_ENABLED is not true; content was generated as a draft.",
      ),
    );
    return {
      attempts,
      socialQueue: applyAttemptsToQueue(run.socialQueue, attempts, false),
    };
  }

  if (!approvedByRule) {
    const attempts = run.socialQueue.map((draft) =>
      skippedAttempt(
        draft.platform,
        "SOCIAL_AUTO_APPROVE is not true; human review is required before direct publishing.",
      ),
    );
    return {
      attempts,
      socialQueue: applyAttemptsToQueue(run.socialQueue, attempts, false),
    };
  }

  const attempts = await Promise.all(
    run.socialQueue.map(async (draft) => {
      // Validate before acquiring an irreversible idempotency reservation.
      const preflight = preflightAttempt(draft);
      if (preflight) return preflight;
      const publisher = PLATFORM_PUBLISHERS[draft.platform];
      return publishOnce(draft, run, publisher);
    }),
  );

  return {
    attempts,
    socialQueue: applyAttemptsToQueue(run.socialQueue, attempts, true),
  };
}

import { getSupabase, getSupabaseAdmin, isSupabaseConfigured } from '@/lib/server/supabase-client';
import { configuredPersistenceProvider } from '@/lib/server/persistence/provider';
