import { SEO_AGENCY_MAX_STORED_RUNS, SEO_AGENCY_STORE_FILE } from './config';
import type { KwinSeoAgencyRun } from './types';

type StoredRuns = KwinSeoAgencyRun[];

type SaveResult = {
  backend: 'supabase' | 'file';
  warning?: string;
};

