import crypto from 'crypto';
import { NextResponse } from 'next/server';
import { logger, type LogContext } from '@/lib/logger';
import { captureApiRouteException } from '@/lib/server/observability';

interface ApiRouteContext {
  requestId: string;
  startedAt: number;
}

interface ApiRouteOptions {
  method: string;
  path: string;
  context?: LogContext;
  fallbackMessage?: string;
}

export async function withApiRoute<T extends NextResponse>(
  options: ApiRouteOptions,
  handler: (ctx: ApiRouteContext) => Promise<T>
): Promise<T | NextResponse> {
  const requestId = crypto.randomUUID();
  const startedAt = Date.now();

  logger.logRequest(options.method, options.path, requestId);

  try {
    const response = await handler({ requestId, startedAt });
    logger.logResponse(options.method, options.path, response.status, Date.now() - startedAt, requestId);
    return response;
  } catch (error) {
      const normalizedError = error instanceof Error ? error : new Error('Unknown API route error');
    logger.error(
      `Unhandled API route failure: ${options.method} ${options.path}`,
        normalizedError,
      options.context,
      requestId
    );
      captureApiRouteException(normalizedError, {
        method: options.method,
        path: options.path,
        requestId,
        context: options.context,
      });
    logger.logResponse(options.method, options.path, 500, Date.now() - startedAt, requestId);

    return NextResponse.json(
      {
        error: options.fallbackMessage || 'Unexpected server error. Please try again.',
        requestId,
      },
      { status: 500 }
    );
  }
}

import crypto from 'crypto';
import { cookies } from 'next/headers';

export const SESSION_COOKIE = 'kwin_session';
const SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function getSecret() {
  return process.env.KWIN_AUTH_SECRET || 'dev-only-secret-change-me';
}

function base64Url(input: Buffer | string) {
  return Buffer.from(input)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function sign(input: string) {
  return base64Url(crypto.createHmac('sha256', getSecret()).update(input).digest());
}

export async function hashPassword(password: string) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = await new Promise<string>((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, derivedKey) => {
      if (err) return reject(err);
      resolve(derivedKey.toString('hex'));
    });
  });

  return { salt, hash };
}

export async function verifyPassword(password: string, salt: string, expectedHash: string) {
  const hash = await new Promise<string>((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, derivedKey) => {
      if (err) return reject(err);
      resolve(derivedKey.toString('hex'));
    });
  });

  const a = Buffer.from(hash, 'hex');
  const b = Buffer.from(expectedHash, 'hex');
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

type SessionPayload = {
  uid: string;
  email: string;
  name: string;
  exp: number;
};

export function createSessionToken(uid: string, email: string, name: string) {
  const payload: SessionPayload = {
    uid,
    email,
    name,
    exp: Date.now() + SESSION_TTL_MS,
  };
  const encodedPayload = base64Url(JSON.stringify(payload));
  const signature = sign(encodedPayload);
  return `${encodedPayload}.${signature}`;
}

export function verifySessionToken(token: string | undefined | null): SessionPayload | null {
  if (!token) return null;

  const [encodedPayload, signature] = token.split('.');
  if (!encodedPayload || !signature) return null;

  const expectedSig = sign(encodedPayload);
  if (signature !== expectedSig) return null;

  try {
    const payload = JSON.parse(Buffer.from(encodedPayload, 'base64').toString('utf8')) as SessionPayload;
    if (!payload.exp || payload.exp < Date.now()) return null;
    return payload;
  } catch {
    return null;
  }
}

export async function getSessionFromCookie() {
  const cookieStore = await cookies();
  const raw = cookieStore.get(SESSION_COOKIE)?.value;
  return verifySessionToken(raw);
}

const blockedTerms = ['spam', 'scam', 'fraud', 'abuse'];

export function hasBlockedTerm(input: string) {
  const lower = input.toLowerCase();
  return blockedTerms.some((term) => lower.includes(term));
}

export function validateTitle(title: string) {
  if (!title || title.trim().length < 5) return 'Title must be at least 5 characters.';
  if (title.length > 140) return 'Title must be 140 characters or less.';
  if (hasBlockedTerm(title)) return 'Title contains blocked language.';
  return null;
}

export function validateBody(text: string) {
  if (!text || text.trim().length < 10) return 'Message must be at least 10 characters.';
  if (text.length > 2000) return 'Message must be 2000 characters or less.';
  if (hasBlockedTerm(text)) return 'Message contains blocked language.';
  return null;
}

export const CONTACT_EMAIL = process.env.CONTACT_EMAIL ?? 'hello@kwin-city.com';
export const CONTACT_ROUTE = '/api/contact';
export const CONTACT_RATE_LIMIT = {
  scope: 'contact-form',
  limit: 3,
  windowMs: 60_000,
} as const;

export const CONTACT_FIELD_LIMITS = {
  name: 120,
  email: 200,
  persona: 60,
  message: 1000,
  minMessage: 20,
} as const;

export type ContactPayload = {
  name?: unknown;
  email?: unknown;
  persona?: unknown;
