import { NextResponse } from 'next/server';
import { getRateLimitHeaders } from '@/lib/server/security';
import type { RateLimitResult } from '@/lib/server/security';

export function buildContactResponseHeaders(
  requestId: string,
  rateLimit: RateLimitResult
): Headers {
  const headers = new Headers({
    'Cache-Control': 'no-store',
    'X-Request-Id': requestId,
  });

  for (const [key, value] of Object.entries(getRateLimitHeaders(rateLimit))) {
    headers.set(key, value);
  }

  return headers;
}

export function createContactResponse(
  body: Record<string, unknown>,
  requestId: string,
  rateLimit: RateLimitResult,
  init?: ResponseInit
) {
  const headers = buildContactResponseHeaders(requestId, rateLimit);
  const extraHeaders = new Headers(init?.headers);

  extraHeaders.forEach((value, key) => {
    headers.set(key, value);
  });

  return NextResponse.json(
    {
      ...body,
      requestId,
    },
    {
      ...init,
      headers,
    }
  );
}

import { CONTACT_EMAIL } from './config';
import { buildContactEmailPayload } from './email-template';
import type { ContactSubmission } from './config';

export class ContactDeliveryError extends Error {
  statusCode?: number;
  responseBody?: string;

  constructor(message: string, options?: { statusCode?: number; responseBody?: string }) {
    super(message);
    this.name = 'ContactDeliveryError';
    this.statusCode = options?.statusCode;
    this.responseBody = options?.responseBody;
  }
}

export type ContactDeliveryResult =
  | {
      kind: 'logged';
      recipient: string;
      submission: ContactSubmission;
    }
  | {
      kind: 'sent';
      recipient: string;
    };

export async function deliverContactSubmission(
  submission: ContactSubmission
): Promise<ContactDeliveryResult> {
  const apiKey = process.env.RESEND_API_KEY;

  if (!apiKey) {
    return {
      kind: 'logged',
      recipient: CONTACT_EMAIL,
      submission,
    };
  }

  const payload = buildContactEmailPayload(submission, CONTACT_EMAIL);
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    throw new ContactDeliveryError('Resend rejected contact submission', {
      statusCode: response.status,
      responseBody: await response.text(),
    });
  }

  return {
    kind: 'sent',
    recipient: CONTACT_EMAIL,
  };
}

import { removeDangerousPatterns, sanitizeEmail } from '@/lib/sanitizer';
import { CONTACT_FIELD_LIMITS } from './config';
import type { ContactPayload, ContactSubmission } from './config';

export type ContactValidationResult =
  | { kind: 'accepted'; submission: ContactSubmission }
  | { kind: 'spam' }
  | { kind: 'invalid'; error: string };

export function sanitiseContactField(value: unknown, maxLen: number): string {
  if (typeof value !== 'string') return '';

  return removeDangerousPatterns(value)
    .replace(/[<>"'`]/g, '')
    .replace(/\r\n/g, '\n')
    .trim()
    .slice(0, maxLen);
}

export function validateContactPayload(body: ContactPayload): ContactValidationResult {
  if (body.website) {
    return { kind: 'spam' };
  }

  const name = sanitiseContactField(body.name, CONTACT_FIELD_LIMITS.name);
  const email = sanitizeEmail(sanitiseContactField(body.email, CONTACT_FIELD_LIMITS.email));
  const message = sanitiseContactField(body.message, CONTACT_FIELD_LIMITS.message);
  const persona =
    sanitiseContactField(body.persona, CONTACT_FIELD_LIMITS.persona) || 'Visitor';

  if (!name || !email || !message) {
    return {
      kind: 'invalid',
      error: 'Name, email, and message are all required.',
    };
  }

  if (message.length < CONTACT_FIELD_LIMITS.minMessage) {
    return {
      kind: 'invalid',
      error: 'Please share a little more detail so we can respond usefully.',
    };
  }

  return {
    kind: 'accepted',
    submission: {
      name,
      email,
      persona,
      message,
    },
  };
}

import type {
  DatabaseDiscussionPostRow,
  DiscussionPost,
  DiscussionReply,
} from '../models';
import { readJsonFile, writeJsonFile } from '../store';
import { getSupabase } from '../supabase-client';
import { mapPostRow } from './mappers';

export async function getAllPosts(): Promise<DiscussionPost[]> {
  const supabase = getSupabase();

  if (supabase) {
    try {
      const { data: posts, error: postsError } = await supabase
        .from('discussion_posts')
        .select('*')
        .order('created_at', { ascending: false });

      if (postsError) {
        console.error('Supabase getAllPosts error:', postsError);
      } else if (posts) {
        const postsWithReplies: DiscussionPost[] = [];

        for (const post of posts) {
          const { data: replies, error: repliesError } = await supabase
            .from('discussion_replies')
            .select('*')
            .eq('post_id', post.id)
            .order('created_at', { ascending: true });

          if (repliesError) {
            console.error('Supabase getReplies error:', repliesError);
          }

          postsWithReplies.push(mapPostRow(post, replies || []));
        }

        return postsWithReplies;
      }
    } catch (error) {
      console.error('Supabase getAllPosts exception:', error);
    }
  }

  return readJsonFile<DiscussionPost[]>('community.json', []);
}

export async function getPostById(postId: string): Promise<DiscussionPost | null> {
  const supabase = getSupabase();

  if (supabase) {
    try {
      const { data: post, error: postError } = await supabase
        .from('discussion_posts')
        .select('*')
        .eq('id', postId)
        .single();

      if (postError) {
        if (postError.code !== 'PGRST116') {
          console.error('Supabase getPostById error:', postError);
        }
      } else if (post) {
        const { data: replies, error: repliesError } = await supabase
          .from('discussion_replies')
          .select('*')
          .eq('post_id', postId)
          .order('created_at', { ascending: true });

        if (repliesError) {
          console.error('Supabase getReplies error:', repliesError);
        }

        return mapPostRow(post, replies || []);
      }
    } catch (error) {
      console.error('Supabase getPostById exception:', error);
    }
  }

  const posts = await readJsonFile<DiscussionPost[]>('community.json', []);
  return posts.find((post) => post.id === postId) || null;
}

export async function createPost(post: DiscussionPost): Promise<void> {
  const supabase = getSupabase();

  if (supabase) {
    try {
      const { error } = await supabase.from('discussion_posts').insert([
        {
          id: post.id,
          author: post.author,
          title: post.title,
          text: post.text,
          likes: post.likes,
          created_at: post.createdAt,
        },
      ]);

      if (error) {
        console.error('Supabase createPost error:', error);
        throw error;
      }

      return;
    } catch (error) {
      console.error('Supabase createPost exception:', error);
    }
  }

  const posts = await readJsonFile<DiscussionPost[]>('community.json', []);
  posts.push(post);
  await writeJsonFile('community.json', posts);
}

export async function updatePost(postId: string, updates: Partial<DiscussionPost>): Promise<void> {
  const supabase = getSupabase();

  if (supabase) {
    try {
      const updateData: Partial<DatabaseDiscussionPostRow> = {};
      if (updates.title !== undefined) updateData.title = updates.title;
      if (updates.text !== undefined) updateData.text = updates.text;
      if (updates.likes !== undefined) updateData.likes = updates.likes;

      const { error } = await supabase.from('discussion_posts').update(updateData).eq('id', postId);

      if (error) {
        console.error('Supabase updatePost error:', error);
        throw error;
      }

      return;
    } catch (error) {
      console.error('Supabase updatePost exception:', error);
    }
  }

  const posts = await readJsonFile<DiscussionPost[]>('community.json', []);
  const postIndex = posts.findIndex((post) => post.id === postId);
  if (postIndex !== -1) {
    posts[postIndex] = { ...posts[postIndex], ...updates };
    await writeJsonFile('community.json', posts);
  }
}

export async function addReplyToPost(postId: string, reply: DiscussionReply): Promise<void> {
  const supabase = getSupabase();

  if (supabase) {
    try {
      const { error } = await supabase.from('discussion_replies').insert([
        {
          id: reply.id,
          post_id: postId,
          author: reply.author,
          text: reply.text,
          created_at: reply.createdAt,
        },
      ]);

      if (error) {
        console.error('Supabase addReplyToPost error:', error);
        throw error;
      }

      return;
    } catch (error) {
      console.error('Supabase addReplyToPost exception:', error);
    }
  }

  const posts = await readJsonFile<DiscussionPost[]>('community.json', []);
  const post = posts.find((item) => item.id === postId);
  if (post) {
    post.replies.push(reply);
    await writeJsonFile('community.json', posts);
