  status: ExportJob['status'];
  export_type: ExportJob['exportType'];
  created_at: string;
  expires_at: string | null;
  file_url: string | null;
};

type ExportJobsTableClient = {
  insert: (values: unknown[]) => Promise<{ error: SupabaseErrorLike }>;
  select: (columns: string) => {
    eq: (column: string, value: string) => {
      single: () => Promise<{ data: ExportJobRow | null; error: SupabaseErrorLike }>;
    };
  };
};

type ExportSupabaseLooseClient = {
  from: (table: 'value_add_export_jobs') => ExportJobsTableClient;
};

const STORE_FILE = 'value-add-export-jobs.json';
const TTL_MS = 1000 * 60 * 60;

export async function createExportJob(request: ExportJobRequest): Promise<ExportJob> {
  const now = Date.now();
  const id = crypto.randomUUID();
  const createdAt = new Date(now).toISOString();
  const expiresAt = new Date(now + TTL_MS).toISOString();

  const job: ExportJob = {
    id,
    status: 'queued',
    exportType: request.exportType,
    createdAt,
    expiresAt,
  };

  const supabase = getSupabase();
  if (supabase) {
    try {
      const client = supabase as unknown as ExportSupabaseLooseClient;
      const payload = {
        id,
        export_type: request.exportType,
        filters: request.filters ?? {},
        status: 'queued',
        created_at: createdAt,
        expires_at: expiresAt,
      };

      const { error } = await client.from('value_add_export_jobs').insert([payload]);
      if (!error) {
        return job;
      }

      console.error('Supabase createExportJob error:', error);
    } catch (error) {
      console.error('Supabase createExportJob exception:', error);
    }
  }

  const jobs = await readJsonFile<ExportJobRecord[]>(STORE_FILE, []);
  jobs.push({
    ...job,
    filters: request.filters,
  });
  await writeJsonFile(STORE_FILE, jobs);

  return job;
}

export async function findExportJob(jobId: string): Promise<ExportJob | null> {
  const supabase = getSupabase();
  if (supabase) {
    try {
      const client = supabase as unknown as ExportSupabaseLooseClient;
      const { data, error } = await client
        .from('value_add_export_jobs')
        .select('*')
        .eq('id', jobId)
        .single();

      if (error) {
        if (error.code !== 'PGRST116') {
          console.error('Supabase findExportJob error:', error);
        }
      } else if (data) {
        if (data.expires_at && Date.parse(data.expires_at) < Date.now()) {
          return null;
        }

        return {
          id: data.id,
          status: data.status,
          exportType: data.export_type,
          createdAt: data.created_at,
          expiresAt: data.expires_at ?? undefined,
          fileUrl: data.file_url ?? undefined,
        };
      }
    } catch (error) {
      console.error('Supabase findExportJob exception:', error);
    }
  }

  const jobs = await readJsonFile<ExportJobRecord[]>(STORE_FILE, []);
  const index = jobs.findIndex((job) => job.id === jobId);
  if (index === -1) {
    return null;
  }

  const job = jobs[index];
  if (job.expiresAt && Date.parse(job.expiresAt) < Date.now()) {
    jobs.splice(index, 1);
    await writeJsonFile(STORE_FILE, jobs);
    return null;
  }

  return {
    id: job.id,
    status: job.status,
    exportType: job.exportType,
    createdAt: job.createdAt,
    expiresAt: job.expiresAt,
    fileUrl: job.fileUrl,
  };
}

import crypto from 'crypto';
import { readJsonFile, writeJsonFile } from '../store';
import { getSupabaseAdmin } from '../supabase-client';
import type { OpportunityLead, OpportunityRequest } from '@/types/value-add';

const STORE_FILE = 'value-add-opportunity-leads.json';

type OpportunityLeadRow = {
  id: string;
  role: OpportunityLead['role'];
  requirement: string;
  budget_band: string | null;
  created_at: string;
  status: OpportunityLead['status'];
};

type SupabaseErrorLike = { code?: string } | null;

type OpportunityLeadsTableClient = {
  insert: (values: unknown[]) => Promise<{ error: SupabaseErrorLike }>;
  select: (columns: string) => {
    order: (column: string, options: { ascending: boolean }) => {
      limit: (count: number) => Promise<{ data: OpportunityLeadRow[] | null; error: SupabaseErrorLike }>;
    };
  };
};

type OpportunitiesSupabaseLooseClient = {
  from: (table: 'value_add_opportunity_leads') => OpportunityLeadsTableClient;
};

export async function createOpportunityLeadRecord(input: OpportunityRequest): Promise<OpportunityLead> {
  const lead: OpportunityLead = {
    id: crypto.randomUUID(),
    role: input.role,
    requirement: input.requirement,
    budgetBand: input.budgetBand,
    createdAt: new Date().toISOString(),
    status: 'new',
  };

  // Opportunity submissions contain private contact details. RLS intentionally
  // denies browser/anon access; the API is the sole writer and uses the
  // server-only service-role client after origin, rate-limit, and CSRF checks.
  const supabase = getSupabaseAdmin();
  if (supabase) {
    try {
      const client = supabase as unknown as OpportunitiesSupabaseLooseClient;
      const payload = {
        id: lead.id,
        name: input.name,
        email: input.email,
        role: lead.role,
        requirement: lead.requirement,
        budget_band: lead.budgetBand ?? null,
        status: lead.status,
        created_at: lead.createdAt,
      };

      const { error } = await client.from('value_add_opportunity_leads').insert([payload]);
      if (!error) {
        return lead;
      }

      console.error('Supabase createOpportunityLeadRecord error:', error);
    } catch (error) {
      console.error('Supabase createOpportunityLeadRecord exception:', error);
    }
  }

  const leads = await readJsonFile<OpportunityLead[]>(STORE_FILE, []);
  leads.push(lead);
  await writeJsonFile(STORE_FILE, leads);
  return lead;
}

export async function listOpportunityLeadRecords(limit: number): Promise<OpportunityLead[]> {
  const normalizedLimit = Number.isFinite(limit) && limit > 0 ? Math.min(Math.floor(limit), 100) : 20;

  const supabase = getSupabaseAdmin();
  if (supabase) {
    try {
      const client = supabase as unknown as OpportunitiesSupabaseLooseClient;
      const { data, error } = await client
        .from('value_add_opportunity_leads')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(normalizedLimit);

      if (!error && Array.isArray(data)) {
        return data.map((row) => ({
          id: row.id,
          role: row.role,
          requirement: row.requirement,
          budgetBand: row.budget_band ?? undefined,
          createdAt: row.created_at,
          status: row.status,
        }));
      }

      if (error) {
        console.error('Supabase listOpportunityLeadRecords error:', error);
      }
    } catch (error) {
      console.error('Supabase listOpportunityLeadRecords exception:', error);
    }
  }

  const leads = await readJsonFile<OpportunityLead[]>(STORE_FILE, []);
  return leads
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    .slice(0, normalizedLimit);
}

