type ApiRouteErrorPayload = {
  method: string;
  path: string;
  requestId: string;
  context?: Record<string, unknown>;
};

type ApmProvider = 'none' | 'sentry' | 'datadog';

type SentryLike = {
  captureException?: (error: Error, payload?: unknown) => void;
};

type DatadogLike = {
  captureException?: (error: Error, payload?: unknown) => void;
};

function resolveProvider(): ApmProvider {
  const raw = (process.env.KWIN_APM_PROVIDER || 'none').trim().toLowerCase();
  if (raw === 'sentry' || raw === 'datadog') {
    return raw;
  }
  return 'none';
}

function captureWithSentry(error: Error, payload: ApiRouteErrorPayload): void {
  const sentry = (globalThis as { Sentry?: SentryLike }).Sentry;
  if (!sentry?.captureException) {
    return;
  }

  sentry.captureException(error, {
    tags: {
      route: payload.path,
      method: payload.method,
    },
    extra: {
      requestId: payload.requestId,
      ...(payload.context || {}),
    },
  });
}

function captureWithDatadog(error: Error, payload: ApiRouteErrorPayload): void {
  const datadog = (globalThis as { DD_APM?: DatadogLike }).DD_APM;
  if (!datadog?.captureException) {
    return;
  }

  datadog.captureException(error, {
    route: payload.path,
    method: payload.method,
    requestId: payload.requestId,
    ...(payload.context || {}),
  });
}

/**
 * Optional APM bridge.
 * - Works as a no-op when no external APM SDK is configured.
 * - Preserves requestId correlation when an SDK is available.
 */
export function captureApiRouteException(error: Error, payload: ApiRouteErrorPayload): void {
  const provider = resolveProvider();
  if (provider === 'sentry') {
    captureWithSentry(error, payload);
    return;
  }

  if (provider === 'datadog') {
    captureWithDatadog(error, payload);
  }
}

/**
 * Provider-neutral persistence contracts.
 *
 * Domain services depend on these ports; Supabase, Postgres, DynamoDB, or a
 * file store implement them in provider-specific adapters. Keep SDK-specific
 * types out of this directory and out of domain models.
 */

export type PersistenceProviderId = "file" | "supabase" | (string & {});

export type PersistenceHealth = {
  provider: PersistenceProviderId;
  available: boolean;
  durable: boolean;
  detail?: string;
};

export interface PersistenceProvider {
  readonly id: PersistenceProviderId;
  health(): PersistenceHealth;
}

export interface Repository<
  Entity,
  Id,
  Create = Entity,
  Update = Partial<Entity>,
> {
  findById(id: Id): Promise<Entity | null>;
  create(input: Create): Promise<Entity>;
  update(id: Id, input: Update): Promise<Entity | null>;
}

/** A small, portable port for append-only operational records. */
export interface AppendOnlyRepository<Record> {
  append(record: Record): Promise<void>;
  list(options?: { limit?: number }): Promise<Record[]>;
}

export * from "./contracts";
export {
  configuredPersistenceProvider,
  getPersistenceHealth,
} from "./provider";

import type {
  PersistenceHealth,
  PersistenceProvider,
  PersistenceProviderId,
} from "./contracts";

const FILE_PROVIDER: PersistenceProvider = {
  id: "file",
  health: () => ({
    provider: "file",
    available: true,
    durable: process.env.NODE_ENV !== "production",
    detail: "Local JSON fallback; not durable on serverless deployments.",
  }),
};

export function configuredPersistenceProvider(): PersistenceProviderId {
  const configured =
    process.env.KWIN_PERSISTENCE_PROVIDER?.trim().toLowerCase();
  if (configured === "supabase") return "supabase";
  if (configured === "file") return "file";

  // Preserve the existing zero-config behavior: credentials select Supabase
  // unless an operator explicitly requests the file provider.
  if (
    process.env.KWIN_SUPABASE_URL &&
    (process.env.KWIN_SUPABASE_ANON_KEY ||
      process.env.KWIN_SUPABASE_SERVICE_ROLE_KEY)
  ) {
    return "supabase";
  }
  return "file";
}

export function getPersistenceHealth(): PersistenceHealth {
  if (configuredPersistenceProvider() === "supabase") {
    const available = Boolean(
      process.env.KWIN_SUPABASE_URL &&
      process.env.KWIN_SUPABASE_SERVICE_ROLE_KEY,
    );
    return {
      provider: "supabase",
      available,
      durable: available,
      detail: available
        ? undefined
        : "Supabase requires KWIN_SUPABASE_URL and KWIN_SUPABASE_SERVICE_ROLE_KEY.",
    };
  }

  return FILE_PROVIDER.health();
}

import crypto from 'crypto';
import type { NextRequest } from 'next/server';

type RateLimitConfig = {
  scope: string;
  limit: number;
  windowMs: number;
};

type RateEntry = {
  count: number;
  resetAt: number;
};

export type RateLimitResult = {
  limited: boolean;
  limit: number;
  remaining: number;
  resetAt: number;
  retryAfterSeconds: number;
};

const rateMap = new Map<string, RateEntry>();

export const CSRF_COOKIE = 'kwin_csrf';
export const CSRF_HEADER = 'x-csrf-token';

export function createCsrfToken() {
  return crypto.randomBytes(24).toString('hex');
}

function purgeExpiredRateEntries(now: number) {
  for (const [key, entry] of rateMap.entries()) {
    if (now > entry.resetAt) {
      rateMap.delete(key);
    }
  }
}

export function getClientIp(req: NextRequest) {
  return (
    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
    req.headers.get('x-real-ip') ||
    'unknown'
  );
}

export function checkRateLimit(req: NextRequest, config: RateLimitConfig): RateLimitResult {
  const key = `${config.scope}:${getClientIp(req)}`;
  const now = Date.now();
  purgeExpiredRateEntries(now);
  const current = rateMap.get(key);

  if (!current || now > current.resetAt) {
    const resetAt = now + config.windowMs;
    rateMap.set(key, { count: 1, resetAt });
    return {
      limited: false,
      limit: config.limit,
      remaining: Math.max(config.limit - 1, 0),
      resetAt,
      retryAfterSeconds: Math.ceil(config.windowMs / 1000),
    };
  }

  if (current.count >= config.limit) {
    return {
      limited: true,
      limit: config.limit,
      remaining: 0,
      resetAt: current.resetAt,
      retryAfterSeconds: Math.max(Math.ceil((current.resetAt - now) / 1000), 1),
    };
  }

  current.count += 1;
  return {
    limited: false,
    limit: config.limit,
    remaining: Math.max(config.limit - current.count, 0),
    resetAt: current.resetAt,
    retryAfterSeconds: Math.max(Math.ceil((current.resetAt - now) / 1000), 1),
  };
}

export function isRateLimited(req: NextRequest, config: RateLimitConfig) {
  return checkRateLimit(req, config).limited;
}

export function getRateLimitHeaders(result: RateLimitResult): Record<string, string> {
  return {
    'X-RateLimit-Limit': String(result.limit),
    'X-RateLimit-Remaining': String(result.remaining),
    'X-RateLimit-Reset': String(Math.floor(result.resetAt / 1000)),
    'Retry-After': String(result.retryAfterSeconds),
  };
}

export function isSameOrigin(req: NextRequest) {
  const origin = req.headers.get('origin');
  if (!origin) return true;

  const proto = req.headers.get('x-forwarded-proto') || 'http';
  const host = req.headers.get('x-forwarded-host') || req.headers.get('host');
  if (!host) return false;

  const expected = `${proto}://${host}`;
  return origin === expected;
}

export function hasValidCsrf(req: NextRequest, cookieValue: string | undefined) {
  const header = req.headers.get(CSRF_HEADER);
  if (!header || !cookieValue) return false;

  const a = Buffer.from(header);
  const b = Buffer.from(cookieValue);
  if (a.length !== b.length) return false;

  return crypto.timingSafeEqual(a, b);
}

import { promises as fs } from 'fs';
import path from 'path';

function resolveDataDir() {
  const explicitDir = process.env.KWIN_DATA_DIR;
  if (explicitDir) return explicitDir;

  // Serverless functions can write only to /tmp at runtime.
  if (process.env.NETLIFY || process.env.VERCEL || process.env.AWS_LAMBDA_FUNCTION_NAME) {
    return path.join('/tmp', 'kwin-city-portal', '.data');
  }

  return path.join(process.cwd(), '.data');
}

const DATA_DIR = resolveDataDir();

async function ensureDataDir() {
  await fs.mkdir(DATA_DIR, { recursive: true });
}

function filePath(name: string) {
  return path.join(DATA_DIR, name);
}

export async function readJsonFile<T>(name: string, fallback: T): Promise<T> {
  const fullPath = filePath(name);

  try {
    await ensureDataDir();
    const raw = await fs.readFile(fullPath, 'utf8');
    return JSON.parse(raw) as T;
  } catch {
    // Best-effort seed for first run; ignore write failures on locked filesystems.
    try {
      await writeJsonFile(name, fallback);
    } catch {
      // no-op
    }
    return fallback;
  }
}

export async function writeJsonFile<T>(name: string, data: T): Promise<void> {
  await ensureDataDir();
  const fullPath = filePath(name);
  await fs.writeFile(fullPath, JSON.stringify(data, null, 2), 'utf8');
}

import { createClient, type SupabaseClient as BaseSupabaseClient } from "@supabase/supabase-js";
import type { Database } from "./models";
import { configuredPersistenceProvider } from "./persistence";

export type SupabaseClient = BaseSupabaseClient<Database>;

let supabaseClient: SupabaseClient | null = null;
let supabaseInitError: string | null = null;
let supabaseAdminClient: SupabaseClient | null = null;
let supabaseAdminInitError: string | null = null;

export function initSupabase(): SupabaseClient | null {
  if (supabaseClient !== null) return supabaseClient;
  if (supabaseInitError !== null) return null;

  if (configuredPersistenceProvider() !== "supabase") {
    supabaseInitError = "File persistence is selected.";
    return null;
  }

  const url = process.env.KWIN_SUPABASE_URL;
  const anonKey = process.env.KWIN_SUPABASE_ANON_KEY;

  if (!url || !anonKey) {
    supabaseInitError = "Supabase not configured. Using file-based storage.";
    return null;
  }

  try {
    supabaseClient = createClient(url, anonKey, {
      auth: { persistSession: false },
    });
    return supabaseClient;
  } catch (error) {
    supabaseInitError = `Supabase initialization failed: ${error}. Using file-based storage.`;
    return null;
  }
}

export function getSupabase(): SupabaseClient | null {
  return initSupabase();
}

export function initSupabaseAdmin(): SupabaseClient | null {
  if (supabaseAdminClient !== null) return supabaseAdminClient;
  if (supabaseAdminInitError !== null) return null;

  if (configuredPersistenceProvider() !== "supabase") {
    supabaseAdminInitError = "File persistence is selected.";
    return null;
  }

  const url = process.env.KWIN_SUPABASE_URL;
  const serviceRoleKey = process.env.KWIN_SUPABASE_SERVICE_ROLE_KEY;

  if (!url || !serviceRoleKey) {
    supabaseAdminInitError = "Supabase service role is not configured.";
    return null;
  }

  try {
    supabaseAdminClient = createClient(url, serviceRoleKey, {
      auth: { persistSession: false },
    });
    return supabaseAdminClient;
  } catch (error) {
    supabaseAdminInitError = `Supabase admin initialization failed: ${error}.`;
    return null;
  }
}

export function getSupabaseAdmin(): SupabaseClient | null {
  return initSupabaseAdmin();
}

export function isSupabaseConfigured(): boolean {
  return (
    configuredPersistenceProvider() === "supabase" &&
    !!process.env.KWIN_SUPABASE_URL &&
    !!process.env.KWIN_SUPABASE_ANON_KEY
  );
}

import type { AccessibilityQuery, AccessibilityResult } from '@/types/value-add';

const BASE_MINUTES_BY_MODE: Record<AccessibilityQuery['mode'], number> = {
  road: 48,
  transit: 64,
  air: 28,
};

export function calculateAccessibility(query: AccessibilityQuery): {
  result: AccessibilityResult;
  sourceIds: string[];
} {
  const mode = query.mode;
  const base = BASE_MINUTES_BY_MODE[mode];

  const destinationBias = query.destination?.toLowerCase().includes('airport') ? -9 : 0;
  const estimatedMinutes = Math.max(8, base + destinationBias);
  const projectedMinutes = query.includeProjected ? Math.max(6, estimatedMinutes - 7) : undefined;
  const deltaMinutes = projectedMinutes != null ? estimatedMinutes - projectedMinutes : undefined;

  return {
    result: {
      estimatedMinutes,
      projectedMinutes,
      deltaMinutes,
      assumptions: [
        'Travel estimates are model-based directional ranges, not live traffic predictions.',
        'Projected time assumes corridor upgrades reach planned service levels.',
      ],
    },
    sourceIds: ['aviation', 'strr', 'irr'],
  };
}

