        page.locator('h1, h2, h3').first().waitFor({ state: 'visible', timeout: 15000 }),
      ]).catch(() => null);

      const hasMain = await page
        .locator('main, [role="main"]')
        .first()
        .isVisible()
        .catch(() => false);
      const hasHeading = await page
        .locator('h1, h2, h3')
        .first()
        .isVisible()
        .catch(() => false);

      expect(hasMain || hasHeading).toBe(true);
      expect(runtimeErrors).toEqual([]);
    });
  }
});

