.principle-number { display: grid; place-items: center; width: 2.2rem; height: 2.2rem; border-radius: 50%; background: var(--sky); color: #075b9b; font-size: 0.78rem; font-weight: 850; }
.principle p { margin: 0.18rem 0 0; color: var(--ink-muted); font-size: 0.93rem; }

.section { margin-top: 3.4rem; }
.section-heading { display: flex; align-items: end; justify-content: space-between; gap: 1rem; margin-bottom: 1.2rem; }
.section-heading p { max-width: 535px; margin: 0; color: var(--ink-muted); }

.journeys { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.journey, .route-card { position: relative; display: flex; flex-direction: column; min-height: 210px; padding: 1.4rem; border: 1px solid var(--line); border-radius: 18px; background: var(--surface); box-shadow: 0 5px 18px rgba(13,38,72,0.035); }
.journey:nth-child(2) { background: linear-gradient(145deg, #fff 20%, #f1fbff); }
.journey:nth-child(3) { background: linear-gradient(145deg, #fff 20%, #fff9ee); }
.journey .tag, .route-card .tag { display: inline-flex; align-self: flex-start; margin-bottom: 1.4rem; border-radius: 999px; background: #edf4fa; padding: 0.28rem 0.56rem; color: #47617f; font-size: 0.7rem; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; }
.journey p, .route-card p { margin-bottom: 1rem; color: var(--ink-muted); font-size: 0.94rem; }
.text-link { margin-top: auto; color: #075b9b; font-weight: 800; text-decoration: none; }
.text-link::after { content: " →"; }
.text-link:hover { text-decoration: underline; }

.route-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 0.9rem; }
.route-card { min-height: 156px; }
.route-card .tag { margin-bottom: 0.65rem; }

.resource-bar { display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 1rem; margin-top: 3.4rem; padding: 1.35rem; border: 1px solid #c9dceb; border-radius: 18px; background: #edf7fc; }
.resource-bar h2 { margin-bottom: 0.35rem; font-size: 1.27rem; }
.resource-bar p { margin-bottom: 0; color: #415d78; }
.resource-links { display: flex; flex-wrap: wrap; align-content: center; gap: 0.65rem; }
.resource-links a { border: 1px solid #bdd3e6; border-radius: 999px; background: #fff; padding: 0.46rem 0.7rem; text-decoration: none; font-size: 0.84rem; font-weight: 750; }

.disclosure { margin-top: 2.5rem; padding: 1rem 1.15rem; border-left: 3px solid var(--gold); background: #fffaf0; color: #5d4b28; font-size: 0.91rem; }
.disclosure strong { color: #3d2e11; }

footer { border-top: 1px solid var(--line); background: #fff; }
.footer-inner { display: flex; justify-content: space-between; gap: 1rem; padding: 1.5rem 0; color: #607086; font-size: 0.86rem; }
.footer-inner p { margin: 0; }

.subpage-hero { padding: 3.3rem 0 2.4rem; background: linear-gradient(132deg, #071c39, #0d4168); color: #fff; }
.subpage-hero h1 { max-width: 800px; margin-bottom: 0.8rem; font-size: clamp(2rem, 4vw, 3.5rem); }
.subpage-hero p { max-width: 680px; margin-bottom: 0; color: #c8dced; font-size: 1.08rem; }
.compact-main { padding-top: 2.6rem; }
.info-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.info-card { padding: 1.35rem; border: 1px solid var(--line); border-radius: 16px; background: #fff; }
.info-card ul { margin: 0.85rem 0 0; padding-left: 1.15rem; }
.info-card li { margin: 0.55rem 0; }
.back-link { display: inline-flex; margin-top: 2.5rem; font-weight: 800; }

@media (max-width: 800px) {
  .hero-inner, .intro, .journeys, .resource-bar, .info-grid { grid-template-columns: 1fr; }
  .hero-inner { gap: 1.5rem; padding: 3.6rem 0 3rem; }
  .signal-card { max-width: 600px; }
  .section-heading { display: block; }
  .section-heading p { margin-top: 0.5rem; }
  .route-grid { grid-template-columns: 1fr; }
}

@media (max-width: 560px) {
  .site-shell { width: min(100% - 1.35rem, 1160px); }
  .topbar { min-height: 62px; }
  .brand small, .site-nav a:not(.nav-cta) { display: none; }
  .hero-actions { display: grid; }
  .button { width: 100%; }
  main { padding-top: 2.7rem; }
  .journey, .route-card { min-height: auto; }
  .footer-inner { display: block; }
  .footer-inner p + p { margin-top: 0.4rem; }
}

