/* KWIN City PWA service worker.
 * Public documents are network-first, immutable assets are cache-first, and
 * private/API/RSC traffic is never cached. No third-party request is intercepted.
 */

const APP_PREFIX = "kwin-pwa";
const CACHE_VERSION = "v4";
const PRECACHE = `${APP_PREFIX}-${CACHE_VERSION}-precache`;
const PAGES = `${APP_PREFIX}-${CACHE_VERSION}-pages`;
const ASSETS = `${APP_PREFIX}-${CACHE_VERSION}-assets`;
const IMAGES = `${APP_PREFIX}-${CACHE_VERSION}-images`;
const OFFLINE_URL = "/offline";
const NETWORK_TIMEOUT_MS = 4_500;
const CACHE_LIMITS = { pages: 35, assets: 120, images: 80 };

const PRECACHE_URLS = [
  OFFLINE_URL,
  "/manifest.webmanifest",
  "/icon",
  "/apple-icon",
];

const NEVER_CACHE_PREFIXES = [
  "/api/",
  "/account",
  "/community",
  "/auth",
  "/admin",
];

self.addEventListener("install", (event) => {
  event.waitUntil(precacheAppShell());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(Promise.all([removeOldAppCaches(), self.clients.claim()]));
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data?.type === "CLEAR_RUNTIME_CACHES") {
    event.waitUntil(Promise.all([caches.delete(PAGES), caches.delete(IMAGES)]));
  }
});

self.addEventListener("fetch", (event) => {
  if (!shouldHandle(event.request)) return;

  const request = event.request;
  const url = new URL(request.url);

  if (request.mode === "navigate") {
    event.respondWith(navigationNetworkFirst(request));
    return;
  }

  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, ASSETS, CACHE_LIMITS.assets));
    return;
  }

  if (request.destination === "image") {
    event.respondWith(cacheFirst(request, IMAGES, CACHE_LIMITS.images));
  }
});

function shouldHandle(request) {
  if (request.method !== "GET") return false;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return false;
  if (request.headers.has("range")) return false;
  if (request.headers.get("RSC") === "1" || url.searchParams.has("_rsc")) {
    return false;
  }
  return !NEVER_CACHE_PREFIXES.some(
    (prefix) =>
      url.pathname === prefix.replace(/\/$/, "") ||
      url.pathname.startsWith(prefix),
  );
}

async function precacheAppShell() {
  const cache = await caches.open(PRECACHE);
  await Promise.allSettled(
    PRECACHE_URLS.map(async (url) => {
      const response = await fetch(new Request(url, { cache: "reload" }));
      if (url === OFFLINE_URL || isCacheablePageResponse(response)) {
        await cache.put(url, response);
      }
    }),
  );
}

async function navigationNetworkFirst(request) {
  try {
    const response = await fetchWithTimeout(request, NETWORK_TIMEOUT_MS);
    if (isCacheablePage(request, response)) {
      const cache = await caches.open(PAGES);
      await cache.put(request, response.clone());
      await enforceLimit(cache, CACHE_LIMITS.pages);
    }
    return response;
  } catch {
    const cache = await caches.open(PAGES);
    const cached = await cache.match(request);
    if (cached) return cached;
    return (
      (await caches.match(OFFLINE_URL)) ||
      new Response("Offline", {
        status: 503,
        headers: { "Content-Type": "text/plain; charset=utf-8" },
      })
    );
  }
}

async function cacheFirst(request, cacheName, limit) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (isCacheable(response)) {
      await cache.put(request, response.clone());
      await enforceLimit(cache, limit);
    }
    return response;
  } catch {
    return new Response("Unavailable", { status: 503 });
  }
}

function fetchWithTimeout(request, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return fetch(request, { signal: controller.signal }).finally(() =>
    clearTimeout(timer),
  );
}

function isCacheable(response) {
  return response?.ok && (response.type === "basic" || response.type === "default");
}

function isCacheablePage(request, response) {
  if (!isCacheablePageResponse(response)) return false;
  if (response.headers.has("set-cookie")) return false;
  return !NEVER_CACHE_PREFIXES.some((prefix) =>
    new URL(request.url).pathname.startsWith(prefix),
  );
}

function isCacheablePageResponse(response) {
  if (!isCacheable(response)) return false;
  const cacheControl = response.headers.get("cache-control") || "";
  return !/no-store|private/i.test(cacheControl);
}

async function enforceLimit(cache, maxEntries) {
  const keys = await cache.keys();
  const excess = keys.length - maxEntries;
  if (excess > 0) {
    await Promise.all(keys.slice(0, excess).map((key) => cache.delete(key)));
  }
}

async function removeOldAppCaches() {
  const names = await caches.keys();
  const current = new Set([PRECACHE, PAGES, ASSETS, IMAGES]);
  await Promise.all(
    names
      .filter((name) => name.startsWith(`${APP_PREFIX}-`) && !current.has(name))
      .map((name) => caches.delete(name)),
  );
}

import { writeFile } from 'node:fs/promises';

const now = new Date().toISOString();
const startedAt = process.env.VERIFICATION_STARTED_AT || now;
const runId = process.env.GITHUB_RUN_ID || `local-${Date.now()}`;
const attempt = process.env.GITHUB_RUN_ATTEMPT || '1';
const sha = (process.env.GITHUB_SHA || '').toLowerCase();
const runUrl = process.env.GITHUB_SERVER_URL && process.env.GITHUB_REPOSITORY
  ? `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${runId}` : undefined;
const trigger = process.env.GITHUB_EVENT_NAME === 'schedule' ? 'schedule' : process.env.GITHUB_EVENT_NAME === 'workflow_dispatch' ? 'workflow_dispatch' : 'manual';

function outcome(name) {
  const value = process.env[name] || 'skipped';
  return value === 'success' ? 'passed' : value === 'failure' ? 'failed' : value === 'cancelled' ? 'cancelled' : 'skipped';
}

function build(suite, policyVersion, definitions) {
  const controls = definitions.map(([id, env]) => ({ id, required: true, outcome: outcome(env) }));
  const passed = controls.every((control) => control.outcome === 'passed');
  return {
    idempotencyKey: `github:${runId}:${attempt}:${suite}`,
    suite, outcome: passed ? 'passed' : 'failed', policyVersion, startedAt, completedAt: now,
    ...(sha ? { commitSha: sha } : {}), environment: 'ci', provider: 'github_actions', providerRunId: `${runId}:${attempt}`,
    ...(runUrl ? { providerRunUrl: runUrl } : {}), trigger, controls,
    manifest: { repository: process.env.GITHUB_REPOSITORY, ref: process.env.GITHUB_REF, workflow: process.env.GITHUB_WORKFLOW, runAttempt: attempt },
    ...(!passed ? { failureCode: `${suite}-controls-failed`, failureSummary: `Required controls did not all pass: ${controls.filter((control) => control.outcome !== 'passed').map((control) => control.id).join(', ')}` } : {}),
  };
}

await writeFile('factual-audit-evidence.json', JSON.stringify(build('factual_audit', 'factual-audit/v1', [
  ['operations-current', 'OUTCOME_OPERATIONS'], ['primary-source-health', 'OUTCOME_PRIMARY'],
  ['source-registry', 'OUTCOME_SOURCES'], ['content-staleness', 'OUTCOME_STALENESS'],
  ['factual-integrity', 'OUTCOME_FACTS'], ['discovery-signals', 'OUTCOME_DISCOVERY'],
]), null, 2));

await writeFile('execution-status-evidence.json', JSON.stringify(build('execution_status', 'execution-status/v1', [
  ['node-runtime', 'OUTCOME_NODE'], ['type-check', 'OUTCOME_TYPES'], ['unit-tests', 'OUTCOME_TESTS'],
  ['migration-verification', 'OUTCOME_MIGRATIONS'], ['vercel-config', 'OUTCOME_VERCEL'],
  ['pwa-verification', 'OUTCOME_PWA'], ['production-build', 'OUTCOME_BUILD'],
]), null, 2));

console.log('Built sanitized factual and execution evidence manifests.');

#!/usr/bin/env node

import { readFileSync } from 'node:fs';

const MAX_AGE_DAYS = 14;
const auditPath = 'docs/FACTUAL_CLAIM_AUDIT.md';
const audit = readFileSync(auditPath, 'utf8');
const match = audit.match(/^Date:\s*(\d{4}-\d{2}-\d{2})$/m);
if (!match) throw new Error(`${auditPath} must declare a YYYY-MM-DD audit date.`);

const auditedAt = new Date(`${match[1]}T00:00:00Z`);
if (Number.isNaN(auditedAt.getTime())) throw new Error(`Invalid audit date: ${match[1]}`);
const ageDays = Math.floor((Date.now() - auditedAt.getTime()) / 86_400_000);
if (ageDays > MAX_AGE_DAYS) {
  throw new Error(`Factual claim audit is ${ageDays} days old (maximum ${MAX_AGE_DAYS}). Review and update ${auditPath}.`);
}

console.log(JSON.stringify({ status: 'healthy', auditPath, auditedAt: match[1], ageDays, maxAgeDays: MAX_AGE_DAYS }, null, 2));

// @vitest-environment node

import { describe, expect, it } from 'vitest';
import { verifyDiscoveryLayout } from './lib/discovery-signals-policy.mjs';

const valid = `
  verification: { google: GOOGLE_SITE_VERIFICATION },
  other: {
    "ai-policy": \`\${SITE_URL}/ai.txt\`,
    "llms-policy": \`\${SITE_URL}/llms.txt\`,
  }
`;

describe('discovery layout policy', () => {
  it('accepts semantic signals independent of quote style and whitespace', () => {
    expect(verifyDiscoveryLayout(valid).signals).toEqual(['llms-policy', 'ai-policy', 'google-verification']);
    expect(verifyDiscoveryLayout(valid.replaceAll('"', "'").replace('google:', 'google :')).status).toBe('healthy');
  });

  it.each([
    ['llms-policy', valid.replace('"llms-policy"', '"missing-llms"')],
    ['ai-policy', valid.replace('"ai-policy"', '"missing-ai"')],
    ['google-verification', valid.replace('GOOGLE_SITE_VERIFICATION', '"hard-coded-value"')],
  ])('fails closed when %s is absent', (signal, layout) => {
    expect(() => verifyDiscoveryLayout(layout)).toThrow(signal);
  });

  it('rejects an empty layout', () => {
    expect(() => verifyDiscoveryLayout('')).toThrow(/empty or unreadable/);
  });
});

const REQUIRED_LAYOUT_SIGNALS = Object.freeze([
  { id: 'llms-policy', pattern: /["']llms-policy["']\s*:\s*`\$\{SITE_URL\}\/llms\.txt`/ },
  { id: 'ai-policy', pattern: /["']ai-policy["']\s*:\s*`\$\{SITE_URL\}\/ai\.txt`/ },
  { id: 'google-verification', pattern: /google\s*:\s*GOOGLE_SITE_VERIFICATION/ },
]);

export function verifyDiscoveryLayout(layout) {
  if (typeof layout !== 'string' || !layout.trim()) throw new Error('app/layout.tsx is empty or unreadable.');
  for (const signal of REQUIRED_LAYOUT_SIGNALS) {
    if (!signal.pattern.test(layout)) throw new Error(`app/layout.tsx is missing required discovery signal: ${signal.id}`);
  }
  return { status: 'healthy', signals: REQUIRED_LAYOUT_SIGNALS.map(({ id }) => id) };
}

export const SOURCE_HOST_POLICIES = Object.freeze({
  'news.google.com': 'discovery',
  'www.bing.com': 'discovery',
  'rbi.org.in': 'directInstitutional',
  'www.thehindu.com': 'directPublisher',
  'timesofindia.indiatimes.com': 'directPublisher',
});

export const OFFICIAL_QUERY_DOMAINS = Object.freeze([
  'investkarnataka.co.in',
  'kiadb.karnataka.gov.in',
  'kla.kar.nic.in',
  'karnataka.gov.in',
  'industry.karnataka.gov.in',
  'kppp.karnataka.gov.in',
  'bengalururural.nic.in',
]);

function extractFeedUrls(xml) {
  if (typeof xml !== 'string') throw new Error('The source registry must be XML text.');
  return [...xml.matchAll(/\bxmlUrl\s*=\s*"([^"]+)"/g)].map((match) =>
    match[1].replaceAll('&amp;', '&'),
  );
}

function parseTrustedUrl(value) {
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error(`Invalid source URL blocked: ${value}`);
  }
  if (url.protocol !== 'https:') throw new Error(`Non-HTTPS source blocked: ${value}`);
  if (url.username || url.password) throw new Error(`Credential-bearing source URL blocked: ${value}`);
  if (url.port && url.port !== '443') throw new Error(`Non-standard source port blocked: ${value}`);
  if (url.hash) throw new Error(`Fragment-bearing source URL blocked: ${value}`);
  return url;
}

function isOfficialDiscovery(url, policy) {
  if (policy !== 'discovery') return false;
  const query = (url.searchParams.get('q') ?? '').toLowerCase();
  return OFFICIAL_QUERY_DOMAINS.some((domain) => {
    const escaped = domain.replaceAll('.', '\\.');
    return new RegExp(`(?:^|\\s|\\()site:${escaped}(?:$|\\s|\\))`, 'i').test(query);
  });
}

export function verifySourceRegistry(xml) {
  const values = extractFeedUrls(xml);
  if (!values.length) throw new Error('The source registry contains no feeds.');

  const seen = new Set();
  const unknownHosts = new Set();
  const duplicateUrls = new Set();
  const inventory = { directInstitutional: 0, directPublisher: 0, officialDiscovery: 0, discovery: 0 };

  for (const value of values) {
    const url = parseTrustedUrl(value);
    const hostname = url.hostname.toLowerCase();
    const policy = SOURCE_HOST_POLICIES[hostname];
    if (!policy) unknownHosts.add(hostname);

    const canonical = url.toString();
    if (seen.has(canonical)) duplicateUrls.add(canonical);
    seen.add(canonical);

    if (isOfficialDiscovery(url, policy)) inventory.officialDiscovery += 1;
    else if (policy) inventory[policy] += 1;
  }

  if (unknownHosts.size) throw new Error(`Unreviewed source hosts: ${[...unknownHosts].sort().join(', ')}`);
  if (duplicateUrls.size) throw new Error(`Duplicate source URLs: ${[...duplicateUrls].sort().join(', ')}`);
  if (!inventory.directInstitutional && !inventory.officialDiscovery) {
    throw new Error('At least one direct or source-filtered institutional signal is required.');
  }

  return {
    status: 'healthy',
    sourceCount: values.length,
    inventory,
    policy: 'Discovery feeds are monitoring signals only; direct sources retain provenance priority.',
  };
}

