import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const SITE_URL = process.env.SITE_URL ?? 'https://kwin-city.com';
const SITE_ORIGIN = new URL(SITE_URL).origin;
const SITE_BASE_URL = SITE_URL.replace(/\/$/, '');
const HOST = new URL(SITE_ORIGIN).host;
const SITEMAP_URL = process.env.INDEXNOW_SITEMAP_URL ?? `${SITE_BASE_URL}/sitemap.xml`;
const ENDPOINT = process.env.INDEXNOW_ENDPOINT ?? 'https://api.indexnow.org/indexnow';
const KEY = process.env.INDEXNOW_KEY ?? '57AA00BD-4FE7-48FB-932C-A0EBDB93354B';
const KEY_LOCATION = process.env.INDEXNOW_KEY_LOCATION ?? `${SITE_BASE_URL}/${KEY}.txt`;
const KEY_FILE_DIRECTORY = process.env.INDEXNOW_KEY_FILE_DIRECTORY ?? 'public';
const DRY_RUN = process.env.INDEXNOW_DRY_RUN === '1';

function parseSitemapUrls(xml) {
  return [
    ...new Set(
      [...xml.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/gi)]
        .map((match) => match[1].trim())
        .filter((url) => new URL(url).host === HOST),
    ),
  ];
}

function verifyLocalKeyFile() {
  const keyFile = resolve(process.cwd(), KEY_FILE_DIRECTORY, `${KEY}.txt`);
  if (!existsSync(keyFile)) {
    throw new Error(`Missing IndexNow verification file: ${KEY_FILE_DIRECTORY}/${KEY}.txt`);
  }

  if (readFileSync(keyFile, 'utf8').trim() !== KEY) {
    throw new Error(`${KEY_FILE_DIRECTORY}/${KEY}.txt must contain exactly the IndexNow key.`);
  }
}

async function getSitemapUrls() {
  const response = await fetch(SITEMAP_URL, {
    headers: { accept: 'application/xml,text/xml;q=0.9,*/*;q=0.1' },
  });

  if (!response.ok) {
    throw new Error(`Could not fetch ${SITEMAP_URL}: HTTP ${response.status}`);
  }

  const urls = parseSitemapUrls(await response.text());
  if (urls.length === 0) {
    throw new Error(`No ${HOST} URLs were found in ${SITEMAP_URL}.`);
  }

  return urls;
}

async function run() {
  verifyLocalKeyFile();
  const urlList = await getSitemapUrls();
  const payload = { host: HOST, key: KEY, keyLocation: KEY_LOCATION, urlList };

  console.log(`Prepared ${urlList.length} URL(s) from ${SITEMAP_URL}.`);

  if (DRY_RUN) {
    console.log('DRY RUN: IndexNow request was not sent.');
    return;
  }

  const response = await fetch(ENDPOINT, {
    method: 'POST',
    headers: { 'content-type': 'application/json; charset=utf-8' },
    body: JSON.stringify(payload),
  });
  const responseBody = (await response.text()).trim();

  if (response.status !== 200 && response.status !== 202) {
    const detail = responseBody ? ` — ${responseBody}` : '';
    throw new Error(`IndexNow submission failed: HTTP ${response.status}${detail}`);
  }

  console.log(`IndexNow submission accepted: HTTP ${response.status} for ${urlList.length} URL(s).`);
}

run().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});

import { createHmac, randomUUID } from 'node:crypto';
import { readFile } from 'node:fs/promises';

function required(name) {
  const value = process.env[name]?.trim();
  if (!value) throw new Error(`${name} must be configured.`);
  return value;
}

const manifestPath = process.argv[2];
if (!manifestPath) throw new Error('Usage: node scripts/submit-operational-evidence.mjs <manifest.json>');
const body = await readFile(manifestPath, 'utf8');
const manifest = JSON.parse(body);
const timestamp = String(Date.now());
const nonce = randomUUID().replaceAll('-', '');
const secret = required('OPERATIONS_EVIDENCE_SECRET');
const signature = createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
const baseUrl = (process.env.SITE_BASE_URL?.trim() || new URL(required('SITE_REFRESH_URL')).origin).replace(/\/$/, '');
const response = await fetch(`${baseUrl}/api/operations/verifications`, {
  method: 'POST', body, signal: AbortSignal.timeout(30_000),
  headers: { 'content-type': 'application/json', 'x-kwin-evidence-timestamp': timestamp, 'x-kwin-evidence-nonce': nonce, 'x-kwin-evidence-signature': signature },
});
const responseBody = await response.text();
if (!response.ok) throw new Error(`Evidence submission failed: HTTP ${response.status}${responseBody ? ` — ${responseBody}` : ''}`);
let receipt;
try { receipt = JSON.parse(responseBody); } catch { throw new Error('Evidence endpoint returned invalid JSON.'); }
if (receipt?.success !== true || typeof receipt.attemptId !== 'string') throw new Error('Evidence endpoint returned an invalid receipt.');
if (manifest.outcome === 'passed' && receipt.qualified !== true) throw new Error(`Evidence was recorded but did not qualify: attemptId=${receipt.attemptId}`);
console.log(`Operational evidence recorded: attemptId=${receipt.attemptId}, rail=${receipt.rail}, qualified=${receipt.qualified}, idempotent=${receipt.idempotent}.`);

#!/usr/bin/env node

import { readdirSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import path from 'node:path';

const databaseUrl = process.env.DATABASE_URL?.trim();
if (!databaseUrl) throw new Error('DATABASE_URL must point to an isolated PostgreSQL test database.');

function psql(args, label) {
  const result = spawnSync('psql', [databaseUrl, '--set', 'ON_ERROR_STOP=1', '--no-psqlrc', ...args], {
    cwd: process.cwd(),
    encoding: 'utf8',
    env: process.env,
  });
  if (result.status !== 0) {
    throw new Error(`${label} failed.\n${result.stdout || ''}${result.stderr || ''}`.trim());
  }
  return result.stdout.trim();
}

psql(['--command', `
  DO $$ BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
  DO $$ BEGIN CREATE ROLE authenticated NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
  DO $$ BEGIN CREATE ROLE service_role NOLOGIN BYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
`], 'Supabase role bootstrap');

const directory = path.join(process.cwd(), 'supabase', 'migrations');
const migrations = readdirSync(directory).filter((name) => name.endsWith('.sql')).sort();

for (const pass of [1, 2]) {
  for (const migration of migrations) {
    psql(['--file', path.join(directory, migration)], `Migration ${migration} (pass ${pass})`);
  }
}

const scalar = (sql, label) => psql(['--tuples-only', '--no-align', '--command', sql], label).trim();
const idempotencyKey = `ci:migration-contract:${randomUUID()}`;
const completedAt = new Date();
const startedAt = new Date(completedAt.getTime() - 60_000).toISOString();
const completedAtIso = completedAt.toISOString();
const expiresAt = new Date(completedAt.getTime() + 14 * 86_400_000).toISOString();

const schemaResult = scalar(`
  SELECT CASE WHEN COUNT(*) = 3 THEN 'schema-ok' ELSE 'schema-missing' END
  FROM information_schema.tables
  WHERE table_schema = 'public'
    AND table_name IN (
      'operational_verification_attempts',
      'operational_freshness_qualifications',
      'operational_scheduler_heartbeats'
    );
`, 'Schema contract');

const recordSql = `
  SELECT inserted::text
  FROM public.record_operational_verification(
    '${idempotencyKey}', repeat('a', 64), 'execution_status', 'passed', true,
    'ci-v1', '${startedAt}'::timestamptz, '${completedAtIso}'::timestamptz, repeat('b', 40), 'ci', 'github_actions',
    'migration-contract', 'https://github.com/example/repository/actions/runs/1', 'manual',
    '["migration-chain","rpc-execution"]'::jsonb, '{"contract":"database"}'::jsonb,
    repeat('c', 64), NULL, NULL, 'execution_status', '${expiresAt}'::timestamptz
  );
`;

const firstInsert = scalar(recordSql, 'Atomic RPC insert contract');
const replay = scalar(recordSql, 'Atomic RPC replay contract');
const verification = [schemaResult, firstInsert, replay];

const expected = ['schema-ok', 'true', 'false'];
if (verification.join(',') !== expected.join(',')) {
  throw new Error(`Unexpected database contract result: ${verification.join(', ')}; expected ${expected.join(', ')}.`);
}

console.log(`Applied ${migrations.length} migrations twice and verified the atomic evidence RPC.`);

const DEFAULT_TIMEOUT_MS = 120_000;

function configuredValue(name) {
  const value = process.env[name]?.trim();
  if (!value) {
    throw new Error(`${name} must be configured.`);
  }
  return value;
}

export async function triggerSeoAgencyRefresh({
  refreshUrl = configuredValue('SITE_REFRESH_URL'),
  cronSecret = configuredValue('CRON_SECRET'),
  fetchImpl = fetch,
  timeoutMs = DEFAULT_TIMEOUT_MS,
  invocationId = process.env.GITHUB_RUN_ID
    ? `${process.env.GITHUB_RUN_ID}:${process.env.GITHUB_RUN_ATTEMPT || '1'}`
    : null,
} = {}) {
  const response = await fetchImpl(refreshUrl, {
    headers: {
      authorization: `Bearer ${cronSecret}`,
      'x-kwin-trigger-provider': 'github_actions',
      ...(invocationId ? { 'x-github-run-id': invocationId } : {}),
    },
    signal: AbortSignal.timeout(timeoutMs),
  });

  const bodyText = await response.text();
  let body;
  try {
    body = JSON.parse(bodyText);
  } catch {
    throw new Error(`SEO agency refresh returned invalid JSON: HTTP ${response.status}${bodyText ? ` — ${bodyText}` : ''}`);
  }

  if (!response.ok || body?.success !== true) {
    throw new Error(`SEO agency refresh failed: HTTP ${response.status}${body?.error ? ` — ${body.error}` : ''}`);
  }

  if (body.storageBackend !== 'supabase') {
    const diagnostic = body.persistence ? ` — diagnostics: ${JSON.stringify(body.persistence)}` : '';
    throw new Error(
      `SEO agency refresh did not persist to Supabase (storageBackend: ${body.storageBackend ?? 'missing'})` +
        `${body.warning ? ` — ${body.warning}` : ''}${diagnostic}`,
    );
  }

  if (body.liveInputStatus !== 'live' || body.evidence?.qualified !== true) {
    throw new Error(`SEO agency refresh completed but did not qualify freshness: liveInputStatus=${body.liveInputStatus ?? 'missing'}, evidenceQualified=${body.evidence?.qualified ?? false}${body.evidence?.warning ? ` — ${body.evidence.warning}` : ''}`);
  }

  console.log(
    `SEO agency refresh persisted to Supabase: runDate=${body.runDate}, generatedAt=${body.generatedAt}, durationMs=${body.durationMs}.`,
  );
  return body;
}

if (process.argv[1]?.endsWith('trigger-seo-agency-refresh.mjs')) {
  triggerSeoAgencyRefresh().catch((error) => {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
  });
}

