#!/usr/bin/env node

const TIMEOUT_MS = 12_000;
// This is an observability gate, not a publication gate: government and public
// institutional domains regularly have transient DNS, TLS, and bot-protection
// failures outside this repository's control. Require one independently
// reachable endpoint to detect a broken runner/network, and surface every
// individual outage as a GitHub Actions warning for follow-up.
const MIN_HEALTHY_SOURCES = 1;
const PRIMARY_SOURCES = [
  // KIADB remains the authoritative source for KWIN-specific records. Its public
  // endpoint currently has an incomplete TLS certificate chain, so it is
  // monitored directly but cannot safely be a single point of CI failure.
  { id: 'kiadb', url: 'https://kiadb.karnataka.gov.in/', required: false },
  { id: 'bmrda', url: 'https://bmrda.karnataka.gov.in/', required: false },
  { id: 'bial', url: 'https://www.bengaluruairport.com/', required: false },
  { id: 'ksndmc', url: 'https://ksndmc.karnataka.gov.in/', required: false },
];

async function probe(url) {
  const signal = AbortSignal.timeout(TIMEOUT_MS);

  try {
    const headResponse = await fetch(url, {
      method: 'HEAD',
      redirect: 'follow',
      signal,
      headers: { 'user-agent': 'kwin-always-current-health-check/1.0' },
    });

    if (headResponse.ok) {
      return headResponse;
    }
  } catch (error) {
    // Fallback to GET below.
    const headError = error instanceof Error ? error : new Error(String(error));

    try {
      return await fetch(url, {
        method: 'GET',
        redirect: 'follow',
        signal,
        headers: { 'user-agent': 'kwin-always-current-health-check/1.0', range: 'bytes=0-1024' },
      });
    } catch (getError) {
      const getMessage = getError instanceof Error ? getError.message : String(getError);
      const getCause = getError instanceof Error && getError.cause instanceof Error
        ? ` (${getError.cause.message})`
        : '';
      throw new Error(`HEAD failed: ${headError.message}; GET failed: ${getMessage}${getCause}`);
    }
  }

  return fetch(url, {
    method: 'GET',
    redirect: 'follow',
    signal,
    headers: { 'user-agent': 'kwin-always-current-health-check/1.0', range: 'bytes=0-1024' },
  });
}

async function main() {
  const checks = [];

  for (const source of PRIMARY_SOURCES) {
    try {
      const response = await probe(source.url);
      checks.push({
        id: source.id,
        url: source.url,
        required: source.required,
        healthy: response.ok,
        status: response.status,
        finalUrl: response.url,
        lastModified: response.headers.get('last-modified'),
        etag: response.headers.get('etag'),
      });
    } catch (error) {
      checks.push({
        id: source.id,
        url: source.url,
        required: source.required,
        healthy: false,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  const requiredFailures = checks.filter((check) => check.required && !check.healthy);
  const healthyCount = checks.filter((check) => check.healthy).length;

  if (requiredFailures.length > 0) {
    throw new Error(`Required primary source unavailable: ${requiredFailures.map((item) => item.id).join(', ')}`);
  }

  if (healthyCount < MIN_HEALTHY_SOURCES) {
    throw new Error(`Primary source health degraded: only ${healthyCount}/${PRIMARY_SOURCES.length} sources responded successfully.`);
  }

  const degradedChecks = checks.filter((check) => !check.healthy);
  if (degradedChecks.length > 0) {
    console.warn(`::warning::Primary-source endpoint(s) need attention: ${degradedChecks.map((item) => item.id).join(', ')}. Direct source links remain unchanged.`);
  }

  console.log(JSON.stringify({
    status: degradedChecks.length > 0 ? 'degraded-but-operational' : 'healthy',
    checkedAt: new Date().toISOString(),
    healthyCount,
    total: PRIMARY_SOURCES.length,
    minimumHealthySources: MIN_HEALTHY_SOURCES,
    checks,
  }, null, 2));
}

main();

const baseUrl = `${(process.env.PAGES_URL ?? 'https://aartisr.github.io/kwin-city-portal/').replace(/\/$/, '')}/`;
const expectedAssets = [
  ['', 'text/html'],
  ['/robots.txt', 'text/plain'],
  ['/sitemap.xml', 'application/xml'],
  ['/llms.txt', 'text/plain'],
  ['/geo-ai-index.html', 'text/html'],
  ['/seo-link-graph.html', 'text/html'],
];

const failures = [];

for (const [path, contentType] of expectedAssets) {
  const url = `${baseUrl}${path.replace(/^\//, '')}`;
  try {
    const response = await fetch(url, { redirect: 'follow' });
    const actualContentType = response.headers.get('content-type') ?? '';
    if (!response.ok || !actualContentType.includes(contentType)) {
      failures.push(`${url} returned ${response.status} (${actualContentType || 'missing content type'})`);
    }
  } catch (error) {
    failures.push(`${url} could not be fetched: ${error instanceof Error ? error.message : String(error)}`);
  }
}

if (failures.length > 0) {
  console.error(`[github-pages-publish] ${failures.join('\n[github-pages-publish] ')}`);
  process.exit(1);
}

console.log(`[github-pages-publish] OK: ${expectedAssets.length} discovery assets are reachable from ${baseUrl}`);

import { access, readFile } from "node:fs/promises";
import { constants } from "node:fs";

const requiredFiles = [
  "app/manifest.ts",
  "app/icon.tsx",
  "app/apple-icon.tsx",
  "app/offline/page.tsx",
  "app/lib/pwa/config.ts",
  "app/components/PwaRegistration.tsx",
  "app/components/PwaInstallPrompt.tsx",
  "public/sw.js",
];

await Promise.all(
  requiredFiles.map(async (file) => {
    try {
      await access(file, constants.R_OK);
    } catch {
      throw new Error(`PWA contract is missing required file: ${file}`);
    }
  }),
);

const [worker, manifest, layout, nextConfig] = await Promise.all([
  readFile("public/sw.js", "utf8"),
  readFile("app/manifest.ts", "utf8"),
  readFile("app/layout.tsx", "utf8"),
  readFile("next.config.js", "utf8"),
]);

const requirements = [
  [worker, "SKIP_WAITING", "controlled service-worker updates"],
  [worker, "CLEAR_RUNTIME_CACHES", "runtime cache reset support"],
  [worker, 'request.headers.get("RSC")', "RSC cache exclusion"],
  [worker, "NEVER_CACHE_PREFIXES", "private route exclusions"],
  [worker, "NETWORK_TIMEOUT_MS", "bounded navigation requests"],
  [worker, "CACHE_LIMITS", "bounded runtime caches"],
  [manifest, "PWA_CONFIG", "central manifest configuration"],
  [manifest, "maskable", "maskable application icon"],
  [layout, "/manifest.webmanifest", "manifest discovery metadata"],
  [layout, "appleWebApp", "Apple standalone metadata"],
  [nextConfig, "/sw.js", "service-worker revalidation headers"],
  [nextConfig, "Service-Worker-Allowed", "explicit service-worker scope"],
];

for (const [source, token, label] of requirements) {
  if (!source.includes(token))
    throw new Error(`PWA contract missing ${label}.`);
}

if (/caches\.keys\(\)[\s\S]*keys\.map\([^)]*caches\.delete/.test(worker)) {
  throw new Error("Service worker must not delete caches it does not own.");
}

console.log(
  `Verified PWA contract across ${requiredFiles.length} required files.`,
);

#!/usr/bin/env node

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const rootDir = process.cwd();
const qualityFile = path.join(rootDir, 'QUALITY_STANDARDS.md');

function run(command, label) {
  const result = spawnSync(command, {
    shell: true,
    cwd: rootDir,
    encoding: 'utf8',
    env: process.env,
    maxBuffer: 10 * 1024 * 1024,
  });

  const output = `${result.stdout || ''}${result.stderr || ''}`;
  if (result.status !== 0) {
    console.error(`\n[quality-verify] ${label} failed: ${command}`);
    console.error(output.trim());
    process.exit(result.status || 1);
  }
  return output;
}

function mustMatch(regex, input, label) {
  const match = input.match(regex);
  if (!match) {
    console.error(`\n[quality-verify] unable to parse ${label}`);
    process.exit(1);
  }
  return match;
}

if (!fs.existsSync(qualityFile)) {
  console.error(`[quality-verify] missing ${qualityFile}`);
  process.exit(1);
}

const qualityText = fs.readFileSync(qualityFile, 'utf8');

const expectedTest = mustMatch(/`npm test`: pass \((\d+) files, (\d+) tests\)/, qualityText, 'expected test counts');
const expectedRoutes = mustMatch(/`npm run e2e:smoke`: pass \((\d+) routes\)/, qualityText, 'expected e2e route count');

const expected = {
  testFiles: Number(expectedTest[1]),
  tests: Number(expectedTest[2]),
  routes: Number(expectedRoutes[1]),
};

console.log('[quality-verify] running gate commands for documentation verification...');
run('npm run type-check', 'type-check');
run('npm run lint', 'lint');
run('npm run build:ci', 'build');

const testOutput = run('npm test -- --reporter=basic', 'unit tests');
const routeOutput = run('npm run e2e:smoke', 'e2e smoke');

const actualTestFiles = Number(mustMatch(/Test Files\s+(\d+)\s+passed/i, testOutput, 'actual test file count')[1]);
const actualTests = Number(mustMatch(/Tests\s+(\d+)\s+passed/i, testOutput, 'actual test count')[1]);
const actualRoutes = Number(mustMatch(/\b(\d+)\s+passed\s*\(/i, routeOutput, 'actual e2e passed count')[1]);

const mismatches = [];
if (actualTestFiles !== expected.testFiles) {
  mismatches.push(`test files expected ${expected.testFiles} but found ${actualTestFiles}`);
}
if (actualTests !== expected.tests) {
  mismatches.push(`tests expected ${expected.tests} but found ${actualTests}`);
}
if (actualRoutes !== expected.routes) {
  mismatches.push(`e2e routes expected ${expected.routes} but found ${actualRoutes}`);
}

if (mismatches.length > 0) {
  console.error('\n[quality-verify] QUALITY_STANDARDS.md snapshot mismatch:');
  for (const mismatch of mismatches) {
    console.error(`- ${mismatch}`);
  }
  process.exit(1);
}

console.log('[quality-verify] QUALITY_STANDARDS.md is aligned with current gate outputs.');

#!/usr/bin/env node

import { readFileSync } from 'node:fs';
import { verifySourceRegistry } from './lib/source-registry-policy.mjs';

const registryPath = 'public/feeds/kwin-city-news-feeds.opml';
const xml = readFileSync(registryPath, 'utf8');
const result = verifySourceRegistry(xml);

console.log(JSON.stringify({
  ...result,
  registry: registryPath,
}, null, 2));

import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const migrationsDirectory = path.join(process.cwd(), "supabase", "migrations");
const migrationName = /^\d{4}_[a-z0-9][a-z0-9_-]*\.sql$/;
const securityDefiner = /SECURITY\s+DEFINER/gi;
const pinnedSearchPath = /SET\s+search_path\s*=\s*[a-z_][a-z0-9_]*(?:\s*,\s*[a-z_][a-z0-9_]*)*/i;

const files = (await readdir(migrationsDirectory))
  .filter((file) => file.endsWith(".sql"))
  .sort();

if (files.length === 0) {
  throw new Error(
    "No Supabase migrations found. Add a migration to supabase/migrations/.",
  );
}

for (const [index, file] of files.entries()) {
  if (!migrationName.test(file)) {
    throw new Error(
      `Invalid migration name: ${file}. Use NNNN_descriptive_name.sql.`,
    );
  }

  const sql = await readFile(path.join(migrationsDirectory, file), "utf8");
  if (!sql.trim()) throw new Error(`Migration is empty: ${file}`);

  const expectedOrdinal = String(index + 1).padStart(4, "0");
  const actualOrdinal = file.slice(0, 4);
  if (actualOrdinal !== expectedOrdinal) {
    throw new Error(
      `Migration sequence must be continuous: expected ${expectedOrdinal}_ but found ${file}.`,
    );
  }

  const definerCount = [...sql.matchAll(securityDefiner)].length;
  const searchPathCount = [...sql.matchAll(new RegExp(pinnedSearchPath.source, "gi"))].length;
  if (definerCount > searchPathCount) {
    throw new Error(
      `Every SECURITY DEFINER function must pin search_path: ${file} has ${definerCount} function(s) and ${searchPathCount} pinned path(s).`,
    );
  }
}

console.log(
  `Verified ${files.length} Supabase migration${files.length === 1 ? "" : "s"}.`,
);

import { readFileSync } from 'node:fs';

const config = JSON.parse(readFileSync('vercel.json', 'utf8'));
const crons = config.crons ?? [];
const publicRegistry = 'https://registry.npmjs.org/';

if (config.installCommand !== `yarn install --frozen-lockfile --registry ${publicRegistry}`) {
  console.error('[vercel-config] Vercel installs must explicitly use the public npm registry.');
  process.exit(1);
}

for (const configPath of ['.npmrc', '.yarnrc']) {
  const content = readFileSync(configPath, 'utf8');
  if (!content.includes(publicRegistry) || content.includes('always-auth=true')) {
    console.error(`[vercel-config] ${configPath} must retain the public, unauthenticated registry configuration.`);
    process.exit(1);
  }
}

if (!Array.isArray(crons) || crons.length === 0) {
  console.error('[vercel-cron] Expected at least one configured Vercel cron job.');
  process.exit(1);
}

for (const cron of crons) {
  // This project deploys on Vercel Hobby. Hobby accepts only a single daily
  // invocation per cron; expressions such as "*/6" cause the entire deploy to fail.
  if (typeof cron?.path !== 'string' || !cron.path.startsWith('/')) {
    console.error('[vercel-cron] Each cron path must be an absolute route.');
    process.exit(1);
  }

  if (typeof cron?.schedule !== 'string' || !/^\d{1,2}\s+\d{1,2}\s+\*\s+\*\s+\*$/.test(cron.schedule)) {
    console.error(`[vercel-cron] ${cron?.path ?? 'Cron'} must run once daily on Vercel Hobby; received: ${cron?.schedule ?? 'missing schedule'}`);
    process.exit(1);
  }
}

console.log(`[vercel-config] OK: public-registry install boundary and ${crons.length} Vercel Hobby-compatible daily cron job(s).`);

