  ON public.social_publish_reservations (platform, source_url);

DROP TRIGGER IF EXISTS set_social_publish_reservations_updated_at ON public.social_publish_reservations;
CREATE TRIGGER set_social_publish_reservations_updated_at BEFORE UPDATE ON public.social_publish_reservations
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE OR REPLACE FUNCTION public.acquire_social_publish_reservation(
  p_platform text,
  p_fingerprint text,
  p_source_url text,
  p_run_id text,
  p_lease_token uuid
)
RETURNS TABLE(acquired boolean, reservation_id uuid)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  INSERT INTO public.social_publish_reservations (
    platform, fingerprint, source_url, run_id, lease_token, lease_expires_at
  ) VALUES (
    p_platform, p_fingerprint, p_source_url, p_run_id, p_lease_token, now() + interval '15 minutes'
  )
  -- Fail closed. A timed-out provider request may still have created the post,
  -- so reservations are never reclaimed automatically. Manual replay must use
  -- a new, explicitly reviewed fingerprint.
  ON CONFLICT (platform, fingerprint) DO NOTHING
  RETURNING true, public.social_publish_reservations.id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::uuid;
  END IF;
END;
$$;

ALTER TABLE public.social_publish_reservations ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.social_publish_reservations FROM anon, authenticated;
GRANT ALL ON TABLE public.social_publish_reservations TO service_role;
REVOKE ALL ON FUNCTION public.acquire_social_publish_reservation(text, text, text, text, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.acquire_social_publish_reservation(text, text, text, text, uuid)
  TO service_role;

-- Append-only, service-role-only operational evidence for honest freshness.
CREATE TABLE IF NOT EXISTS public.operational_verification_attempts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  idempotency_key text NOT NULL UNIQUE CHECK (char_length(idempotency_key) BETWEEN 8 AND 240),
  suite text NOT NULL CHECK (suite IN ('content_refresh', 'factual_audit', 'execution_status')),
  outcome text NOT NULL CHECK (outcome IN ('passed', 'failed', 'partial', 'skipped', 'timed_out', 'indeterminate', 'cancelled')),
  qualified boolean NOT NULL DEFAULT false CHECK (NOT qualified OR outcome = 'passed'),
  policy_version text NOT NULL CHECK (char_length(policy_version) BETWEEN 3 AND 80),
  started_at timestamptz NOT NULL,
  completed_at timestamptz NOT NULL CHECK (completed_at >= started_at),
  commit_sha text CHECK (commit_sha IS NULL OR commit_sha ~ '^[0-9a-f]{40}$'),
  environment text NOT NULL CHECK (environment IN ('production', 'preview', 'ci', 'development')),
  provider text NOT NULL CHECK (provider IN ('github_actions', 'vercel_cron', 'manual', 'local')),
  provider_run_id text,
  provider_run_url text CHECK (provider_run_url IS NULL OR provider_run_url ~ '^https://'),
  trigger_name text NOT NULL CHECK (trigger_name IN ('schedule', 'workflow_dispatch', 'deployment', 'retry', 'manual', 'request')),
  controls jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(controls) = 'array'),
  manifest jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(manifest) = 'object'),
  manifest_sha256 text NOT NULL CHECK (manifest_sha256 ~ '^[0-9a-f]{64}$'),
  failure_code text,
  failure_summary text CHECK (failure_summary IS NULL OR char_length(failure_summary) <= 1000),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT operational_attempt_clock_skew CHECK (started_at <= created_at + interval '10 minutes')
);

CREATE TABLE IF NOT EXISTS public.operational_freshness_qualifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rail text NOT NULL CHECK (rail IN ('content', 'factual_audit', 'execution_status')),
  attempt_id uuid NOT NULL REFERENCES public.operational_verification_attempts(id) ON DELETE RESTRICT,
  qualified_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL CHECK (expires_at > qualified_at),
  policy_version text NOT NULL,
  commit_sha text CHECK (commit_sha IS NULL OR commit_sha ~ '^[0-9a-f]{40}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (rail, attempt_id)
);

CREATE TABLE IF NOT EXISTS public.operational_scheduler_heartbeats (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  idempotency_key text NOT NULL UNIQUE,
  provider text NOT NULL CHECK (provider IN ('github_actions', 'vercel_cron', 'manual', 'local')),
  schedule_id text NOT NULL,
  invocation_id text NOT NULL,
  outcome text NOT NULL CHECK (outcome IN ('received', 'passed', 'failed', 'partial', 'timed_out', 'indeterminate')),
  duration_ms integer CHECK (duration_ms IS NULL OR duration_ms >= 0),
  failure_code text,
  received_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz
);

CREATE INDEX IF NOT EXISTS idx_operational_attempts_suite_completed
  ON public.operational_verification_attempts (suite, completed_at DESC);
CREATE INDEX IF NOT EXISTS idx_operational_qualifications_rail_qualified
  ON public.operational_freshness_qualifications (rail, qualified_at DESC);
CREATE INDEX IF NOT EXISTS idx_operational_heartbeats_received
  ON public.operational_scheduler_heartbeats (received_at DESC);

ALTER TABLE public.operational_verification_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.operational_freshness_qualifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.operational_scheduler_heartbeats ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.operational_verification_attempts FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.operational_freshness_qualifications FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.operational_scheduler_heartbeats FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON TABLE public.operational_verification_attempts TO service_role;
GRANT SELECT, INSERT ON TABLE public.operational_freshness_qualifications TO service_role;
GRANT SELECT, INSERT, UPDATE ON TABLE public.operational_scheduler_heartbeats TO service_role;

CREATE OR REPLACE FUNCTION public.prevent_operational_evidence_mutation()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  RAISE EXCEPTION 'Operational evidence is append-only';
END;
$$;

REVOKE ALL ON FUNCTION public.prevent_operational_evidence_mutation() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS prevent_operational_attempt_mutation ON public.operational_verification_attempts;
CREATE TRIGGER prevent_operational_attempt_mutation
BEFORE UPDATE OR DELETE ON public.operational_verification_attempts
FOR EACH ROW EXECUTE FUNCTION public.prevent_operational_evidence_mutation();

DROP TRIGGER IF EXISTS prevent_operational_qualification_mutation ON public.operational_freshness_qualifications;
CREATE TRIGGER prevent_operational_qualification_mutation
BEFORE UPDATE OR DELETE ON public.operational_freshness_qualifications
FOR EACH ROW EXECUTE FUNCTION public.prevent_operational_evidence_mutation();

-- Defense in depth for operational evidence. Qualification rows must agree
-- with their immutable attempt and the policy window they claim to represent.
ALTER TABLE public.operational_verification_attempts
  DROP CONSTRAINT IF EXISTS operational_attempt_completed_clock_skew;
ALTER TABLE public.operational_verification_attempts
  ADD CONSTRAINT operational_attempt_completed_clock_skew
  CHECK (completed_at <= created_at + interval '10 minutes');

ALTER TABLE public.operational_verification_attempts
  DROP CONSTRAINT IF EXISTS operational_attempt_max_duration;
ALTER TABLE public.operational_verification_attempts
  ADD CONSTRAINT operational_attempt_max_duration
  CHECK (completed_at - started_at <= interval '24 hours');

CREATE OR REPLACE FUNCTION public.validate_operational_qualification()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  attempt public.operational_verification_attempts%ROWTYPE;
  expected_rail text;
  expected_expiry timestamptz;
BEGIN
  SELECT * INTO attempt
  FROM public.operational_verification_attempts
  WHERE id = NEW.attempt_id;

  IF NOT FOUND OR NOT attempt.qualified OR attempt.outcome <> 'passed' THEN
    RAISE EXCEPTION 'Qualification requires a qualified passed attempt';
  END IF;

  expected_rail := CASE attempt.suite
    WHEN 'content_refresh' THEN 'content'
    WHEN 'factual_audit' THEN 'factual_audit'
    WHEN 'execution_status' THEN 'execution_status'
  END;
  expected_expiry := NEW.qualified_at + CASE NEW.rail
    WHEN 'content' THEN interval '3 days'
    ELSE interval '14 days'
  END;

  IF NEW.rail <> expected_rail
     OR NEW.qualified_at <> attempt.completed_at
     OR NEW.policy_version <> attempt.policy_version
     OR NEW.commit_sha IS DISTINCT FROM attempt.commit_sha
     OR NEW.expires_at <> expected_expiry THEN
    RAISE EXCEPTION 'Qualification does not match its immutable attempt or policy window';
  END IF;

  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.validate_operational_qualification() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.validate_operational_qualification() TO service_role;

DROP TRIGGER IF EXISTS validate_operational_qualification_insert
  ON public.operational_freshness_qualifications;
CREATE TRIGGER validate_operational_qualification_insert
BEFORE INSERT ON public.operational_freshness_qualifications
FOR EACH ROW EXECUTE FUNCTION public.validate_operational_qualification();

-- Forward-only repair for environments bootstrapped before value-add tables
-- were included in the baseline. These workflows must never depend on a
-- serverless local-file fallback for durable production submissions.
CREATE TABLE IF NOT EXISTS public.value_add_alert_subscriptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email text NOT NULL,
  persona text NOT NULL,
  topics text[] NOT NULL DEFAULT '{}',
  geofilters text[] NOT NULL DEFAULT '{}',
  cadence text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.value_add_export_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  export_type text NOT NULL,
  filters jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'queued',
  file_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz
);

CREATE TABLE IF NOT EXISTS public.value_add_opportunity_leads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  email text NOT NULL,
  role text NOT NULL,
  requirement text NOT NULL,
  budget_band text,
  status text NOT NULL DEFAULT 'new',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_value_add_alerts_email ON public.value_add_alert_subscriptions(email);
CREATE INDEX IF NOT EXISTS idx_value_add_alerts_status ON public.value_add_alert_subscriptions(status);
CREATE INDEX IF NOT EXISTS idx_value_add_exports_created_at ON public.value_add_export_jobs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_value_add_exports_status ON public.value_add_export_jobs(status);
CREATE INDEX IF NOT EXISTS idx_value_add_leads_created_at ON public.value_add_opportunity_leads(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_value_add_leads_role ON public.value_add_opportunity_leads(role);

DROP TRIGGER IF EXISTS set_value_add_alerts_updated_at ON public.value_add_alert_subscriptions;
CREATE TRIGGER set_value_add_alerts_updated_at
BEFORE UPDATE ON public.value_add_alert_subscriptions
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.value_add_alert_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.value_add_export_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.value_add_opportunity_leads ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.value_add_alert_subscriptions FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.value_add_export_jobs FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.value_add_opportunity_leads FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.value_add_alert_subscriptions TO service_role;
GRANT SELECT, INSERT, UPDATE ON TABLE public.value_add_export_jobs TO service_role;
GRANT SELECT, INSERT, UPDATE ON TABLE public.value_add_opportunity_leads TO service_role;

